class _IdleCoyNotifications(list):
    """Final Idle-only guard against inherited resistance-facing notices."""
    _replacements = (
        ("MISS AUTO-CAST", "MANY-SIRED OVERRIDE"),
        ("AUTO THRUST", "MANY-SIRED'S PACE"),
        ("Pressure returns.", "Many-Sired takes the pace back."),
        ("PRESSURE RETURNS", "MANY-SIRED TAKES THE PACE BACK"),
        ("Distance gained.", "Hana gives him more."),
        ("Distance held.", "Hana stays eagerly with him."),
        ("Distance held", "Hana stays with him"),
        ("She keeps trying.", "Hana keeps going with him."),
        ("Still not enough.", "Hana is still pretending this is restraint."),
        ("BRACE HELD", "HANA STAYS WITH HIM"),
        ("GRIP LOST — RECOVER", "HANA LOSES THE RHYTHM — MANY-SIRED CONTINUES"),
        ("CONTROL NARROWS — KEEP PLAYING", "MANY-SIRED TAKES MORE CONTROL — HANA KEEPS UP"),
    )

    def append(self, value):
        text=str(value)
        idle=str(os.environ.get("LOCKKEY_IDLE_OGRE_MODE","") or "").strip().lower() in ("1","true","yes","on")
        if idle:
            for old,new in self._replacements:
                text=text.replace(old,new)
        super().append(text)

