def _lk_env_on(name: str, default: str = "0") -> bool:
    return str(os.environ.get(name, default) or default).strip().lower() in ("1", "true", "yes", "on")

def _lk_env_text(name: str, default: str = "") -> str:
    return str(os.environ.get(name, default) or default).strip()


def _lk_env_int(name: str, default: int = 0, minimum: Optional[int] = None, maximum: Optional[int] = None) -> int:
    try:
        value = int(_lk_env_text(name, str(default)) or default)
    except Exception:
        value = int(default)
    if minimum is not None:
        value = max(int(minimum), value)
    if maximum is not None:
        value = min(int(maximum), value)
    return value

