def _lk_seed_from_env() -> Optional[int]:
    raw = (
        _lk_env_text("LOCKKEY_SEED_LOCK")
        or _lk_env_text("LOCKKEY_CONTEXT_SEED")
        or _lk_env_text("LOCKKEY_SEED")
    )
    if not raw:
        return None
    try:
        return int(raw)
    except Exception:
        return abs(hash(raw)) % 1000000007


def _compact_sprites_debug_enabled() -> bool:
    """Return whether the legacy ASCII sprite layer should render.

    Despite the historical name, this is no longer debug-only by default:
    the ASCII ogre/opponent animation layer is part of the intended rhythm
    presentation, sitting on top of the restored lightmap/cell-shader layer.

    Set LOCKKEY_COMPACT_SPRITES_OFF=1 or LOCKKEY_PUNCTUATION_SPRITES_OFF=1
    to suppress it for screenshot/debug comparisons. The old *_DEBUG flags
    still force it on.
    """
    if _lk_env_on("LOCKKEY_COMPACT_SPRITES_OFF") or _lk_env_on("LOCKKEY_PUNCTUATION_SPRITES_OFF"):
        return False
    return True


def _maybe_render_compact_sprites_debug(sprites: Any, scr: Any, base_y: int, width: int) -> None:
    """Render the ASCII ogre/opponent animation layer when enabled.

    Lightmaps remain the primary figure/pose layer. A terminal wrong-hole route
    may request cosmetic bucking, but that display must never become a real
    BUCKING gameplay state or reopen the escape loop.
    """
    try:
        if _compact_sprites_debug_enabled():
            _saved_state = None
            _cosmetic_bucking = bool(getattr(sprites, "terminal_bucking_display", False))
            if _cosmetic_bucking:
                try:
                    _saved_state = sprites.pen_state
                    sprites.pen_state = PenState.BUCKING
                    sprites._rendering_cosmetic_bucking = True
                    # Animate the old locked-leg bucking body without ever
                    # entering its gameplay update/escape state. Black Wind can
                    # taper the bucking toward a near-still hold while preserving
                    # the special pose until the sequence actually resolves.
                    _buck_strength = max(0.0, min(1.0, float(
                        getattr(sprites, "terminal_bucking_strength", 1.0) or 0.0
                    )))
                    _buck_frequency = max(0.18, min(1.0, float(
                        getattr(sprites, "terminal_bucking_frequency", 1.0) or 1.0
                    )))
                    sprites.buck_phase = time.perf_counter() * (2.8 + 7.2 * _buck_frequency)
                    sprites.jiggle_amp = 0.30 + 1.70 * _buck_strength
                    sprites.jiggle_t = 1.0
                except Exception:
                    _saved_state = None
            try:
                sprites.render(scr, base_y, width)
            finally:
                if _cosmetic_bucking:
                    try:
                        sprites._rendering_cosmetic_bucking = False
                    except Exception:
                        pass
                if _saved_state is not None:
                    try:
                        sprites.pen_state = _saved_state
                    except Exception:
                        pass
        else:
            try:
                sprites.sprite_x_center = int(width) // 2
            except Exception:
                pass
    except Exception:
        pass

