# NSCL (Nervous System Context Layer)
# Data-driven: loads .bratbox/context/*.json and renders:
# - persistent banner (bottom line)
# - toast events (short-lived, stacked)
# - pose caption (when intimacy begins)
# ──────────────────────────────────────────────────────────────────

class NSCLManager:
    def __init__(self):
        self.enabled = True
        self.loaded = False
        self.base_dir: Optional[Path] = None

        self.cards = {}
        self.card_index = {}     # (stage, pattern) -> card
        self.events = {}         # id -> event dict
        self.pose_catalog = {}   # POSE_ID -> entry dict
        self.gambit_deltas = {}
        self.intent_aliases = {}

        self.state = {
            "LOC": "ROOM",
            "STAGE": "SOCIAL",
            "WARDROBE": "CLOTHED",
            "CONTACT": "NONE",
            "LEAD": "MUTUAL",
            "LANE": "QUIET",
            "CONSENT": "GREEN",
            "BADGES": [],
            "CARD_ID": "CTX_SOCIAL_A_BASE_MUTUAL",
            "POSE_ID": "",
            "POSE_CAPTION": "",
            "POWER": 1,
            "DENIAL": 0,
            "CONSEQUENCE": "CLEAN",
            "URGENCY": "NONE",
            "CONTRACTS": {},
        }
        self._prev_state = dict(self.state)

        self.toast_queue: List[Tuple[float, str]] = []   # (until, text)
        self._cooldowns: Dict[str, float] = {}           # event_id -> until
        self._last_combo = 0
        self._last_miss = 0
        self._last_stage = "SOCIAL"
        self._last_card = self.state["CARD_ID"]


        # Mask/room surfacing (toast on change + temporary line after dialogue)
        self._last_dialogue_time: float = 0.0
        self._mask_line_until: float = 0.0
        self._last_mask: str = str(self.state.get("LANE") or "")
        self._mask_shift_cd_until: float = 0.0
    def _find_base_dir(self) -> Optional[Path]:
        # 1) Explicit override
        try:
            env = (os.environ.get("LOCKKEY_CONTEXT_DIR", "") or "").strip()
            if env:
                p = Path(env).expanduser()
                if p.exists() and p.is_dir():
                    return p
        except Exception:
            pass

        # 2) .bratbox/context in cwd
        try:
            p = Path(os.getcwd()) / ".bratbox" / "context"
            if p.exists() and p.is_dir():
                return p
        except Exception:
            pass

        # 3) sibling to this file
        try:
            here = Path(__file__).resolve().parent
            p = here / ".bratbox" / "context"
            if p.exists() and p.is_dir():
                return p
        except Exception:
            pass

        return None

        cards = _load_json("context_cards.json") or {}
        events = _load_json("context_events.json") or {}
        poses = _load_json("pose_schema_defaults.json") or {}
        deltas = _load_json("gambit_deltas.json") or {}
        aliases = _load_json("intent_bucket_aliases.json") or {}
        texture_rules = _load_json("texture_rules.json") or {}
        consent_tokens = _load_json("consent_tokens.json") or {}
        canon_contracts = _load_json("canon_contracts.json") or {}


        # Index cards
        self.cards = cards
        self.card_index = {}
        try:
            for c in cards.get("cards", []):
                self.card_index[(c.get("stage"), c.get("pattern"))] = c
        except Exception:
            self.card_index = {}

        # Index events
        self.events = {}
        try:
            for e in events.get("events", []):
                eid = e.get("id")
                if eid:
                    self.events[eid] = e
        except Exception:
            self.events = {}

        # Pose catalog
        self.pose_catalog = {}
        try:
            for p in poses.get("pose_catalog", []):
                pid = p.get("pose_id")
                if pid:
                    self.pose_catalog[pid] = p
        except Exception:
            self.pose_catalog = {}

        self.gambit_deltas = deltas or {}
        self.intent_aliases = aliases or {}

        self.texture_rules = texture_rules or {}
        self.consent_tokens = consent_tokens or {}
        self.canon_contracts = canon_contracts or {}


        self.loaded = bool(self.card_index)

    def _emit(self, event_id: str, now: float, ttl_s: float = 1.25):
        # Respect cooldowns from event table if present
        cooldown_until = self._cooldowns.get(event_id, 0.0)
        if cooldown_until > now:
            return

        e = self.events.get(event_id)
        if e:
            cd = float(e.get("cooldown_s", 0.0) or 0.0)
            if cd > 0:
                self._cooldowns[event_id] = now + cd
            text = str(e.get("display") or event_id)
        else:
            text = event_id

        self.toast_queue.append((now + ttl_s, text))

        # Keep only recent toasts
        if len(self.toast_queue) > 6:
            self.toast_queue = self.toast_queue[-6:]

    def _normalize_pose_id(self, pose_name: str) -> str:
        if not pose_name:
            return ""
        # pose names in-engine are snake_case; catalog uses UPPER_SNAKE.
        pose_id = re.sub(r"[^a-zA-Z0-9_]+", "_", str(pose_name)).strip("_").upper()
        return pose_id


    def get_axis(self, key: str):
        """Authoritative axis value (or None). Safe: auto-loads JSONs."""
        if not self.loaded:
            self.load()
        if not self.loaded:
            return None
        try:
            return (self.state or {}).get(key)
        except Exception:
            return None



    def note_text_emitted(self, speaker: str, text: str):
        """Signal: a text line was printed/recorded (literal event surface).
        Extends the temporary mask line visibility window modestly.
        """
        try:
            _t = time
            now = float(_t.time())
            self._last_dialogue_time = now
            self._mask_line_until = max(float(getattr(self, "_mask_line_until", 0.0) or 0.0), now + 3.5)
        except Exception:
            pass

    def note_voice_emitted(self, speaker: str, text: str, hint: str = ""):
        """Signal: a voice clip actually played (texture surface).
        Extends the mask line window longer than text.
        Also emits occasional TEXTURE tags inferred from the played clip or text.
        """
        try:
            _t = time
            now = float(_t.time())
            self._last_dialogue_time = now
            self._mask_line_until = max(float(getattr(self, "_mask_line_until", 0.0) or 0.0), now + 6.0)

            # Lazy-init texture cooldown maps
            if not hasattr(self, "_texture_cd"):
                self._texture_cd = {}
            if not hasattr(self, "_texture_global_cd_until"):
                self._texture_global_cd_until = 0.0

            tag = self._infer_texture_tag(speaker=str(speaker or ""), text=str(text or ""), hint=str(hint or ""))
            if tag:
                # Rate-limit: one texture toast every ~2.5s globally, and ~10s per tag
                if now >= float(getattr(self, "_texture_global_cd_until", 0.0) or 0.0):
                    until = float(self._texture_cd.get(tag, 0.0) or 0.0)
                    if now >= until:
                        self.toast_queue.append((now + 1.8, f"TEXTURE: {tag}"))
                        self._texture_cd[tag] = now + 10.0
                        self._texture_global_cd_until = now + 2.5
        except Exception:
            pass


    def _infer_texture_tag(self, speaker: str, text: str, hint: str = "") -> str:
        """Heuristic texture tag inference.
        Priority: hint (resolved clip path/id) > explicit tokens in text > speaker microcues.
        This is intentionally *vague* and non-explicit: microgesture/texture only.
        """
        s = (speaker or "").upper()
        h = (hint or "").lower()
        t = (text or "").lower()

        blob = " ".join([h, t])

        # Optional external rule map: .bratbox/context/texture_rules.json
        try:
            ruleset = getattr(self, "texture_rules", {}) or {}
            for r in ruleset.get("rules", []) or []:
                tag = str(r.get("tag") or "").strip().upper()
                if not tag:
                    continue
                spk = str(r.get("speaker") or "").strip().upper()
                if spk and spk != s:
                    continue
                keys = r.get("match_any") or r.get("keys") or []
                for k in keys:
                    kk = str(k or "").lower()
                    if kk and kk in blob:
                        return tag
        except Exception:
            pass

        # Map common substrings to canonical texture tags (keep it classy)
        rules = [
            (["smilecrackle", "smile_crackle", "crackle_smile", "crackle"], "SMILE_CRACKLE"),
            (["headtilt", "head_tilt", "tilt"], "HEAD_TILT"),
            (["fingerwag", "finger_wag", "wag"], "FINGER_WAG"),
            (["leanin", "lean_in", "lean"], "LEAN_IN"),
            (["trace", "tracing", "taffy", "taffytime", "taffy_time"], "TRACE_SLOW"),
            (["humm", "hum", "mm", "mmm", "hmm", "mhmm"], "HUM"),
            (["breath", "breathy", "pant", "breathless", "gasp", "catch"], "BREATH_CATCH"),
            (["velvet"], "VELVET"),
            (["afterglow"], "AFTERGLOW"),
            (["glint"], "GLINT"),
            (["staredown", "dilated"], "STAREDOWN_DILATED"),
            (["wiggle"], "WIGGLE_IMPATIENT"),
        ]

        for keys, tag in rules:
            for k in keys:
                if k and k in blob:
                    return tag

        # Speaker-biased microcues from punctuation/markers (fallback)
        if s == "FIEND":
            if "~" in text or "—" in text:
                return "SMOOTH_DRAWL"
            if "..." in text:
                return "PAUSE_HEAVY"
        if s == "BIRDSONG":
            if "..." in text:
                return "SLOW_TRACING"
            if "!" in text:
                return "BRIGHT_ENERGY"

        return ""


    def is_bucket_allowed(self, bucket: str, stage: str, consent: str, lane: str) -> bool:
        """Gambit gating: returns True if a bucket is allowed under current NSCL axes.
        Driven by gambit_deltas.json intent_buckets[*].gate (if present). Safe fallback: allow.
        """
        if not self.enabled:
            return True
        if not self.loaded:
            self.load()
        if not self.loaded:
            return True

        bucket = str(bucket or "OBSERVE")
        spec = (self.gambit_deltas.get("intent_buckets", {}) or {}).get(bucket, {}) or {}
        gate = spec.get("gate") or (self.gambit_deltas.get("gating", {}) or {}).get("defaults", {}).get(bucket) or {}

        # No gate spec => allow
        if not gate:
            return True

        stage_order = ["SOCIAL","FLIRT","FOREPLAY","PLAY","EDGE","FRENZY","AFTERGLOW","COOLDOWN"]
        def idx(x):
            try:
                return stage_order.index(str(x))
            except Exception:
                return 0

        try:
            min_stage = gate.get("min_stage")
            if min_stage and idx(stage) < idx(min_stage):
                return False
            max_stage = gate.get("max_stage")
            if max_stage and idx(stage) > idx(max_stage):
                return False
        except Exception:
            pass

        try:
            consent_allow = gate.get("consent_allow")
            if consent_allow and str(consent) not in set(map(str, consent_allow)):
                return False
        except Exception:
            pass

        try:
            lane_allow = gate.get("lane_allow")
            if lane_allow and str(lane) not in set(map(str, lane_allow)):
                return False
        except Exception:
            pass

        return True


    def _normalize_intent_label(self, raw: str) -> str:
        s = (raw or "").strip().upper()
        s = s.replace("-", "_").replace(" ", "_")
        while "__" in s:
            s = s.replace("__", "_")
        return s

    def resolve_bucket(self, raw_intent: str) -> str:
        """Map arbitrary director/tool labels into canonical buckets using intent_bucket_aliases.json."""
        raw_n = self._normalize_intent_label(raw_intent)

        # Special-case: distinguish dom/sub frenzy buckets if present
        try:
            if "FRENZY" in raw_n:
                if "DOM" in raw_n and "FRENZY_DOM" in (self.gambit_deltas.get("intent_buckets", {}) or {}):
                    return "FRENZY_DOM"
                if "SUB" in raw_n and "FRENZY_SUB" in (self.gambit_deltas.get("intent_buckets", {}) or {}):
                    return "FRENZY_SUB"
            if raw_n == "FRENZY":
                lead = str((self.state or {}).get("LEAD") or "")
                lane0 = str((self.state or {}).get("LANE") or "")
                if (lead == "SURRENDERED" or lane0 == "NEEDY") and "FRENZY_SUB" in (self.gambit_deltas.get("intent_buckets", {}) or {}):
                    return "FRENZY_SUB"
                if "FRENZY_DOM" in (self.gambit_deltas.get("intent_buckets", {}) or {}):
                    return "FRENZY_DOM"
        except Exception:
            pass

        # 1) already canonical?
        try:
            canon = set(self.intent_aliases.get("canonical_buckets", []) or [])
            if raw_n in canon:
                return raw_n
        except Exception:
            pass

        # 2) exact aliases
        try:
            exact = self.intent_aliases.get("exact_aliases", {}) or {}
            for bucket, alias_list in exact.items():
                for a in (alias_list or []):
                    if raw_n == self._normalize_intent_label(a):
                        return str(bucket)
        except Exception:
            pass

        # 3) regex rules
        try:
            for r in (self.intent_aliases.get("regex_rules", []) or []):
                pat = r.get("pattern", "") or ""
                bucket = r.get("bucket", "") or ""
                if pat and bucket and re.match(pat, raw_n):
                    return str(bucket)
        except Exception:
            pass

        return "OBSERVE"

    def apply_intent(self, *, raw_intent: str, lane: str, now: float, confidence: float = 1.0):
        """Apply gambit/tool intent deltas to NSCL state (authoritative in hardlink mode)."""
        if not self.enabled:
            return
        if not self.loaded:
            self.load()
        if not self.loaded:
            return

        # Confidence gate (prevents thrash from weak signals)
        try:
            gate = float(self.gambit_deltas.get("global", {}).get("confidence_thresholds", {}).get("apply_tool_intent", 0.35))
        except Exception:
            gate = 0.35
        try:
            if float(confidence) < gate:
                return
        except Exception:
            pass

        bucket = self.resolve_bucket(raw_intent)

        # Pull spec
        spec = (self.gambit_deltas.get("intent_buckets", {}) or {}).get(bucket, {}) or {}

        lane_n = self._normalize_intent_label(lane)
        lane_mods = (self.gambit_deltas.get("lane_modifiers", {}) or {}).get(lane_n, {}) or {}

        deltas = dict((spec.get("axis_deltas") or spec.get("deltas") or {}) or {})
        deltas.update((lane_mods.get("axis_deltas_overrides") or lane_mods.get("deltas_overrides") or {}) or {})

        # Stage operations
        stage_order = ["SOCIAL","FLIRT","FOREPLAY","PLAY","EDGE","FRENZY","AFTERGLOW","COOLDOWN"]
        def idx(x):
            try:
                return stage_order.index(x)
            except Exception:
                return 0

        cur_stage = str(self.state.get("STAGE") or "SOCIAL")

        stage_set = deltas.get("stage_set")
        stage_adv = deltas.get("stage_advance_by", deltas.get("stage_delta", 0))

        if stage_set and str(stage_set) in stage_order:
            self.state["STAGE"] = str(stage_set)
        else:
            try:
                adv = int(stage_adv)
            except Exception:
                adv = 0
            if adv != 0:
                ni = max(0, min(len(stage_order)-1, idx(cur_stage) + adv))
                self.state["STAGE"] = stage_order[ni]

        # Simple sets
        for k_src, k_dst in [
            ("wardrobe_set", "WARDROBE"),
            ("contact_set", "CONTACT"),
            ("lead_set", "LEAD"),
            ("consent_set", "CONSENT"),
        ]:
            v = deltas.get(k_src)
            if v:
                self.state[k_dst] = str(v)

        # Lane always set (keeps NSCL deterministic)
        if lane_n:
            self.state["LANE"] = lane_n


        # Treat lane as "mask/register" for surfacing (without spamming)
        try:
            self._last_dialogue_time = float(now)
            # show the mask line for a few seconds after a narrative tick
            self._mask_line_until = max(float(self._mask_line_until or 0.0), float(now) + 3.5)
            prev_mask = str(self._last_mask or "")
            cur_mask = str(self.state.get("LANE") or "")
            if cur_mask and cur_mask != prev_mask:
                # Cooldown so rapid lane oscillation doesn't spam
                if float(now) >= float(getattr(self, "_mask_shift_cd_until", 0.0) or 0.0):
                    self.toast_queue.append((float(now) + 1.6, f"MASK SHIFT -> {self._pretty_lane(cur_mask)}"))
                    self._mask_shift_cd_until = float(now) + 4.0
                self._last_mask = cur_mask
        except Exception:
            pass


        # Emit one event (deterministic pick, supports both formats)
        def _when_ok(when: dict) -> bool:
            if not when:
                return True
            try:
                lane_in = when.get("lane_in")
                if lane_in and str(self.state.get("LANE")) not in set(map(str, lane_in)):
                    return False
                stage_in = when.get("stage_in")
                if stage_in and str(self.state.get("STAGE")) not in set(map(str, stage_in)):
                    return False
                contact_in = when.get("contact_in")
                if contact_in and str(self.state.get("CONTACT")) not in set(map(str, contact_in)):
                    return False
                badge_in = when.get("badge_in")
                if badge_in:
                    badges = set(map(str, self.state.get("BADGES") or []))
                    if not any(b in badges for b in map(str, badge_in)):
                        return False
            except Exception:
                pass
            return True

        # New style: spec["events"] = [{"id":..., "w":..., "when":...}, ...]
        events_list = list(spec.get("events", []) or [])
        # Legacy/alt style: event_candidates = ["EV_*", ...]
        cand = list(spec.get("event_candidates", []) or [])
        cand += list(lane_mods.get("event_candidates_add", []) or [])

        ev_pick = None
        if events_list:
            try:
                # deterministic: sort by weight desc, pick first whose 'when' passes
                events_list_sorted = sorted(events_list, key=lambda e: float(e.get("w", 0.0)), reverse=True)
                for e in events_list_sorted:
                    ev_id = e.get("id")
                    if ev_id and ev_id in self.events and _when_ok(e.get("when") or {}):
                        ev_pick = ev_id
                        break
            except Exception:
                pass

        if not ev_pick and cand:
            for ev_id in cand:
                if ev_id in self.events:
                    ev_pick = ev_id
                    break

        if ev_pick:
            self._emit(ev_pick, now, ttl_s=1.1)


    def apply_text_tokens(self, *, speaker: str, text: str, now: float):
        """
        Apply consent/contract cues from *existing* printed text.
        No new explicit content is authored here; this only listens for patterns
        defined in consent_tokens.json and updates axes deterministically.
        """
        if not self.enabled:
            return
        if not self.loaded:
            self.load()
        if not self.loaded:
            return
        try:
            rules = (getattr(self, "consent_tokens", None) or {}).get("tokens", []) or []
        except Exception:
            rules = []
        if not rules:
            return

        s = (speaker or "").strip()
        t = ""
        try:
            t = str(text or "")
        except Exception:
            t = ""
        tl = t.lower()

        # helper: clamp small ints
        def _clamp_int(v, lo=0, hi=3):
            try:
                iv = int(v)
            except Exception:
                try:
                    iv = int(float(v))
                except Exception:
                    return lo
            return lo if iv < lo else hi if iv > hi else iv

        for r in rules:
            try:
                # speaker filter (optional)
                sp_ok = True
                sp = r.get("speaker")
                if sp:
                    if isinstance(sp, str):
                        sp_ok = (sp.lower() in s.lower())
                    elif isinstance(sp, (list, tuple)):
                        sp_ok = any((str(x).lower() in s.lower()) for x in sp)
                if not sp_ok:
                    continue

                pats = r.get("patterns") or []
                if isinstance(pats, str):
                    pats = [pats]
                hit = False
                for p in pats:
                    try:
                        if not p:
                            continue
                        if re.search(p, tl, flags=re.IGNORECASE):
                            hit = True
                            break
                    except Exception:
                        # simple substring fallback
                        try:
                            if str(p).lower() in tl:
                                hit = True
                                break
                        except Exception:
                            pass
                if not hit:
                    continue

                # Apply axis deltas
                deltas = r.get("axis_deltas") or {}
                if isinstance(deltas, dict):
                    for k, v in deltas.items():
                        kk = str(k).upper().strip()
                        if kk in ("POWER", "DENIAL"):
                            cur = self.state.get(kk, 0)
                            # allow "+1" style
                            if isinstance(v, str) and (v.startswith("+") or v.startswith("-")):
                                try:
                                    cur = int(cur)
                                except Exception:
                                    cur = 0
                                try:
                                    cur = cur + int(float(v))
                                except Exception:
                                    pass
                                self.state[kk] = _clamp_int(cur)
                            else:
                                self.state[kk] = _clamp_int(v)
                        elif kk in ("CONSENT", "LEAD", "STAGE", "WARDROBE", "CONTACT", "LANE", "LOC", "URGENCY", "CONSEQUENCE"):
                            self.state[kk] = str(v).upper()
                        else:
                            # store extra keys safely
                            self.state[kk] = v

                # Contract toggles (optional)
                contracts = r.get("contracts") or {}
                if isinstance(contracts, dict):
                    c = self.state.get("CONTRACTS") or {}
                    if not isinstance(c, dict):
                        c = {}
                    for ck, cv in contracts.items():
                        try:
                            c[str(ck).upper()] = cv
                        except Exception:
                            pass
                    self.state["CONTRACTS"] = c

                # Emit event toast (optional)
                ev = r.get("event_id") or r.get("emit")
                if ev:
                    self._emit(str(ev), now, ttl_s=float(r.get("ttl_s", 1.2) or 1.2))

                # One rule per line max (prevents multi-hit spam)
                break
            except Exception:
                continue

    def pose_is_allowed(self, pose_id: str, stage: str, wardrobe: str, contact: str, lead: str) -> bool:
        """Validate pose against pose_catalog constraints (PG semantic)."""
        if not self.pose_catalog:
            return True

        p = self.pose_catalog.get(str(pose_id) or "", {}) or {}
        stage_order = ["SOCIAL","FLIRT","FOREPLAY","PLAY","EDGE","FRENZY","AFTERGLOW","COOLDOWN"]
        def idx(x):
            try:
                return stage_order.index(str(x))
            except Exception:
                return 0

        min_stage = p.get("suggested_stage_min")
        if min_stage and idx(stage) < idx(min_stage):
            return False

        compat = p.get("wardrobe_compat") or []
        if compat and wardrobe not in compat:
            return False

        allowed = p.get("allowed_contact") or []
        if allowed and contact not in allowed:
            return False

        return True

    def pick_fallback_pose(self, stage: str, wardrobe: str, contact: str, lead: str, loc: Optional[str] = None) -> str:
        """Pick the nearest allowed pose. Prefer location match; relax contact if needed."""
        if not self.pose_catalog:
            return ""

        # pass 1: strict
        for pid, p in self.pose_catalog.items():
            if loc and p.get("loc") and str(p.get("loc")) != str(loc):
                continue
            if self.pose_is_allowed(pid, stage, wardrobe, contact, lead):
                return pid

        # pass 2: relax contact to CLOSE
        for pid, p in self.pose_catalog.items():
            if loc and p.get("loc") and str(p.get("loc")) != str(loc):
                continue
            if self.pose_is_allowed(pid, stage, wardrobe, "CLOSE", lead):
                return pid

        # pass 3: anything stage-allowed
        for pid in self.pose_catalog.keys():
            return pid

        return ""

    def _infer_lane(self, engine) -> str:
        # User rule of thumb (your build language):
        # denial = bratty, rough = needy, gentle = gentle/quiet.
        mode = ""
        try:
            mode = str(getattr(engine, "current_mode", "") or getattr(engine.round_state, "intensity_mode", "") or "").lower()
        except Exception:
            mode = ""

        if "denial" in mode or mode == "bratty":
            return "BRATTY"
        if "rough" in mode or "needy" in mode:
            return "NEEDY"

        # If she's melting/open, lean RAMBLING; else QUIET.
        try:
            bs = str(getattr(engine.session_state, "birdsong_state", "") or "").lower()
            if bs in ("open", "melting"):
                return "RAMBLING"
        except Exception:
            pass

        return "QUIET"

    def _infer_lead(self, engine) -> str:
        try:
            pd = float(getattr(engine.round_state, "power_dynamic", 0.0) or 0.0)
        except Exception:
            pd = 0.0

        # Keep a contested band in the middle.
        if abs(pd) < 0.18:
            return "MUTUAL"
        if abs(pd) < 0.55:
            return "CONTESTED"
        if pd >= 0.55:
            return "FIEND_LEADS"
        return "BIRD_LEADS"

    def _infer_stage(self, engine) -> str:
        rs = getattr(engine, "round_state", None)
        ss = getattr(engine, "session_state", None)

        tier = 0
        her = 0.0
        depth = 0.0
        in_flow = False
        try:
            tier = int(getattr(rs, "tier", 0) or 0)
            her = float(getattr(rs, "her_pleasure", 0.0) or 0.0)
            depth = float(getattr(rs, "depth", 0.0) or 0.0)
            in_flow = bool(getattr(rs, "in_flow", False))
        except Exception:
            pass

        phase = ""
        try:
            phase = str(getattr(ss, "session_phase", "") or "").lower()
        except Exception:
            phase = ""

        mode = ""
        try:
            mode = str(getattr(engine, "current_mode", "") or getattr(rs, "intensity_mode", "") or "").lower()
        except Exception:
            mode = ""

        # AFTERGLOW / COOLDOWN from explicit flags, otherwise inferred.
        try:
            if bool(getattr(engine.vibe, "climax_reached", False)):
                # post-climax can still be "play" if you're still riding intensity,
                # but default to AFTERGLOW if tier drops.
                if tier <= 1 and her < 0.45:
                    return "AFTERGLOW"
        except Exception:
            pass

        if phase == "warmup" and (depth < 0.1 and her < 0.15):
            base = "SOCIAL"
        elif phase == "warmup":
            base = "FLIRT"
        elif phase == "building":
            base = "FOREPLAY" if (depth < 0.55 and her < 0.65) else "PLAY"
        elif phase == "peak":
            base = "FRENZY" if (tier >= 2 or her > 0.80 or depth > 0.75) else "PLAY"
        elif phase == "resolution":
            base = "EDGE" if ("denial" in mode) else ("FRENZY" if tier >= 2 else "PLAY")
        else:
            # fallback
            if tier >= 3 or her > 0.85:
                base = "FRENZY"
            elif tier >= 2 or her > 0.65 or depth > 0.60:
                base = "PLAY"
            elif her > 0.35 or depth > 0.35:
                base = "FOREPLAY"
            elif depth > 0.10 or her > 0.15:
                base = "FLIRT"
            else:
                base = "SOCIAL"

        # Denial turns into EDGE once intimacy is live.
        if "denial" in mode and base in ("FOREPLAY", "PLAY", "FRENZY"):
            return "EDGE"

        # A very soft COOLDOWN if flow collapses hard
        try:
            if (not in_flow) and tier == 0 and float(getattr(rs, "momentum", 0.0) or 0.0) < -0.65:
                return "COOLDOWN"
        except Exception:
            pass

        return base

    def _infer_contact_wardrobe(self, engine, stage: str) -> Tuple[str, str]:
        rs = getattr(engine, "round_state", None)
        tier = 0
        depth = 0.0
        try:
            tier = int(getattr(rs, "tier", 0) or 0)
            depth = float(getattr(rs, "depth", 0.0) or 0.0)
        except Exception:
            pass

        # PG semantic. This is about "how far / fabric state" for disambiguation,
        # not description.
        if stage in ("SOCIAL", "FLIRT"):
            return ("NONE" if depth < 0.2 else "CLOSE", "CLOTHED")
        if stage == "FOREPLAY":
            return ("TOUCH", "SHIFTED" if depth > 0.25 else "CLOTHED")
        if stage in ("PLAY", "EDGE"):
            # Edge can be high-contact but intentionally constrained. Keep it implied.
            return ("IMPLIED" if stage == "EDGE" else "HEAVY", "PARTIAL" if depth > 0.45 else "SHIFTED")
        if stage == "FRENZY":
            return ("HEAVY", "PARTIAL")
        if stage in ("AFTERGLOW", "COOLDOWN"):
            return ("AFTERCARE_TOUCH", "WRAPPED")
        return ("NONE", "CLOTHED")

    def _infer_consent_flag(self, engine) -> str:
        rs = getattr(engine, "round_state", None)
        try:
            if rs and (getattr(rs, "failure_acknowledged", True) is False):
                return "AMBER"
            if rs and str(getattr(rs, "pending_negative_event", "") or ""):
                return "AMBER"
        except Exception:
            pass
        return "GREEN"

    def _badges(self, engine, stage: str) -> List[str]:
        badges = []
        rs = getattr(engine, "round_state", None)
        vibe = getattr(engine, "vibe", None)

        combo = 0
        misses = 0
        in_flow = False
        try:
            combo = int(getattr(vibe, "combo", 0) or 0)
            misses = int(getattr(vibe, "misses", 0) or 0)
            in_flow = bool(getattr(rs, "in_flow", False))
        except Exception:
            pass

        # DUET signals: high combo + flow.
        if combo >= 18 and in_flow:
            badges.append("DUET")
        if combo >= 35 and in_flow and misses <= 3:
            badges.append("DUET_PLUS")

        # VELVET: sustained low-noise control.
        try:
            depth = float(getattr(rs, "depth", 0.0) or 0.0)
            comp = float(getattr(rs, "composure", 1.0) or 1.0)
            if depth > 0.65 and comp < 0.55 and combo >= 12:
                badges.append("VELVET")
        except Exception:
            pass

        # GLINT: little sacred spark that recurs when play is clean
        if combo in (10, 20, 30, 40) and misses <= 2:
            badges.append("GLINT")

        # Frenzy badges based on power dynamic / tier
        try:
            pd = float(getattr(rs, "power_dynamic", 0.0) or 0.0)
            tier = int(getattr(rs, "tier", 0) or 0)
            if stage in ("FRENZY",) or tier >= 2:
                if pd >= 0.65:
                    badges.append("DOM_FRENZY")
                elif pd <= -0.65:
                    badges.append("SUB_FRENZY")
        except Exception:
            pass

        return badges

    def _pick_pattern(self, stage: str, wardrobe: str, contact: str, lead: str, badges: List[str]) -> str:
        # Force DUET_PLUS pattern if present
        if "DUET_PLUS" in badges:
            return "F_IMPLIED_DUETPLUS"

        if stage in ("AFTERGLOW", "COOLDOWN"):
            return "G_AFTERCARE_MUTUAL"

        # Simplified mapping into the 8 patterns.
        if contact == "NONE" and wardrobe == "CLOTHED":
            return "A_BASE_MUTUAL"

        if lead == "FIEND_LEADS" and contact in ("CLOSE", "TOUCH") and wardrobe == "CLOTHED":
            return "B_CLOSE_FIEND"

        if wardrobe == "SHIFTED" and contact == "TOUCH":
            return "C_SHIFT_TOUCH_COACHED"

        if lead == "CONTESTED" and contact == "CLOSE":
            return "E_CLOSE_CONTESTED"

        if contact == "HEAVY" and lead in ("SURRENDERED",):
            return "H_HEAVY_SURRENDERED"

        if wardrobe == "PARTIAL" and contact == "HEAVY" and lead == "FIEND_LEADS":
            return "D_PARTIAL_HEAVY_FIEND"

        if contact == "IMPLIED":
            # default implied pattern
            return "F_IMPLIED_DUETPLUS" if "DUET_PLUS" in badges else "A_BASE_MUTUAL"

        return "A_BASE_MUTUAL"

    def _pretty_lane(self, lane: str) -> str:
        """Display-safe lane/mask label.
        Keeps the "feel" but avoids confusing run-on strings like 'quietokay.'
        """
        raw = (lane or "").strip()
        if not raw:
            return "QUIET"
        low = raw.lower()
        # canonical lanes
        if "quiet" in low:
            base = "QUIET"
        elif "brat" in low:
            base = "BRATTY"
        elif "need" in low:
            base = "NEEDY"
        elif "rambl" in low:
            base = "RAMBLING"
        else:
            # fallback: take first alpha token
            m = re.search(r"[a-zA-Z]+", raw)
            base = (m.group(0).upper() if m else raw[:12].upper())
        # optional soft suffix (ok/okay/soft/etc) -> keep in parentheses if present
        suffix = ""
        for key, lab in [("okay","okay"),("ok","ok"),("soft","soft"),("sharp","sharp")]:
            if key in low and base not in ("OK","OKAY"):
                suffix = lab
                break
        return f"{base} ({suffix})" if suffix else base


    def _pose_sem_label(self, pose_id: str, stage: str, contact: str, wardrobe: str, lead: str, lane: str) -> str:
        """Return a mature-but-not-crass pose semantic label.
        Presentation only; authoritative axes are STAGE/CONTACT/WARDROBE/LEAD/LANE/CONSENT.
        """
        pid = (pose_id or "").upper()
        st = (stage or "").upper()
        ct = (contact or "").upper()
        wd = (wardrobe or "").upper()

        if pid == "SQUAT":
            return "INTIMACY"
        if pid == "DOWNWARD":
            if st in ("FOREPLAY","PLAY","EDGE","FRENZY"):
                if ct in ("NONE","AIR"):
                    return "APPROACH"
                if wd in ("CLOTHED","PARTIAL"):
                    return "TEASE"
                return "INVITATION"
            return "APPROACH"
        if pid in ("COY_CHEEK","COY_CHEEK_2","COY_CHEEK_3"):
            return "THRONE"
        if pid in ("FACE","FACE_CLOSE","FACE_SMILE","FACE_SOFT"):
            return "REGULATION"
        if pid in ("OUTHOUSE","BATHROOM","WASHROOM"):
            return "FOCUS"
        if pid in ("LAYING_SMILE","LAYING","AFTERGLOW"):
            return "AFTERGLOW"
        if pid in ("ANGLED_COLLAPSE","COLLAPSE_ANGLED"):
            return "BREATH_UP"
        return pid or "POSE"

    def _format_axes_banner(self) -> str:
        """Always-on trust banner driven by live NSCL axes."""
        try:
            stage = str(self.state.get("STAGE") or "SOCIAL")
            loc = str(self.state.get("LOC") or "ROOM")
            lane = str(self.state.get("LANE") or "QUIET")
            lead = str(self.state.get("LEAD") or "MUTUAL")
            consent = str(self.state.get("CONSENT") or "GREEN")
            contact = str(self.state.get("CONTACT") or "NONE")
            wardrobe = str(self.state.get("WARDROBE") or "CLOTHED")
            pose_id = str(self.state.get("POSE_ID") or "")
            pose_sem = self._pose_sem_label(pose_id, stage, contact, wardrobe, lead, lane)

            bits = [
                f"STAGE:{stage}",
                f"POSE:{pose_sem}",
                f"CONTACT:{contact}",
                f"WARD:{wardrobe}",
                f"LEAD:{lead}",
                f"LANE:{lane}",
                f"CONSENT:{consent}",
            ]
            if loc and loc != "ROOM":
                bits.insert(0, f"LOC:{loc}")
            return "  ".join(bits)
        except Exception:
            return ""

    def _format_banner(self, card: dict, loc: str, lane: str, badges: List[str]) -> str:
        # New default: axes banner is the "trust panel". Cards banner is optional cosmetics.
        try:
            mode = (os.environ.get("LOCKKEY_NSCL_BANNER_MODE", "") or "").strip().lower()
        except Exception:
            mode = ""
        if mode in ("axes", "axis", "nscl", "live", "truth") or mode == "":
            return self._format_axes_banner()

        # Legacy card-driven banner (kept for compatibility)
        banner_t = ""
        try:
            banner_t = str(card.get("display", {}).get("banner", "") or "")
        except Exception:
            banner_t = ""

        badge_txt = ""
        if badges:
            badge_txt = " " + " ".join([f"[{b}]" for b in badges[:4]])

        return (banner_t
                .replace("{LOC}", loc)
                .replace("{LANE}", lane)
                .replace("{BADGES}", badge_txt)).strip()

    def tick(self, engine, now: float):
        if not self.enabled:
            return
        if not self.loaded:
            self.load()
        if not self.loaded:
            return

        # Pose -> LOC + caption bias
        pose_name = ""
        try:
            pose_name = str(getattr(engine.lightmap_renderer, "current_pose", "") or "")
        except Exception:
            pose_name = ""

        pose_id = self._normalize_pose_id(pose_name)
        pose_entry = self.pose_catalog.get(pose_id, {})
        loc = str(pose_entry.get("loc") or "ROOM")
        pose_caption = str(pose_entry.get("caption_pg") or "").strip()
        lane_inf = self._infer_lane(engine)
        stage_inf = self._infer_stage(engine)
        lead_inf = self._infer_lead(engine)
        consent_inf = self._infer_consent_flag(engine)
        contact_inf, wardrobe_inf = self._infer_contact_wardrobe(engine, stage_inf)
        badges = self._badges(engine, stage_inf)

        # HARDLINK (authoritative NSCL axes, with safe fallbacks)
        hardlink = bool(getattr(engine, "nscl_hardlink", False))
        stage_order = ["SOCIAL","FLIRT","FOREPLAY","PLAY","EDGE","FRENZY","AFTERGLOW","COOLDOWN"]
        def _idx(x):
            try:
                return stage_order.index(str(x))
            except Exception:
                return 0

        if hardlink:
            lane = str(self.state.get("LANE") or lane_inf)
            stage = str(self.state.get("STAGE") or stage_inf)
            # never regress below inferred stage (lets engine milestones push forward)
            stage = stage_order[max(_idx(stage), _idx(stage_inf))]
            lead = str(self.state.get("LEAD") or lead_inf)
            consent = str(self.state.get("CONSENT") or consent_inf)
            # safety-first consent: if inference says RED/AMBER, respect it
            if str(consent_inf) in ("RED", "AMBER"):
                consent = str(consent_inf)
            contact = str(self.state.get("CONTACT") or contact_inf)
            wardrobe = str(self.state.get("WARDROBE") or wardrobe_inf)
        else:
            lane = lane_inf
            stage = stage_inf
            lead = lead_inf
            consent = consent_inf
            contact, wardrobe = contact_inf, wardrobe_inf

        # Pattern + card
        # Reduce BIRD_LEADS into CONTESTED for card patterns (keeps the 64-card grid stable).
        lead_for_pattern = lead if lead != "BIRD_LEADS" else "CONTESTED"
        pattern = self._pick_pattern(stage, wardrobe, contact, lead_for_pattern, badges)
        card = self.card_index.get((stage, pattern)) or self.card_index.get(("SOCIAL", "A_BASE_MUTUAL")) or {}
        card_id = str(card.get("id") or "")

        # Toast on stage/card shift
        if stage != self._last_stage:
            self._emit(f"EV_CONTEXT_SHIFT_{stage}", now, ttl_s=1.15) if f"EV_CONTEXT_SHIFT_{stage}" in self.events else self._emit("CONTEXT SHIFT -> " + stage, now, ttl_s=1.0)
            self._last_stage = stage

        if card_id and card_id != self._last_card:
            # Small card-change toast (lower priority)
            try:
                t = str(card.get("display", {}).get("toast_on_enter") or "")
                if t:
                    self._emit(t, now, ttl_s=1.0)
            except Exception:
                pass
            self._last_card = card_id

        # Combo-triggered microgestures (your “smile crackle / head tilt” asks)
        try:
            combo = int(getattr(engine.vibe, "combo", 0) or 0)
            misses = int(getattr(engine.vibe, "misses", 0) or 0)

            # On clean combo thresholds
            if combo in (8, 16, 24, 32, 40) and combo != self._last_combo:
                # choose a tiny, breathless event
                choices = ["EV_SMILE_CRACKLE", "EV_HEAD_TILT_SOFT", "EV_BREATH_CATCH", "EV_PAUSE_HEAVY", "EV_STAREDOWN_VELVET"]
                # bias velvet during VELVET badge
                if "VELVET" in badges:
                    choices = ["EV_STAREDOWN_VELVET", "EV_PAUSE_HEAVY", "EV_BREATH_CATCH"]
                for ev in choices:
                    if ev in self.events:
                        self._emit(ev, now, ttl_s=1.1)
                        break
                self._last_combo = combo

            # Miss spike -> flinch / reset
            if misses != self._last_miss and misses > 0:
                if "EV_FLINCH" in self.events:
                    self._emit("EV_FLINCH", now, ttl_s=1.0)
                self._last_miss = misses
        except Exception:
            pass

        # HARDLINK POSE: enforce pose_catalog eligibility once intimacy begins
        try:
            if bool(getattr(engine, "nscl_hardlink_pose", False)):
                if stage in ("FOREPLAY", "PLAY", "EDGE", "FRENZY", "AFTERGLOW"):
                    cur_pose_id = pose_id
                    if cur_pose_id and not self.pose_is_allowed(cur_pose_id, stage, wardrobe, contact, lead):
                        fb = self.pick_fallback_pose(stage, wardrobe, contact, lead, loc=loc)
                        if fb:
                            # convert catalog POSE_ID back to engine pose name (lowercase)
                            engine_pose_name = str(fb).lower()
                            try:
                                engine.lightmap_renderer.set_pose(engine_pose_name, instant=False)
                            except Exception:
                                try:
                                    engine.lightmap_renderer.set_pose(engine_pose_name)
                                except Exception:
                                    pass
        except Exception:
            pass

        # Update state
        self._prev_state = dict(self.state)
        self.state.update({
            "LOC": loc,
            "STAGE": stage,
            "WARDROBE": wardrobe,
            "CONTACT": contact,
            "LEAD": lead,
            "LANE": lane,
            "CONSENT": consent,
            "BADGES": badges,
            "CARD_ID": card_id or self.state.get("CARD_ID", ""),
            "POSE_ID": pose_id,
            "POSE_CAPTION": pose_caption,
        })

    def render(self, scr, flow_mode: bool = False):
        if flow_mode:
            # Respect your “Flow = no subtitles” discipline by default.
            try:
                if (os.environ.get("LOCKKEY_NSCL_FLOW", "") or "").strip().lower() in ("1","true","yes","on"):
                    pass
                else:
                    return
            except Exception:
                return

        if not self.loaded:
            return

        h, w = scr.getmaxyx()

        # Banner (bottom line)
        try:
            stage = self.state.get("STAGE", "SOCIAL")
            pattern = None
            # recover card for formatting
            card = None
            # current card id
            cid = self.state.get("CARD_ID", "")
            if cid:
                # find card quickly by id from card_index values
                for c in self.card_index.values():
                    if c.get("id") == cid:
                        card = c
                        break
            if not card:
                card = self.card_index.get(("SOCIAL", "A_BASE_MUTUAL"), {})
            banner = self._format_banner(
                card=card,
                loc=str(self.state.get("LOC", "ROOM")),
                lane=str(self._pretty_lane(str(self.state.get("LANE", "QUIET")))),
                badges=list(self.state.get("BADGES", []) or []),
            )
            if banner:
                # Cosmetic: "ROOM" label reads as semantic context, not just location
                if banner.startswith("ROOM ") or banner.startswith("ROOM•") or banner.startswith("ROOM"):
                    banner = banner.replace("ROOM", "CONTEXT", 1)
                scr.addstr(h - 1, 1, (" " + banner)[:max(0, w - 2)], curses.A_DIM)
        except Exception:
            pass

        # Pose caption once intimacy begins
        try:
            if str(self.state.get("STAGE")) in ("FOREPLAY", "PLAY", "EDGE", "FRENZY", "AFTERGLOW"):
                cap = str(self.state.get("POSE_CAPTION") or "").strip()
                pid = str(self.state.get("POSE_ID") or "").strip()
                if cap or pid:
                    line = f"POSE -> {pid}{(' • ' + cap) if cap else ''}"
                    scr.addstr(h - 3, 2, line[:max(0, w - 4)], curses.A_DIM)
        except Exception:
            pass

        # Temporary mask line (only after dialogue/narrative ticks)
        try:
            now = time.time()
            if float(getattr(self, "_mask_line_until", 0.0) or 0.0) > float(now):
                mask = str(self.state.get("LANE") or "").strip()
                if mask:
                    disp = self._pretty_lane(mask)
                line = f"mask: {disp.lower()}"
                y = (h - 3) if flow_mode else (h - 2)
                scr.addstr(y, 1, (" " + line)[:max(0, w - 2)], curses.A_DIM)
        except Exception:
            pass

        # Toasts (stack upward; keep below the Systems HUD banner)
        try:
            now = time.time()
            # drop expired
            self.toast_queue = [(u,t) for (u,t) in self.toast_queue if u > now]
            if self.toast_queue:
                # show up to 2 lines
                show = self.toast_queue[-2:]
                y = 2
                for _, text in show:
                    scr.addstr(y, 2, str(text)[:max(0, w - 4)], curses.A_BOLD)
                    y += 1
        except Exception:
            pass

        # Final pass: redraw banner last so nothing overwrites it.
        try:
            h, w = scr.getmaxyx()
            lane = str(self.state.get("LANE") or "QUIET")
            loc = str(self.state.get("LOC") or "ROOM")
            card_id = str(self.state.get("CARD_ID") or "")
            card = self.cards.get(card_id, {}) if hasattr(self, "cards") else {}
            badges = list(self.state.get("BADGES") or [])
            banner = self._format_banner(card, loc, lane, badges)
            if banner:
                scr.addstr(h - 1, 1, (" " + banner)[:max(0, w - 2)], curses.A_BOLD)
        except Exception:
            pass
def validate_telemetry_stream() -> None:
    """Quick sanity check — call from interactive session if tail looks broken"""
    sample = {
        "event": "TELEMETRY_SANITY",
        "t": time.time(),
        "note": "Ogre → Biometric → Japan linkage confirmed",
        "pid": os.getpid()
    }
    telemetry.emit(sample)
    print("[VALIDATION] Emitted sanity check event")

