@dataclass
class RoundState:
    """State for a single intimate cycle - resets each round."""
    her_pleasure: float = 0.0       # 0.0 -> 1.0, builds to climax
    his_pleasure: float = 0.0       # 0.0 -> 1.0, can peak before her
    momentum: float = 0.0           # -1.0 -> 1.0, negative=retreat, positive=advance
    composure: float = 1.0          # 1.0 -> 0.0, her emotional walls (from cascade)
    intensity_mode: str = "gentle"  # gentle/steady/rough

    # GEN 31–34: Persona/mode balance hooks (safe defaults).
    # Populated by PlayableEngineV5 at session start via persona_system.to_round_balance_dict().
    balance: Dict[str, float] = field(default_factory=lambda: {
        "bpm_mult": 1.0,
        "window_mult": 1.0,
        "her_gain": 1.0,
        "his_gain": 1.0,
        "miss_penalty": 1.0,
        "momentum_gain": 1.0,
        "composure_drop": 1.0,
        "composure_restore": 1.0,
    })

    # Escalation tier (rhythm difficulty)
    tier: int = 0                   # 0=Release, 1=Overdrive, 2=Frenzy, 3=Breaking, 4=Transcendence
    tier_combo: int = 0             # Hits since entering this tier
    tier_misses: int = 0            # Misses this tier (resets on tier change)

    # Round tracking
    round_hits: int = 0
    round_misses: int = 0
    round_start_time: float = 0.0

    # Failure tracking (for consequences)
    recent_slips: int = 0           # Slips this round
    recent_wrong_holes: int = 0     # Wrong holes this round
    last_failure_type: str = ""     # "slip", "wrong_hole", "combo_break"
    failure_acknowledged: bool = True  # Has failure been addressed in dialogue?

    # ═══════════════════════════════════════════════════════════════════════════
    # SURGE SYSTEM - Tiered Progression
    # ═══════════════════════════════════════════════════════════════════════════
    # TIER 1: BLANK (0.0 -> 1.0) - Clear notes, safety net, easiest to understand
    # TIER 2: PUSH (1.0 -> 2.0) - Force dialogue escalation, take control
    # TIER 3: PERFECT LINE (2.0 -> 3.0) - Say exactly the right thing, tame her
    #
    # Charge continues past 1.0 into next tier. Use contextually:
    # - In rhythm: Always uses BLANK if charged (safety)
    # - In dialogue: Uses highest available tier (PUSH or PERFECT LINE)
    # - In choices: Uses PERFECT LINE if available, else PUSH
    surge_charge: float = 0.0       # 0.0 -> 3.0, each 1.0 = one tier
    surge_tier: int = 0             # 0=empty, 1=blank, 2=push, 3=perfect
    surges_used: int = 0            # Total surges this round
    surge_cooldown: float = 0.0     # Brief cooldown after use
    last_surge_type: str = ""       # "blank", "push", "perfect_line"
    surge_combo_streak: int = 0     # Consecutive perfect hits toward charge
    surge_context_enabled: bool = True # Degradation-only red/green/purple context choreography

    # Release loop: separate from climate/surge so the player can read the
    # difference between "can this become a child" and "can I finish this now".
    release_charge: float = 0.0     # 0.0 -> 1.0, commit-ready at full
    cycle_lives: int = 2            # Major failures allowed this cycle
    max_cycle_lives: int = 2
    climaxes_this_cycle: int = 0

    # ═══════════════════════════════════════════════════════════════════════════
    # V3 POWER DYNAMIC - Who's in control? Affects dialogue, rhythm, everything
    # ═══════════════════════════════════════════════════════════════════════════
    power_dynamic: float = 0.0      # -1.0 (BIRD_DOM) ↔ +1.0 (FIEND_DOM)
    power_contested_streak: int = 0  # How long in contested territory
    last_power_shift: str = ""       # "F_TOOK", "B_TOOK", "CONTESTED"

    # Negative event tracking
    pending_negative_event: str = ""  # Event to trigger on next dialogue beat
    negative_event_cooldown: float = 0.0  # Prevent spam
    spank_intensity: int = 0          # Tracks spank force for TOO_HARD
    edge_permission_given: bool = False  # For PEAKS_INSIDE
    bathroom_denied: bool = False     # Currently denying bathroom
    denial_timer: float = 0.0         # How long until denial ends

    # ═══════════════════════════════════════════════════════════════════════════
    # V3 DEPTH SYSTEM - Invisible progress that drives dialogue evolution
    # ═══════════════════════════════════════════════════════════════════════════
    depth: float = 0.0              # 0.0 -> 1.0, NEVER SHOWN, only felt through dialogue
    depth_peak: float = 0.0         # Highest depth reached this session
    last_combo_depth_tick: int = 0  # Last combo value we gave depth for
    flow_start_time: float = 0.0    # When flow state started (combo > 5)
    in_flow: bool = False           # Currently in flow state

    # Breakthrough tracking (one-time special moments)
    breakthrough_30: bool = False   # First "good girl" territory
    breakthrough_50: bool = False   # First confession territory
    breakthrough_70: bool = False   # First break/overwhelm territory
    breakthrough_90: bool = False   # First mutual break territory

    def build_surge(self, amount: float, source: str = "hit"):
        """
        Build surge charge. TIERED PROGRESSION with friction reduction.

        Tier 1 (BLANK): 0.0 -> 1.0 - Safety net, EASY to get
        Tier 2 (PUSH): 1.0 -> 2.0 - Force escalation, requires skill
        Tier 3 (PERFECT): 2.0 -> 3.0 - Say the perfect thing, requires excellence

        FRICTION REDUCTION: Tier 1 charges from ANY hit.
        Subsequent tiers require perfects. Player learns mechanic with BLANK,
        then realizes "oh, if I play BETTER I get MORE tools."

        Building:
        - perfect: +0.20 (tier 1), +0.15 (tier 2+)
        - good: +0.10 (tier 1 only), +0.02 (tier 2+)
        - perfect_streak_5: bonus +0.25
        - perfect_streak_10: bonus +0.50
        - miss: -0.25 (tier 1), -0.40 (tier 2+), resets streak
        """
        if self.surge_cooldown > 0:
            return

        current_tier = int(self.surge_charge)

        if source == "perfect":
            self.surge_combo_streak += 1

            # Tier 1 charges faster with perfects
            if current_tier < 1:
                self.surge_charge = min(3.0, self.surge_charge + 0.20)
            else:
                self.surge_charge = min(3.0, self.surge_charge + 0.15)

            # Streak bonuses (apply at any tier)
            if self.surge_combo_streak == 5:
                self.surge_charge = min(3.0, self.surge_charge + 0.25)
            elif self.surge_combo_streak == 10:
                self.surge_charge = min(3.0, self.surge_charge + 0.50)
            elif self.surge_combo_streak == 15:
                self.surge_charge = 3.0  # Max out at 15 perfect streak

        elif source == "good":
            # FRICTION REDUCTION: Good hits charge tier 1 meaningfully
            if current_tier < 1:
                self.surge_charge = min(1.0, self.surge_charge + 0.10)  # Good hits cap at tier 1
            else:
                self.surge_charge = min(3.0, self.surge_charge + 0.02)
            # Good doesn't break streak but doesn't add to it

        elif source == "miss":
            # Less punishing at tier 1, more punishing at higher tiers
            if current_tier < 1:
                self.surge_charge = max(0.0, self.surge_charge - 0.25)
            else:
                self.surge_charge = max(0.0, self.surge_charge - 0.40)
            self.surge_combo_streak = 0

        # Update tier
        self.surge_tier = int(self.surge_charge)

    def get_surge_tier_name(self) -> str:
        """Get display name for current surge tier."""
        if self.surge_tier >= 3:
            return "PERFECT LINE"
        elif self.surge_tier >= 2:
            return "PUSH"
        elif self.surge_tier >= 1:
            return "BLANK"
        return ""

    def get_rhythm_surge_name(self) -> str:
        """Readable rhythm-facing surge identity."""
        if self.surge_tier >= 3:
            return "PULL"
        elif self.surge_tier >= 2:
            return "SMACK"
        elif self.surge_tier >= 1:
            return "THRUST"
        return ""

    def consume_rhythm_surge(self) -> str:
        """Spend rhythm surge.

        Suggestive restores the original BLANK safety net. Degradation alone
        exposes the later purple/red/green authored choreography.
        """
        if self.surge_cooldown > 0:
            return ""
        if not bool(self.surge_context_enabled):
            if self.surge_tier < 1:
                return ""
            self.surge_charge=max(0.0,self.surge_charge-1.0)
            self.surge_tier=int(self.surge_charge)
            self.surges_used+=1
            self.last_surge_type="blank"
            self.surge_cooldown=1.15
            self.surge_combo_streak=0
            return "blank"
        surge_kind = ""
        cost = 0.0
        if self.surge_tier >= 3:
            surge_kind = "green"
            cost = 0.95
        elif self.surge_tier >= 2:
            surge_kind = "red"
            cost = 0.75
        elif self.surge_tier >= 1:
            surge_kind = "purple"
            cost = 0.55
        if not surge_kind:
            return ""
        self.surge_charge = max(0.0, self.surge_charge - cost)
        self.surge_tier = int(self.surge_charge)
        self.surges_used += 1
        self.last_surge_type = surge_kind
        self.surge_cooldown = 0.85
        self.surge_combo_streak = 0
        return surge_kind

    def can_surge(self, context: str = "rhythm") -> bool:
        """Check if surge available for given context."""
        if self.surge_cooldown > 0:
            return False
        if context == "rhythm":
            return self.surge_tier >= 1  # BLANK or authored degradation surge
        elif context == "dialogue":
            return bool(self.surge_context_enabled) and self.surge_tier >= 2
        elif context == "choice":
            return bool(self.surge_context_enabled) and self.surge_tier >= 2
        return False

    def use_surge(self, context: str = "rhythm") -> str:
        """
        Use surge based on context. Returns surge type used or "".

        Rhythm -> Always BLANK (tier 1 cost)
        Dialogue -> PUSH if tier 2+, else nothing
        Choice -> PERFECT LINE if tier 3, else PUSH if tier 2
        """
        if self.surge_cooldown > 0:
            return ""
        if context != "rhythm" and not bool(self.surge_context_enabled):
            return ""

        surge_type = ""
        cost = 0.0

        if context == "rhythm" and self.surge_tier >= 1:
            surge_type = "blank"
            cost = 1.0
        elif context == "dialogue" and self.surge_tier >= 2:
            surge_type = "push"
            cost = 1.0  # Push costs 1 tier
        elif context == "choice":
            if self.surge_tier >= 3:
                surge_type = "perfect_line"
                cost = 2.0  # Perfect line costs 2 tiers (premium)
            elif self.surge_tier >= 2:
                surge_type = "push"
                cost = 1.0

        if surge_type:
            self.surge_charge = max(0.0, self.surge_charge - cost)
            self.surge_tier = int(self.surge_charge)
            self.surges_used += 1
            self.last_surge_type = surge_type
            self.surge_cooldown = 1.5  # Brief cooldown
            self.surge_combo_streak = 0
            return surge_type

        return ""

    def update_surge_cooldown(self, dt: float):
        """Update surge cooldown timer."""
        if self.surge_cooldown > 0:
            self.surge_cooldown = max(0.0, self.surge_cooldown - dt)

    def build_release(self, quality: str, attached: bool, release_open: bool) -> None:
        """Build the immediate release bar from clean attached play."""
        if not attached or not release_open:
            return
        gain = 0.0
        if quality == "perfect":
            gain = 0.16 + self.tier * 0.01
        elif quality == "good":
            gain = 0.08 + self.tier * 0.005
        if gain > 0.0:
            self.release_charge = min(1.0, self.release_charge + gain)

    def decay_release(self, dt: float, attached: bool, release_open: bool, qte_active: bool = False) -> None:
        """Release decays when the player loses control or backs off."""
        if qte_active:
            return
        if not attached:
            decay = 0.30 * dt
        elif not release_open:
            decay = 0.08 * dt
        else:
            decay = 0.015 * dt
        self.release_charge = max(0.0, self.release_charge - decay)

    def ready_for_commit(self, surge_charge: float, commit_stage: int = 0) -> bool:
        stage = max(0, min(2, int(commit_stage)))
        if stage <= 0:
            return self.release_charge >= 0.58
        if stage == 1:
            return self.release_charge >= 0.68 and surge_charge >= 1.40
        return self.release_charge >= 0.74 and surge_charge >= 1.95

    def reset_release(self) -> None:
        self.release_charge = 0.0

    def lose_life(self) -> int:
        self.cycle_lives = max(0, int(self.cycle_lives) - 1)
        return self.cycle_lives

    def restore_life(self) -> int:
        self.cycle_lives = min(int(self.max_cycle_lives), int(self.cycle_lives) + 1)
        return self.cycle_lives

    def get_power_mode(self) -> str:
        """Get current power dynamic mode."""
        if self.power_dynamic > 0.4:
            return "FIEND_DOM"
        elif self.power_dynamic < -0.4:
            return "BIRD_DOM"
        else:
            return "CONTESTED"

    def shift_power(self, amount: float, reason: str = ""):
        """Shift power dynamic. Positive = toward Fiend, negative = toward Bird."""
        old_mode = self.get_power_mode()
        self.power_dynamic = max(-1.0, min(1.0, self.power_dynamic + amount))
        new_mode = self.get_power_mode()

        if new_mode != old_mode:
            if new_mode == "FIEND_DOM":
                self.last_power_shift = "F_TOOK"
            elif new_mode == "BIRD_DOM":
                self.last_power_shift = "B_TOOK"
            else:
                self.last_power_shift = "CONTESTED"

        # Track contested streak
        if new_mode == "CONTESTED":
            self.power_contested_streak += 1
        else:
            self.power_contested_streak = 0

    def trigger_negative_event(self, event_type: str):
        """Queue a negative event for next dialogue beat."""
        if self.negative_event_cooldown <= 0:
            self.pending_negative_event = event_type
            self.negative_event_cooldown = 10.0  # 10 second cooldown

    def update_depth_from_hit(self, combo: int, is_perfect: bool = False):
        """
        Update depth on rhythm hit. Depth = invisible progress.

        Tuned for meaningful progression in 5-10 minutes:
        - Combo 20 -> ~0.2 (first modifiers/mutations)
        - Combo 50 -> ~0.4 (confessions start)
        - Combo 100 -> ~0.7 (breaking point)
        - Sustained play -> 0.9+ (transcendence)
        """
        # Combo milestone rewards (+0.04 per 10 combo)
        combo_milestone = (combo // 10) * 10
        if combo_milestone > self.last_combo_depth_tick:
            self.depth += 0.04 * ((combo_milestone - self.last_combo_depth_tick) // 10)
            self.last_combo_depth_tick = combo_milestone

        # Every hit adds small depth while in flow
        if combo >= 5:
            self.depth += 0.003  # Steady accumulation

        # Perfect hit bonus
        if is_perfect:
            self.depth += 0.015

        # Flow state check
        if combo >= 5 and not self.in_flow:
            self.in_flow = True
            self.flow_start_time = time.time()

        # Clamp and track peak
        self.depth = min(1.0, self.depth)
        self.depth_peak = max(self.depth_peak, self.depth)

        # Check breakthroughs
        self._check_breakthroughs()

    def update_depth_from_miss(self, combo_was: int):
        """Update depth on miss. Breaking combo = depth decay."""
        if combo_was >= 5:
            # Breaking a real combo hurts
            self.depth = max(0.0, self.depth - 0.02)

        # Exit flow state
        self.in_flow = False
        self.last_combo_depth_tick = 0

    def update_depth_from_flow(self, current_time: float):
        """Called periodically - depth grows while in flow state."""
        if self.in_flow and self.flow_start_time > 0:
            flow_duration = current_time - self.flow_start_time
            # +0.001 per second in flow, but diminishing
            flow_bonus = 0.001 * min(flow_duration, 60)  # Cap at 60 sec contribution
            self.depth = min(1.0, self.depth + flow_bonus * 0.01)  # Scaled down for per-call

    def update_depth_from_reversal(self, success: bool):
        """Reversal outcome affects depth significantly."""
        if success:
            self.depth = min(1.0, self.depth + 0.05)
        else:
            self.depth = max(0.0, self.depth - 0.03)
        self._check_breakthroughs()

    def depth_decay_idle(self, seconds_idle: float):
        """Depth decays if player is idle too long."""
        if seconds_idle > 3.0:
            decay = 0.01 * (seconds_idle - 3.0)
            self.depth = max(0.0, self.depth - decay)

    def _check_breakthroughs(self):
        """Check and mark breakthrough thresholds."""
        if self.depth >= 0.3 and not self.breakthrough_30:
            self.breakthrough_30 = True
        if self.depth >= 0.5 and not self.breakthrough_50:
            self.breakthrough_50 = True
        if self.depth >= 0.7 and not self.breakthrough_70:
            self.breakthrough_70 = True
        if self.depth >= 0.9 and not self.breakthrough_90:
            self.breakthrough_90 = True

    def get_depth_tier(self) -> str:
        """Get named tier for depth (for internal use)."""
        if self.depth < 0.2: return "surface"
        if self.depth < 0.4: return "warming"
        if self.depth < 0.6: return "deep"
        if self.depth < 0.8: return "breaking"
        return "transcendent"

    def update_pleasure_from_hit(self, combo: int, tier: int, pose: str):
        """Update pleasure on rhythm hit."""
        bal = self.balance or {}
        her_mult = float(bal.get("her_gain", 1.0))
        his_mult = float(bal.get("his_gain", 1.0))

        base_gain = 0.0008              # ↓ was 0.015  — 20-30min sessions
        combo_bonus = min(combo * 0.0001, 0.002)   # ↓ was combo*0.001, max 0.02
        tier_bonus = tier * 0.001       # ↓ was 0.005

        # Her pleasure
        self.her_pleasure = min(1.0, self.her_pleasure + (base_gain + combo_bonus + tier_bonus) * her_mult)

        # His pleasure builds independently
        his_base = 0.0007               # ↓ was 0.012
        if combo > 10:
            his_base += 0.00015 * (combo - 10)   # ↓ was 0.002
        if pose in ("squat", "angled_collapse", "downward"):
            his_base += 0.0003              # ↓ was 0.005
        self.his_pleasure = min(1.0, self.his_pleasure + his_base * his_mult)

        # V3: Also update depth
        self.update_depth_from_hit(combo, is_perfect=False)

    def update_pleasure_from_miss(self, tier: int):
        """Update on rhythm miss."""
        bal = self.balance or {}
        miss_mult = float(bal.get("miss_penalty", 1.0))
        self.her_pleasure = max(0.0, self.her_pleasure - (0.01 * (tier + 1)) * miss_mult)
        self.momentum = max(-1.0, self.momentum - 0.05 * miss_mult)

    def register_failure(self, failure_type: str):
        """Register a failure for consequence tracking."""
        self.last_failure_type = failure_type
        self.failure_acknowledged = False
        if failure_type == "slip":
            self.recent_slips += 1
        elif failure_type == "wrong_hole":
            self.recent_wrong_holes += 1

    def apply_choice_effect(self, effect: Dict):
        """Apply effects from a choice."""
        bal = self.balance or {}
        her_mult = float(bal.get("her_gain", 1.0))
        his_mult = float(bal.get("his_gain", 1.0))
        miss_mult = float(bal.get("miss_penalty", 1.0))
        mom_mult = float(bal.get("momentum_gain", 1.0))
        comp_drop = float(bal.get("composure_drop", 1.0))
        comp_rest = float(bal.get("composure_restore", 1.0))

        if "her_pleasure" in effect and effect["her_pleasure"] is not None:
            delta = float(effect["her_pleasure"])
            delta = delta * (her_mult if delta >= 0 else miss_mult)
            delta *= 0.35  # ↓ scale choice jumps for 20-30min sessions
            self.her_pleasure = max(0.0, min(1.0, self.her_pleasure + delta))

        if "his_pleasure" in effect and effect["his_pleasure"] is not None:
            delta = float(effect["his_pleasure"])
            delta = delta * (his_mult if delta >= 0 else miss_mult)
            delta *= 0.35  # ↓ scale choice jumps
            self.his_pleasure = max(0.0, min(1.0, self.his_pleasure + delta))

        if "momentum" in effect and effect["momentum"] is not None:
            delta = float(effect["momentum"])
            delta = delta * (mom_mult if delta >= 0 else miss_mult)
            self.momentum = max(-1.0, min(1.0, self.momentum + delta))

        if "composure" in effect and effect["composure"] is not None:
            delta = float(effect["composure"])
            delta = delta * (comp_rest if delta >= 0 else comp_drop)
            self.composure = max(0.0, min(1.0, self.composure + delta))
        if "her_pleasure_set" in effect and effect["her_pleasure_set"] is not None:
            self.her_pleasure = effect["her_pleasure_set"]


# ═══════════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════════
#
#                    🔗 DIALOGUE CASCADE SYSTEM 🔗
#
#     GRANULAR PER-LINE TRACKING WITH FULL CONTEXT PROPAGATION
#
#     Flow: Seed -> Choice -> Interjection -> Dialogue -> Skill -> Recalibrate -> Repeat
#
#     Every line is a LineEvent with:
#     - Who spoke (speaker)
#     - What triggered it (trigger_type: choice/hit/miss/interjection/cascade)
#     - Full context snapshot at moment of delivery
#     - Effect on trajectory (delta values)
#     - Cascade inheritance (what previous line led to this)
#
# ═══════════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════════

@dataclass
class ContextSnapshot:
    """Frozen state at moment a line is spoken."""
    timestamp: float = 0.0

    # Core metrics
    composure: float = 1.0
    momentum: float = 0.0
    her_pleasure: float = 0.0
    his_pleasure: float = 0.0
    power_dynamic: float = 0.0
    depth: float = 0.0

    # Rhythm state
    combo: int = 0
    tier: int = 0
    intensity: float = 0.0

    # Emotional state
    birdsong_state: str = "neutral"  # rambling/bratty/melting/needy/quiet
    fiend_mode: str = "tension"      # tension/escalation/feral

    # Session markers
    choices_this_session: int = 0
    interjections_this_session: int = 0
    lines_since_choice: int = 0
    lines_since_interjection: int = 0


@dataclass
class LineEvent:
    """A single line of dialogue with full cascade context."""
    event_id: str = ""              # Unique ID for this event
    timestamp: float = 0.0

    # The line itself
    speaker: str = ""               # FIEND/BIRDSONG/NARRATOR/SOUND
    text: str = ""
    line_id: str = ""               # If from authored pool

    # What triggered this line
    trigger_type: str = ""          # choice/hit/miss/interjection/cascade/scene/automatic
    trigger_source: str = ""        # The specific trigger (choice_id, "perfect_hit", etc)

    # Context at delivery
    context: ContextSnapshot = field(default_factory=ContextSnapshot)

    # Cascade inheritance
    parent_event_id: str = ""       # What line led to this one
    cascade_depth: int = 0          # How deep in current cascade
    branch_path: List[str] = field(default_factory=list)  # Path of choices taken

    # Effect on trajectory (deltas applied after this line)
    delta_composure: float = 0.0
    delta_momentum: float = 0.0
    delta_power: float = 0.0
    delta_depth: float = 0.0
    delta_pleasure: float = 0.0

    # Skill/mastery tracking
    tool_used: str = ""             # observe/command/escalate/ground/tease
    tool_effectiveness: float = 0.0  # 0-1, how well did it work

    # Modification flags
    was_interjected: bool = False   # Did an interjection modify this?
    interjection_type: str = ""     # What kind of interjection
    was_mutated: bool = False       # Was text mutated (stutter, trail, etc)
    mutation_type: str = ""         # What mutation applied


@dataclass
class TrajectoryState:
    """The current trajectory - where the scene is headed."""
    # Direction vectors (-1 to +1)
    emotional_direction: float = 0.0    # -1=retreating, +1=advancing
    power_direction: float = 0.0        # -1=B taking control, +1=F taking control
    intensity_direction: float = 0.0    # -1=cooling, +1=heating

    # Predicted destination
    predicted_ending: str = "gentle"    # gentle/intense/climax/interrupted/reversal
    ending_confidence: float = 0.5      # 0-1, how confident in prediction

    # Momentum accumulation
    consecutive_advances: int = 0
    consecutive_retreats: int = 0
    direction_locked: bool = False      # Can't easily reverse

    # Recalibration tracking
    recalibrations_this_session: int = 0
    last_recalibration_reason: str = ""


@dataclass
class CascadeStatistics:
    """Aggregate statistics from the cascade."""
    total_lines: int = 0
    total_choices: int = 0
    total_interjections: int = 0

    # By speaker
    fiend_lines: int = 0
    birdsong_lines: int = 0

    # By trigger type
    lines_from_choices: int = 0
    lines_from_hits: int = 0
    lines_from_misses: int = 0
    lines_from_interjections: int = 0
    lines_from_cascades: int = 0

    # Trajectory changes
    advances: int = 0
    retreats: int = 0
    plateaus: int = 0

    # Tool usage
    tool_usage: Dict[str, int] = field(default_factory=lambda: {
        'observe': 0, 'command': 0, 'escalate': 0, 'ground': 0, 'tease': 0
    })
    tool_success: Dict[str, float] = field(default_factory=lambda: {
        'observe': 0.0, 'command': 0.0, 'escalate': 0.0, 'ground': 0.0, 'tease': 0.0
    })

    # Key moments
    breakthroughs: int = 0
    breakdowns: int = 0
    reversals: int = 0


class DialogueCascade:
    """
    Master tracking system for the full dialogue cascade.

    Records every line with full context, tracks trajectory,
    enables granular recalibration, and informs ending selection.
    """

    def __init__(self):
        self.events: List[LineEvent] = []
        self.trajectory = TrajectoryState()
        self.statistics = CascadeStatistics()

        # Active cascade tracking
        self.current_cascade_root: str = ""
        self.cascade_depth: int = 0
        self.branch_path: List[str] = []

        # Pending effects
        self.pending_interjection: Optional[str] = None
        self.pending_mutation: Optional[str] = None

        # Seed tracking
        self.session_seed: int = 0
        self.cascade_seeds: List[int] = []

        # Event ID counter
        self._event_counter: int = 0

    def _generate_event_id(self) -> str:
        """Generate unique event ID."""
        self._event_counter += 1
        return f"evt_{self._event_counter:05d}"

    def snapshot_context(self, round_state, session_state, vibe, rhythm) -> ContextSnapshot:
        """Capture current context as frozen snapshot."""
        return ContextSnapshot(
            timestamp=time.time(),
            composure=round_state.composure,
            momentum=round_state.momentum,
            her_pleasure=round_state.her_pleasure,
            his_pleasure=round_state.his_pleasure,
            power_dynamic=round_state.power_dynamic,
            depth=round_state.depth,
            combo=vibe.combo if vibe else 0,
            tier=round_state.tier,
            intensity=rhythm.intensity if rhythm else 0.0,
            birdsong_state=getattr(round_state, 'birdsong_state', 'neutral'),
            fiend_mode=getattr(session_state, 'fiend_mode', 'tension'),
            choices_this_session=self.statistics.total_choices,
            interjections_this_session=self.statistics.total_interjections,
            lines_since_choice=self._lines_since_trigger('choice'),
            lines_since_interjection=self._lines_since_trigger('interjection')
        )

    def _lines_since_trigger(self, trigger_type: str) -> int:
        """Count lines since last occurrence of trigger type."""
        count = 0
        for event in reversed(self.events):
            if event.trigger_type == trigger_type:
                return count
            count += 1
        return count

    def record_line(self,
                    speaker: str,
                    text: str,
                    trigger_type: str,
                    trigger_source: str,
                    context: ContextSnapshot,
                    line_id: str = "",
                    tool_used: str = "",
                    tool_effectiveness: float = 0.0) -> LineEvent:
        """
        Record a line and calculate its trajectory effect.
        Returns the created LineEvent.
        """
        # Safety: ensure text is a string
        if not isinstance(text, str):
            text = str(text) if text is not None else ""

        event = LineEvent(
            event_id=self._generate_event_id(),
            timestamp=time.time(),
            speaker=speaker,
            text=text,
            line_id=line_id,
            trigger_type=trigger_type,
            trigger_source=trigger_source,
            context=context,
            parent_event_id=self.events[-1].event_id if self.events else "",
            cascade_depth=self.cascade_depth,
            branch_path=self.branch_path.copy(),
            tool_used=tool_used,
            tool_effectiveness=tool_effectiveness,
            was_interjected=self.pending_interjection is not None,
            interjection_type=self.pending_interjection or "",
            was_mutated=self.pending_mutation is not None,
            mutation_type=self.pending_mutation or ""
        )

        # Clear pending modifiers
        self.pending_interjection = None
        self.pending_mutation = None

        # Calculate trajectory deltas
        event = self._calculate_deltas(event)

        # Record
        self.events.append(event)

        # Update statistics
        self._update_statistics(event)

        # Recalibrate trajectory
        self._recalibrate_trajectory(event)

        return event

    def _calculate_deltas(self, event: LineEvent) -> LineEvent:
        """Calculate how this line affects trajectory."""
        text_lower = event.text.lower() if event.text else ""
        speaker = event.speaker
        ctx = event.context

        # Base deltas from content analysis
        delta_composure = 0.0
        delta_momentum = 0.0
        delta_power = 0.0
        delta_depth = 0.0
        delta_pleasure = 0.0

        # === SPEAKER-BASED EFFECTS ===
        if speaker == "BIRDSONG":
            # Vulnerability indicators
            if any(w in text_lower for w in ['...', 'hahhh', 'ghhh', 'mwehh']):
                delta_composure -= 0.02
                delta_depth += 0.01

            # Bratty indicators
            if any(w in text_lower for w in ['baka', 'idiot', 'make me', 'no']):
                delta_power -= 0.03  # B gaining ground
                delta_momentum += 0.01

            # Melting indicators
            if any(w in text_lower for w in ['please', 'more', "don't stop", 'yes']):
                delta_power += 0.02  # F has control
                delta_depth += 0.02
                delta_pleasure += 0.02

            # Need indicators
            if any(w in text_lower for w in ['fiend', 'need', 'want']):
                delta_depth += 0.01
                delta_pleasure += 0.01

        elif speaker == "FIEND":
            # Dominant indicators
            if any(w in text_lower for w in ['good girl', 'stay', 'mine', 'now']):
                delta_power += 0.03
                delta_momentum += 0.02

            # Grounding indicators
            if any(w in text_lower for w in ['breathe', "i've got you", "i'm here", 'easy']):
                delta_composure += 0.03
                delta_power += 0.01

            # Soft indicators
            if any(w in text_lower for w in ['...', 'mm', 'hey']):
                delta_depth += 0.01

        # === TRIGGER-BASED EFFECTS ===
        if event.trigger_type == "hit":
            delta_momentum += 0.01
            delta_pleasure += 0.01
        elif event.trigger_type == "miss":
            delta_momentum -= 0.02
            delta_composure -= 0.01
        elif event.trigger_type == "choice":
            delta_depth += 0.01  # Choices always advance depth
        elif event.trigger_type == "interjection":
            # Interjections can shift trajectory
            if event.interjection_type == "ground":
                delta_composure += 0.05
            elif event.interjection_type == "escalate":
                delta_momentum += 0.05
            elif event.interjection_type == "poke":
                delta_momentum += 0.02

        # === TOOL EFFECTIVENESS ===
        if event.tool_used and event.tool_effectiveness > 0:
            if event.tool_used == "observe":
                delta_depth += 0.02 * event.tool_effectiveness
            elif event.tool_used == "command":
                delta_power += 0.03 * event.tool_effectiveness
            elif event.tool_used == "escalate":
                delta_momentum += 0.03 * event.tool_effectiveness
            elif event.tool_used == "ground":
                delta_composure += 0.04 * event.tool_effectiveness
            elif event.tool_used == "tease":
                delta_pleasure += 0.02 * event.tool_effectiveness

        # Apply to event
        event.delta_composure = delta_composure
        event.delta_momentum = delta_momentum
        event.delta_power = delta_power
        event.delta_depth = delta_depth
        event.delta_pleasure = delta_pleasure

        return event

    def _update_statistics(self, event: LineEvent):
        """Update aggregate statistics."""
        self.statistics.total_lines += 1

        # By speaker
        if event.speaker == "FIEND":
            self.statistics.fiend_lines += 1
        elif event.speaker == "BIRDSONG":
            self.statistics.birdsong_lines += 1

        # By trigger
        if event.trigger_type == "choice":
            self.statistics.lines_from_choices += 1
            self.statistics.total_choices += 1
        elif event.trigger_type == "hit":
            self.statistics.lines_from_hits += 1
        elif event.trigger_type == "miss":
            self.statistics.lines_from_misses += 1
        elif event.trigger_type == "interjection":
            self.statistics.lines_from_interjections += 1
            self.statistics.total_interjections += 1
        elif event.trigger_type == "cascade":
            self.statistics.lines_from_cascades += 1

        # Tool tracking
        if event.tool_used:
            self.statistics.tool_usage[event.tool_used] = \
                self.statistics.tool_usage.get(event.tool_used, 0) + 1

            # Running average of effectiveness
            current = self.statistics.tool_success.get(event.tool_used, 0.0)
            count = self.statistics.tool_usage[event.tool_used]
            self.statistics.tool_success[event.tool_used] = \
                (current * (count - 1) + event.tool_effectiveness) / count

    def _recalibrate_trajectory(self, event: LineEvent):
        """Recalibrate trajectory prediction based on new event."""
        traj = self.trajectory

        # Update direction vectors from delta
        if event.delta_momentum > 0.01:
            traj.emotional_direction = min(1.0, traj.emotional_direction + 0.1)
            traj.consecutive_advances += 1
            traj.consecutive_retreats = 0
            self.statistics.advances += 1
        elif event.delta_momentum < -0.01:
            traj.emotional_direction = max(-1.0, traj.emotional_direction - 0.1)
            traj.consecutive_retreats += 1
            traj.consecutive_advances = 0
            self.statistics.retreats += 1
        else:
            self.statistics.plateaus += 1

        traj.power_direction = (traj.power_direction * 0.9) + (event.delta_power * 0.1)
        traj.intensity_direction = (traj.intensity_direction * 0.9) + (event.delta_pleasure * 0.1)

        # Lock direction if consistent
        if traj.consecutive_advances >= 5:
            traj.direction_locked = True
        elif traj.consecutive_retreats >= 5:
            traj.direction_locked = True

        # Predict ending
        self._predict_ending(event)

    def _predict_ending(self, latest_event: LineEvent):
        """Predict ending based on cascade history."""
        ctx = latest_event.context
        traj = self.trajectory

        # Score each ending type
        scores = {
            'gentle': 0.0,
            'intense': 0.0,
            'climax': 0.0,
            'interrupted': 0.0,
            'reversal': 0.0
        }

        # From current state
        if ctx.composure > 0.7:
            scores['gentle'] += 0.3
        elif ctx.composure < 0.3:
            scores['intense'] += 0.3
            scores['climax'] += 0.2

        if ctx.her_pleasure > 0.7:
            scores['climax'] += 0.4

        if ctx.momentum > 0.5:
            scores['intense'] += 0.2
        elif ctx.momentum < -0.3:
            scores['interrupted'] += 0.3

        # From trajectory
        if traj.emotional_direction > 0.5:
            scores['climax'] += 0.2
            scores['intense'] += 0.2
        elif traj.emotional_direction < -0.5:
            scores['gentle'] += 0.2
            scores['interrupted'] += 0.1

        if traj.direction_locked:
            # Boost the direction we're locked into
            if traj.consecutive_advances >= 5:
                scores['climax'] += 0.3
            elif traj.consecutive_retreats >= 5:
                scores['interrupted'] += 0.3

        # From statistics
        if self.statistics.breakthroughs > 0:
            scores['climax'] += 0.2
        if self.statistics.breakdowns > 0:
            scores['reversal'] += 0.2

        # Pick highest
        best_ending = max(scores, key=scores.get)
        best_score = scores[best_ending]
        total_score = sum(scores.values())

        traj.predicted_ending = best_ending
        traj.ending_confidence = best_score / total_score if total_score > 0 else 0.5

    def record_choice(self, choice_id: str, options: List[str], context: ContextSnapshot):
        """Record a choice point and update branch path."""
        self.branch_path.append(choice_id)
        self.cascade_depth += 1
        self.cascade_seeds.append(hash(choice_id) % 1000)

    def record_interjection(self, interjection_type: str, reason: str):
        """Mark next line as interjected."""
        self.pending_interjection = interjection_type
        self.trajectory.recalibrations_this_session += 1
        self.trajectory.last_recalibration_reason = reason

    def record_mutation(self, mutation_type: str):
        """Mark next line as mutated."""
        self.pending_mutation = mutation_type

    def record_breakthrough(self):
        """Record a breakthrough moment."""
        self.statistics.breakthroughs += 1

    def record_breakdown(self):
        """Record a breakdown moment."""
        self.statistics.breakdowns += 1

    def record_reversal(self):
        """Record a reversal."""
        self.statistics.reversals += 1

    def get_cascade_context(self) -> Dict:
        """Get current cascade state for dialogue selection."""
        recent_events = self.events[-10:] if self.events else []

        return {
            'total_lines': self.statistics.total_lines,
            'cascade_depth': self.cascade_depth,
            'branch_path': self.branch_path,
            'trajectory': {
                'emotional': self.trajectory.emotional_direction,
                'power': self.trajectory.power_direction,
                'intensity': self.trajectory.intensity_direction,
                'locked': self.trajectory.direction_locked
            },
            'predicted_ending': self.trajectory.predicted_ending,
            'ending_confidence': self.trajectory.ending_confidence,
            'recent_speakers': [e.speaker for e in recent_events],
            'recent_triggers': [e.trigger_type for e in recent_events],
            'lines_since_choice': self._lines_since_trigger('choice'),
            'lines_since_interjection': self._lines_since_trigger('interjection'),
            'tool_mastery': self.statistics.tool_success,
            'breakthroughs': self.statistics.breakthroughs
        }

    def select_ending(self) -> Tuple[str, float]:
        """
        Select ending based on full cascade history.
        Returns (ending_type, confidence).
        """
        return (self.trajectory.predicted_ending, self.trajectory.ending_confidence)

    def get_summary(self) -> Dict:
        """Get full cascade summary for debug/display."""
        return {
            'events': len(self.events),
            'statistics': {
                'total_lines': self.statistics.total_lines,
                'fiend_lines': self.statistics.fiend_lines,
                'birdsong_lines': self.statistics.birdsong_lines,
                'choices': self.statistics.total_choices,
                'interjections': self.statistics.total_interjections,
                'breakthroughs': self.statistics.breakthroughs,
                'breakdowns': self.statistics.breakdowns,
                'reversals': self.statistics.reversals
            },
            'trajectory': {
                'predicted_ending': self.trajectory.predicted_ending,
                'confidence': self.trajectory.ending_confidence,
                'direction_locked': self.trajectory.direction_locked,
                'consecutive_advances': self.trajectory.consecutive_advances,
                'consecutive_retreats': self.trajectory.consecutive_retreats
            },
            'tool_mastery': self.statistics.tool_success
        }

    # ═══════════════════════════════════════════════════════════════════════════
    # SEEDED DETERMINISM - Reproducible cascades from seed+state
    # ═══════════════════════════════════════════════════════════════════════════

    def get_cascade_seed(self) -> int:
        """
        Get deterministic seed based on cascade state.
        Same cascade path = same seed = same results.
        """
        # Combine session seed with branch path
        path_hash = hash(tuple(self.branch_path)) if self.branch_path else 0
        state_hash = hash((
            self.statistics.total_lines,
            self.statistics.total_choices,
            len(self.events)
        ))
        return (self.session_seed + path_hash + state_hash) % 100000

    def seeded_choice(self, options: List[str], weights: List[float] = None) -> str:
        """
        Make a seeded choice from options - deterministic given cascade state.
        """
        seed = self.get_cascade_seed()
        rng = random.Random(seed + len(self.events))

        if weights:
            # Weighted selection
            total = sum(weights)
            r = rng.random() * total
            cumulative = 0.0
            for opt, w in zip(options, weights):
                cumulative += w
                if r <= cumulative:
                    return opt
            return options[-1]
        else:
            return rng.choice(options)

    def seeded_float(self) -> float:
        """Get seeded random float 0-1."""
        seed = self.get_cascade_seed()
        rng = random.Random(seed + len(self.events))
        return rng.random()

    # ═══════════════════════════════════════════════════════════════════════════
    # DIALOGUE SELECTION - Use trajectory to influence what comes next
    # ═══════════════════════════════════════════════════════════════════════════

    def get_dialogue_weights(self, options: Dict[str, float]) -> Dict[str, float]:
        """
        Adjust dialogue option weights based on trajectory.

        options: {"gentle_line": 1.0, "intense_line": 1.0, ...}
        returns: adjusted weights based on current trajectory
        """
        traj = self.trajectory
        adjusted = options.copy()

        # Boost options that match trajectory direction
        for key in adjusted:
            key_lower = key.lower()

            # Emotional direction
            if traj.emotional_direction > 0.3:
                if any(w in key_lower for w in ['intense', 'heat', 'more', 'escalate']):
                    adjusted[key] *= 1.5
                if any(w in key_lower for w in ['gentle', 'soft', 'retreat']):
                    adjusted[key] *= 0.6
            elif traj.emotional_direction < -0.3:
                if any(w in key_lower for w in ['gentle', 'soft', 'retreat']):
                    adjusted[key] *= 1.5
                if any(w in key_lower for w in ['intense', 'heat', 'more']):
                    adjusted[key] *= 0.6

            # Power direction
            if traj.power_direction > 0.3:  # Fiend dominant
                if any(w in key_lower for w in ['dom', 'command', 'control']):
                    adjusted[key] *= 1.4
                if any(w in key_lower for w in ['sub', 'brat', 'resist']):
                    adjusted[key] *= 0.7
            elif traj.power_direction < -0.3:  # Bird dominant
                if any(w in key_lower for w in ['sub', 'brat', 'resist']):
                    adjusted[key] *= 1.4
                if any(w in key_lower for w in ['dom', 'command', 'control']):
                    adjusted[key] *= 0.7

            # Locked direction - stronger bias
            if traj.direction_locked:
                if traj.consecutive_advances >= 5:
                    if any(w in key_lower for w in ['climax', 'peak', 'break']):
                        adjusted[key] *= 2.0
                elif traj.consecutive_retreats >= 5:
                    if any(w in key_lower for w in ['stop', 'pause', 'end']):
                        adjusted[key] *= 2.0

        return adjusted

    def should_interjection_fire(self, base_chance: float, interjection_type: str) -> bool:
        """
        Determine if an interjection should fire based on trajectory.
        Uses seeded randomness for reproducibility.
        """
        traj = self.trajectory

        # Adjust chance based on trajectory
        adjusted_chance = base_chance

        if interjection_type == "ground":
            # Grounding more likely when retreating
            if traj.emotional_direction < -0.2:
                adjusted_chance *= 1.5
            if traj.consecutive_retreats >= 3:
                adjusted_chance *= 1.3
        elif interjection_type == "escalate":
            # Escalation more likely when advancing
            if traj.emotional_direction > 0.2:
                adjusted_chance *= 1.5
            if traj.consecutive_advances >= 3:
                adjusted_chance *= 1.3
        elif interjection_type == "poke":
            # Pokes more likely in neutral/contested
            if abs(traj.power_direction) < 0.2:
                adjusted_chance *= 1.4
        elif interjection_type == "tease":
            # Teases more likely when Bird has power
            if traj.power_direction < -0.2:
                adjusted_chance *= 1.5

        # Don't spam interjections
        lines_since = self._lines_since_trigger('interjection')
        if lines_since < 3:
            adjusted_chance *= 0.3
        elif lines_since < 5:
            adjusted_chance *= 0.6

        # Use seeded random for determinism
        return self.seeded_float() < adjusted_chance

    def get_next_line_modifiers(self) -> Dict[str, any]:
        """
        Get modifiers to apply to the next line based on trajectory.
        Called before dialogue generation.
        """
        traj = self.trajectory
        ctx = self.get_cascade_context()

        modifiers = {
            'intensity_bias': 0.0,
            'vulnerability_bias': 0.0,
            'power_bias': 0.0,
            'stutter_chance': 0.0,
            'trail_off_chance': 0.0,
            'repeat_chance': 0.0,
            'suggested_mutation': None
        }

        # Intensity modifiers
        if traj.emotional_direction > 0.5:
            modifiers['intensity_bias'] = 0.2
            modifiers['stutter_chance'] = 0.15
        elif traj.emotional_direction < -0.3:
            modifiers['intensity_bias'] = -0.1
            modifiers['trail_off_chance'] = 0.1

        # Vulnerability modifiers
        if ctx.get('lines_since_choice', 100) < 3:
            # Just made a choice - more vulnerable
            modifiers['vulnerability_bias'] = 0.15

        # Power modifiers
        modifiers['power_bias'] = traj.power_direction * 0.1

        # Suggest mutations based on state
        if traj.direction_locked and traj.consecutive_advances >= 5:
            if self.seeded_float() < 0.3:
                modifiers['suggested_mutation'] = 'breaking'

        return modifiers

    # ═══════════════════════════════════════════════════════════════════════════
    # ENDING SELECTION - Full cascade-aware ending determination
    # ═══════════════════════════════════════════════════════════════════════════

    def determine_ending(self, her_pleasure: float, composure: float,
                        session_minutes: float, player_quit: bool = False) -> Tuple[str, Dict]:
        """
        Determine the appropriate ending based on full cascade history.

        Returns: (ending_type, ending_context)

        ending_type: 'climax', 'gentle', 'interrupted', 'timeout', 'early_quit'
        ending_context: dict with scene selection hints
        """
        traj = self.trajectory
        stats = self.statistics

        # Early quit handling
        if player_quit:
            if session_minutes < 2.0:
                return ('early_quit', {
                    'reason': 'very_early',
                    'scene': 'quick_goodbye'
                })
            elif stats.total_lines < 20:
                return ('early_quit', {
                    'reason': 'before_connection',
                    'scene': 'awkward_goodbye'
                })
            else:
                return ('interrupted', {
                    'reason': 'player_choice',
                    'scene': 'gentle_stop',
                    'power_at_end': traj.power_direction
                })

        # Climax ending
        # Time gate: climax requires at least 15 minutes of active play
        _session_elapsed = time.time() - getattr(self, '_session_start_ts', time.time())
        if not hasattr(self, '_session_start_ts'):
            self._session_start_ts = time.time()
        _gate_open = _session_elapsed >= 900.0  # 15 minutes
        if her_pleasure >= 0.9 and _gate_open:
            # Determine climax flavor based on trajectory
            if traj.power_direction > 0.4:
                climax_flavor = 'fiend_leads'
            elif traj.power_direction < -0.3:
                climax_flavor = 'bird_takes'
            elif stats.breakthroughs > 0:
                climax_flavor = 'breakthrough'
            else:
                climax_flavor = 'mutual'

            return ('climax', {
                'flavor': climax_flavor,
                'intensity': traj.intensity_direction,
                'scene': f'climax_{climax_flavor}',
                'composure_at_end': composure,
                'power_at_end': traj.power_direction
            })

        # Gentle ending
        if her_pleasure >= 0.5 and composure > 0.5:
            return ('gentle', {
                'flavor': 'satisfied' if her_pleasure > 0.7 else 'sweet',
                'scene': 'gentle_wind_down',
                'depth_reached': len(self.branch_path)
            })

        # Interrupted/timeout
        if session_minutes > 30:
            return ('timeout', {
                'reason': 'session_length',
                'scene': 'tired_but_happy' if her_pleasure > 0.5 else 'exhausted'
            })

        # Default based on trajectory
        predicted, confidence = self.select_ending()
        return (predicted, {
            'confidence': confidence,
            'scene': f'{predicted}_default',
            'trajectory_state': {
                'emotional': traj.emotional_direction,
                'power': traj.power_direction,
                'locked': traj.direction_locked
            }
        })

    # ═══════════════════════════════════════════════════════════════════════════
    # CASCADE EXPORT - For debug/replay/analysis
    # ═══════════════════════════════════════════════════════════════════════════

    def export_cascade(self) -> Dict:
        """Export full cascade for analysis/replay."""
        return {
            'session_seed': self.session_seed,
            'branch_path': self.branch_path,
            'events': [
                {
                    'id': e.event_id,
                    'speaker': e.speaker,
                    'text': e.text[:50] + '...' if len(e.text) > 50 else e.text,
                    'trigger': e.trigger_type,
                    'trigger_source': e.trigger_source,
                    'cascade_depth': e.cascade_depth,
                    'deltas': {
                        'composure': e.delta_composure,
                        'momentum': e.delta_momentum,
                        'power': e.delta_power,
                        'depth': e.delta_depth
                    },
                    'interjected': e.was_interjected,
                    'mutated': e.was_mutated
                }
                for e in self.events[-50:]  # Last 50 events
            ],
            'trajectory': {
                'emotional': self.trajectory.emotional_direction,
                'power': self.trajectory.power_direction,
                'intensity': self.trajectory.intensity_direction,
                'locked': self.trajectory.direction_locked,
                'predicted_ending': self.trajectory.predicted_ending,
                'confidence': self.trajectory.ending_confidence
            },
            'statistics': {
                'total_lines': self.statistics.total_lines,
                'choices': self.statistics.total_choices,
                'interjections': self.statistics.total_interjections,
                'breakthroughs': self.statistics.breakthroughs,
                'reversals': self.statistics.reversals
            }
        }


# ═══════════════════════════════════════════════════════════════════════════════
#                    🔥 REVERSAL GAMBIT SYSTEM 🔥
#              "I can do better" - at the cost of future sanity
# ═══════════════════════════════════════════════════════════════════════════════

@dataclass
class ReversalState:
    """
    Reversal Gambit tracking.

    When you're losing, press [R] to:
    - Restore grip, preserve combo, boost pleasure
    - Get brief invincibility shield
    BUT:
    - Content tier escalates permanently (this session)
    - 30-second "PROVE IT" difficulty spike
    - Can't opt out of escalated content
    """
    # Content escalation (0=vanilla, 1=heated, 2=feral, 3=unhinged)
    content_tier: int = 0

    # Reversal availability
    reversal_available: bool = False
    reversal_window_timer: float = 0.0  # How long [R] prompt shows

    # Post-reversal spike
    in_spike: bool = False
    spike_timer: float = 0.0            # Countdown during spike
    spike_misses: int = 0               # Misses during spike (2 = fail)

    # Shield (brief invincibility after reversal)
    shield_active: bool = False
    shield_timer: float = 0.0

    # Tracking
    reversals_used: int = 0
    reversals_expired: int = 0           # Chances not taken - meaningful!
    spikes_survived: int = 0
    spikes_failed: int = 0

    # Why reversal became available
    trigger_reason: str = ""  # "low_grip", "slip", "combo_break", "miss_streak"
    last_expired_reason: str = ""        # For dialogue selection

    def can_reversal(self) -> bool:
        """Check if reversal can be activated."""
        return self.reversal_available and self.content_tier < 3

    def activate_reversal(self) -> int:
        """Activate reversal, return new content tier."""
        self.reversal_available = False
        self.reversal_window_timer = 0.0
        self.content_tier = min(3, self.content_tier + 1)
        self.reversals_used += 1

        # Start spike
        self.in_spike = True
        self.spike_timer = 12.0
        self.spike_misses = 0

        # Start shield
        self.shield_active = True
        self.shield_timer = 1.5  # 1.5 seconds of invincibility

        return self.content_tier

    def update(self, dt: float) -> str:
        """
        Update timers. Returns event string if something significant happened.
        Events: "expired" (reversal window closed without use)
        """
        event = ""

        if self.reversal_window_timer > 0:
            self.reversal_window_timer -= dt
            if self.reversal_window_timer <= 0:
                if self.reversal_available:
                    # EXPIRATION PENALTY - You had the chance and didn't take it
                    event = "expired"
                    self.reversals_expired += 1
                    self.last_expired_reason = self.trigger_reason
                self.reversal_available = False

        if self.spike_timer > 0:
            self.spike_timer -= dt
            if self.spike_timer <= 0:
                self.in_spike = False
                self.spikes_survived += 1

        if self.shield_timer > 0:
            self.shield_timer -= dt
            if self.shield_timer <= 0:
                self.shield_active = False

        return event

    def trigger_availability(self, reason: str, duration: float = 4.0):
        """Make reversal available for a window. Default 4 seconds now."""
        if self.content_tier < 3 and not self.in_spike:
            self.reversal_available = True
            self.reversal_window_timer = duration
            self.trigger_reason = reason

    def spike_miss(self) -> bool:
        """Register a miss during spike. Returns True if spike failed."""
        if self.shield_active:
            return False  # Shield absorbs

        self.spike_misses += 1
        if self.spike_misses >= 2:
            self.in_spike = False
            self.spike_timer = 0.0
            self.spikes_failed += 1
            return True
        return False

    def get_difficulty_multipliers(self) -> Tuple[float, float, float]:
        """Get (bpm_mult, window_mult, density_mult) for current state."""
        if self.in_spike:
            # PROVE IT mode - harder than anything
            return (1.25, 0.70, 1.5)  # +25% BPM, -30% window, +50% notes
        return (1.0, 1.0, 1.0)


