@dataclass
class SessionState:
    """State for current play session - resets each run."""
    unlocked_moves: List[str] = field(default_factory=list)    # pull, edge_mastery, etc
    active_modes: List[str] = field(default_factory=list)      # love_bunny, starving, hump_dog
    fiend_mood: str = "patient"                                 # patient/eager/feral
    birdsong_state: str = "guarded"                            # guarded/warming/open/melting

    scenes_played: Dict[str, List[int]] = field(default_factory=dict)  # Track used scenes
    choices_made: List[Tuple[str, str]] = field(default_factory=list)  # (fork_id, choice)

    # Session stats
    total_pleasure_given: float = 0.0
    total_tier_time: Dict[int, float] = field(default_factory=dict)  # Time spent at each tier
    highest_tier_reached: int = 0
    transcendence_attempts: int = 0
    transcendence_successes: int = 0

    # ═══════════════════════════════════════════════════════════════════════════
    #              SESSION ARC SYSTEM
    #              "20 minutes should feel like a story"
    # ═══════════════════════════════════════════════════════════════════════════

    session_start_time: float = 0.0
    session_phase: str = "warmup"  # warmup -> building -> peak -> resolution
    phase_start_time: float = 0.0

    # Phase timing (in seconds)
    PHASE_TIMES = {
        "warmup": (0, 300),        # 0-5 min: Learning each other
        "building": (300, 720),    # 5-12 min: Intensity rises
        "peak": (720, 1080),       # 12-18 min: Maximum intensity
        "resolution": (1080, 1500) # 18-25 min: Climax approaches
    }

    # Milestones (session time -> event)
    milestones_triggered: List[str] = field(default_factory=list)

    def update_phase(self, current_time: float):
        """Update session phase based on elapsed time."""
        elapsed = current_time - self.session_start_time

        old_phase = self.session_phase

        if elapsed < 300:
            self.session_phase = "warmup"
        elif elapsed < 720:
            self.session_phase = "building"
        elif elapsed < 1080:
            self.session_phase = "peak"
        else:
            self.session_phase = "resolution"

        # Track phase changes
        if self.session_phase != old_phase:
            self.phase_start_time = current_time
            return self.session_phase  # Return new phase for notification
        return None

    def get_phase_progress(self, current_time: float) -> float:
        """Get 0.0-1.0 progress through current phase."""
        elapsed = current_time - self.session_start_time
        phase_times = self.PHASE_TIMES.get(self.session_phase, (0, 300))
        phase_elapsed = elapsed - phase_times[0]
        phase_duration = phase_times[1] - phase_times[0]
        return min(1.0, max(0.0, phase_elapsed / phase_duration))

    def check_milestone(self, current_time: float) -> Optional[str]:
        """Check if a milestone should trigger."""
        elapsed = current_time - self.session_start_time

        milestones = {
            300: "five_min",      # 5 min: "Still here?"
            600: "ten_min",       # 10 min: Trust bonus
            900: "fifteen_min",   # 15 min: Content check
            1200: "twenty_min",   # 20 min: Climax window
        }

        for time_threshold, milestone_id in milestones.items():
            if elapsed >= time_threshold and milestone_id not in self.milestones_triggered:
                self.milestones_triggered.append(milestone_id)
                return milestone_id

        return None

    def get_phase_modifiers(self) -> Dict:
        """Get gameplay modifiers based on current phase."""
        return {
            "warmup": {
                "intensity_cap": 0.6,      # Gentle maximum
                "dialogue_mood": "tender",
                "reversal_available": False,
                "content_gate": 0,
            },
            "building": {
                "intensity_cap": 0.85,
                "dialogue_mood": "playful",
                "reversal_available": True,
                "content_gate": 1,
            },
            "peak": {
                "intensity_cap": 1.0,
                "dialogue_mood": "heated",
                "reversal_available": True,
                "content_gate": 2,
            },
            "resolution": {
                "intensity_cap": 1.0,
                "dialogue_mood": "desperate",
                "reversal_available": True,
                "content_gate": 3,
            },
        }.get(self.session_phase, {})

    def unlock_move(self, move: str) -> bool:
        """Unlock a move if not already unlocked. Returns True if newly unlocked."""
        if move not in self.unlocked_moves:
            self.unlocked_moves.append(move)
            return True
        return False

    def activate_mode(self, mode: str) -> bool:
        """Activate a mode for this session."""
        if mode not in self.active_modes:
            self.active_modes.append(mode)
            return True
        return False

    def update_birdsong_state(self, composure: float, pleasure: float):
        """Update Birdsong's state based on composure and pleasure."""
        if composure > 0.7:
            self.birdsong_state = "guarded"
        elif composure > 0.4:
            self.birdsong_state = "warming"
        elif pleasure > 0.7:
            self.birdsong_state = "melting"
        else:
            self.birdsong_state = "open"


