def build_scenario_dialogue(scenario_id: str, intensity: float = 0.5) -> List[List[Tuple[str, str]]]:
    """
    Build a full dialogue sequence from a scenario.

    This is the ASSEMBLER - it takes the grammar atoms and the scenario recipe
    and constructs actual dialogue that will be different each time.
    """
    import random

    scenario = SCENARIOS.get(scenario_id)
    if not scenario:
        return []

    dialogue_sequences = []

    for beat_type, atom_types, mood in scenario.beats:
        beat_lines = []

        # Determine speaker order
        if beat_type == "F_first" or beat_type == "F_lead" or beat_type.startswith("F_"):
            speakers = ["FIEND", "BIRDSONG"]
        elif beat_type == "B_first" or beat_type == "B_lead" or beat_type.startswith("B_"):
            speakers = ["BIRDSONG", "FIEND"]
        elif beat_type == "mutual" or beat_type == "interleave":
            speakers = random.choice([["FIEND", "BIRDSONG"], ["BIRDSONG", "FIEND"]])
        else:
            speakers = ["FIEND", "BIRDSONG"]

        # Pull atoms based on beat specification
        for i, atom_type in enumerate(atom_types):
            speaker = speakers[i % 2]

            # Get the appropriate pool
            pool_key = atom_type
            if "_B" in atom_type or "_F" in atom_type:
                pool_key = atom_type
            else:
                # Generic type - pick speaker-appropriate version if exists
                speaker_suffix = "_F" if speaker == "FIEND" else "_B"
                if atom_type + speaker_suffix in GRAMMAR:
                    pool_key = atom_type + speaker_suffix
                elif atom_type in GRAMMAR:
                    pool_key = atom_type
                else:
                    continue

            pool = GRAMMAR.get(pool_key, [])
            if pool:
                line = random.choice(pool)
                beat_lines.append((speaker, line))

        if beat_lines:
            dialogue_sequences.append(beat_lines)

    return dialogue_sequences


def get_scenario_for_context(
    session_phase: str,
    power_dynamic: str,
    intensity: float,
    trust_profile: 'TrustProfile' = None
) -> str:
    """
    Select an appropriate scenario based on current game state.
    """
    import random

    # Filter scenarios by compatibility
    compatible = []

    for scenario_id, scenario in SCENARIOS.items():
        # Check intensity arc compatibility with phase
        if session_phase == "warmup":
            if scenario.intensity_arc in ["slow_build", "waves"]:
                compatible.append((scenario_id, 1.5))  # Weight for preference
        elif session_phase == "building":
            compatible.append((scenario_id, 1.0))
        elif session_phase == "peak":
            if scenario.intensity_arc in ["fast_burn", "edge_tease"]:
                compatible.append((scenario_id, 1.5))
            else:
                compatible.append((scenario_id, 0.8))
        else:
            compatible.append((scenario_id, 1.0))

        # Bonus weight if power dynamic matches current state
        if power_dynamic == "F_leads" and scenario.power_start == "F_dominant":
            compatible[-1] = (compatible[-1][0], compatible[-1][1] * 1.3)
        elif power_dynamic == "B_leads" and scenario.power_start == "B_dominant":
            compatible[-1] = (compatible[-1][0], compatible[-1][1] * 1.3)

    if not compatible:
        return "slow_tenderness"  # Default

    # Weighted random selection
    total_weight = sum(w for _, w in compatible)
    r = random.random() * total_weight
    cumulative = 0
    for scenario_id, weight in compatible:
        cumulative += weight
        if r <= cumulative:
            return scenario_id

    return compatible[0][0]


# ═══════════════════════════════════════════════════════════════════════════════
#                    🔥 LIVING DIALOGUE ENGINE 🔥
#              Lines mutate, combine, react to state, remember history
# ═══════════════════════════════════════════════════════════════════════════════

@dataclass
class EmotionalDNA:
    """Genetic code of a dialogue line - determines compatibility and mutation."""
    warmth: float = 0.0        # Cold ↔ Warm
    dominance: float = 0.0     # Submissive ↔ Dominant
    arousal: float = 0.0       # Calm ↔ Excited
    vulnerability: float = 0.0  # Guarded ↔ Open
    needs_response: bool = True
    can_stand_alone: bool = False
    interrupts_flow: bool = False
    escalates: bool = False
    deescalates: bool = False
    can_stutter: bool = False
    can_trail: bool = False
    can_intensify: bool = False
    can_soften: bool = False
    can_repeat: bool = False
    requires_intimacy: int = 0
    requires_intensity: float = 0.0

    # V3: Depth gating - lines only available after reaching certain depth
    min_depth: float = 0.0  # 0.0 = always available, 0.5 = needs depth >= 0.5

    def compatible_with(self, other: 'EmotionalDNA') -> float:
        score = 1.0
        if abs(self.warmth - other.warmth) > 0.8: score *= 0.3
        if abs(self.dominance - other.dominance) > 1.0: score *= 0.5
        if other.arousal < self.arousal - 0.3: score *= 0.7
        return score


@dataclass
class LivingLine:
    """A dialogue line that knows how to mutate and react."""
    speaker: str
    text: str
    dna: EmotionalDNA
    times_used: int = 0

    def mutate(self, intensity: float, desperation: float, state: str, depth: float = 0.0) -> str:
        """
        Mutate line based on state. V3: depth controls which mutations are active.

        depth 0.0-0.3: mutations OFF (clean lines)
        depth 0.3-0.5: can_trail, can_soften enabled
        depth 0.5-0.7: can_stutter, can_intensify enabled
        depth 0.7-1.0: can_repeat, ALL enabled, STACKING
        """
        result = self.text

        # V3: Depth-gated mutations
        trail_enabled = depth >= 0.3 or not self.dna.can_trail
        soften_enabled = depth >= 0.3 or not self.dna.can_soften
        stutter_enabled = depth >= 0.5
        intensify_enabled = depth >= 0.5
        repeat_enabled = depth >= 0.7

        # At high depth, mutations can STACK
        stacking = depth >= 0.7
        mutation_count = 0
        max_mutations = 1 if not stacking else 3

        # STUTTER: "Please" -> "P— Please"
        if self.dna.can_stutter and stutter_enabled and desperation > 0.5:
            if random.random() < desperation * (0.5 + depth * 0.5) and mutation_count < max_mutations:
                words = result.split()
                if words and len(words[0]) > 1:
                    result = f"{words[0][0]}— {result}"
                    mutation_count += 1

        # TRAIL: "I want" -> "I want..."
        if self.dna.can_trail and trail_enabled and self.dna.vulnerability > 0.4:
            if random.random() < 0.3 + depth * 0.2 and mutation_count < max_mutations:
                result = result.rstrip('.!?') + "..."
                mutation_count += 1

        # INTENSIFY: "harder" -> "HARDER—"
        if self.dna.can_intensify and intensify_enabled and intensity > 0.6:
            if random.random() < (intensity - 0.4) * (0.5 + depth * 0.5) and mutation_count < max_mutations:
                words = result.split()
                if words:
                    words[len(words)//2] = words[len(words)//2].upper()
                    result = ' '.join(words)
                    if not result.endswith('—'): result = result.rstrip('.!?') + "—"
                    mutation_count += 1

        # SOFTEN: "Come here" -> "...come here"
        if self.dna.can_soften and soften_enabled and self.dna.warmth > 0.5 and intensity < 0.5:
            if random.random() < 0.3 + depth * 0.2 and mutation_count < max_mutations:
                if not result.startswith('...'):
                    result = "..." + result
                    mutation_count += 1

        # REPEAT: "please" -> "please... please..."
        if self.dna.can_repeat and repeat_enabled and desperation > 0.7:
            if random.random() < 0.2 + depth * 0.3 and mutation_count < max_mutations:
                words = result.split()
                if words:
                    echo = words[-1].rstrip('.!?—')
                    result = f"{result.rstrip('.!?—')}... {echo}..."
                    mutation_count += 1

        # V3: At very high depth (0.9+), double mutations possible
        if depth >= 0.9 and mutation_count > 0 and random.random() < 0.3:
            # Add another echo or stutter
            if self.dna.can_repeat:
                words = result.split()
                if words:
                    echo = words[-1].rstrip('.!?—')
                    result = f"{result.rstrip('.!?—')}... {echo}..."

        self.times_used += 1
        return result


