def get_vignette_for_state(round_state: 'RoundState', trigger: str) -> Optional[BranchingVignette]:
    """Get an appropriate vignette based on current state and trigger."""
    for vignette in BRANCHING_VIGNETTES.values():
        if vignette.trigger == trigger:
            return vignette
    return None


def select_branch_dialogue(vignette: BranchingVignette, power_dynamic: float, depth: float = 0.5) -> List[Tuple[str, str]]:
    """Select and possibly mutate the appropriate branch dialogue."""
    dialogue, effects = vignette.get_branch(power_dynamic)

    # At high depth, mutations apply to vignette dialogue too
    if depth > 0.6:
        # Could add stutter/intensify here
        pass

    return dialogue


# ═══════════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════════
#
#                    🎬 MICRO-ANIMATION SYSTEM 🎬
#                    Breathing, transitions, reactions - poses that LIVE
#
# ═══════════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════════

from enum import Enum
from typing import Callable

class AnimationType(Enum):
    """Types of micro-animations."""
    BREATHING = "breathing"           # Idle chest/body rise/fall
    WEIGHT_SHIFT = "weight_shift"     # Idle sway left/right
    HEAD_TURN = "head_turn"           # Look direction change
    STARTLE = "startle"               # Quick up-shift, settle
    SLUMP = "slump"                   # Down-shift, compress
    FLINCH = "flinch"                 # Back + compress (recoil)
    IDEA_JUMP = "idea_jump"           # Anticipation -> up -> settle
    DISSOLVE = "dissolve"             # Cross-fade between poses
    SLIDE = "slide"                   # Physical movement transition
    TURN = "turn"                     # Orientation change


@dataclass
class AnimationFrame:
    """A single frame of animation with transform data."""
    frame_id: int
    duration_ms: int              # How long this frame displays
    y_offset: int = 0             # Vertical shift (negative = up)
    x_offset: int = 0             # Horizontal shift (negative = left)
    scale_y: float = 1.0          # Vertical scale (< 1 = compress)
    scale_x: float = 1.0          # Horizontal scale
    opacity: float = 1.0          # For dissolve transitions
    row_range: Tuple[int, int] = None  # Which rows to affect (None = all)


@dataclass
class Animation:
    """A complete animation sequence."""
    animation_id: str
    animation_type: AnimationType
    frames: List[AnimationFrame]
    loop: bool = False            # Whether to loop (for breathing, weight shift)
    interruptible: bool = True    # Can be interrupted by new animation


