#                    POSE-SPECIFIC BREATHING
#              Each pose has custom row ranges for realistic breathing
# ═══════════════════════════════════════════════════════════════════════════════

# Row ranges where breathing affects each pose (tuned per lightmap)
POSE_BREATHING_ZONES = {
    "laying_smile": (15, 50),      # Chest/torso area when laying
    "coy_cheek": (10, 45),         # Upper body, shoulder area
    "front_presence": (12, 48),    # Full torso visible
    "stand_backfacing": (10, 50),  # Back visible, shoulders move
    "strut": (8, 42),              # Walking pose, upper body
    "squat": (5, 35),              # Compressed, smaller range
    "downward": (10, 40),          # Bent over, torso area
    "angled_collapse": (15, 55),   # Sprawled, larger breathing area
    "angled_collapse_low_quality": (15, 55),  # Alias for full name
    "outhouse": (10, 45),          # Sitting, torso
    "face": (5, 25),               # Close-up, subtle movement
}

def create_pose_breathing(pose_name: str, breathing_type: str = "normal") -> Animation:
    """Create breathing animation tuned for a specific pose."""
    row_range = POSE_BREATHING_ZONES.get(pose_name, (10, 45))

    if breathing_type == "slow":
        return Animation(
            animation_id=f"breathing_slow_{pose_name}",
            animation_type=AnimationType.BREATHING,
            loop=True,
            frames=[
                AnimationFrame(0, duration_ms=1200, y_offset=0, row_range=row_range),
                AnimationFrame(1, duration_ms=800, y_offset=-1, row_range=row_range),
                AnimationFrame(2, duration_ms=2000, y_offset=-1, row_range=row_range),
                AnimationFrame(3, duration_ms=1000, y_offset=0, row_range=row_range),
                AnimationFrame(4, duration_ms=600, y_offset=0, row_range=row_range),
            ]
        )
    elif breathing_type == "fast":
        return Animation(
            animation_id=f"breathing_fast_{pose_name}",
            animation_type=AnimationType.BREATHING,
            loop=True,
            frames=[
                AnimationFrame(0, duration_ms=300, y_offset=0, row_range=row_range),
                AnimationFrame(1, duration_ms=1200, y_offset=-1, row_range=row_range),
                AnimationFrame(2, duration_ms=300, y_offset=0, row_range=row_range),
                AnimationFrame(3, duration_ms=1200, y_offset=-1, row_range=row_range),
            ]
        )
    elif breathing_type == "exhausted":
        return Animation(
            animation_id=f"breathing_exhausted_{pose_name}",
            animation_type=AnimationType.BREATHING,
            loop=True,
            frames=[
                AnimationFrame(0, duration_ms=300, y_offset=0, row_range=row_range),
                AnimationFrame(1, duration_ms=1200, y_offset=-2, row_range=row_range),
                AnimationFrame(2, duration_ms=800, y_offset=-2, row_range=row_range),
                AnimationFrame(3, duration_ms=300, y_offset=0, row_range=row_range),
                AnimationFrame(4, duration_ms=1000, y_offset=0, row_range=row_range),
            ]
        )
    else:  # normal
        return Animation(
            animation_id=f"breathing_normal_{pose_name}",
            animation_type=AnimationType.BREATHING,
            loop=True,
            frames=[
                AnimationFrame(0, duration_ms=800, y_offset=0, row_range=row_range),
                AnimationFrame(1, duration_ms=80, y_offset=-1, row_range=row_range),
                AnimationFrame(2, duration_ms=600, y_offset=0, row_range=row_range),
            ]
        )


# Pre-generate breathing variants for key poses
POSE_BREATHING_VARIANTS = {}
for pose in ["laying_smile", "coy_cheek", "front_presence", "angled_collapse", "strut"]:
    POSE_BREATHING_VARIANTS[pose] = {
        "slow": create_pose_breathing(pose, "slow"),
        "normal": create_pose_breathing(pose, "normal"),
        "fast": create_pose_breathing(pose, "fast"),
        "exhausted": create_pose_breathing(pose, "exhausted"),
    }


