# ═══════════════════════════════════════════════════════════════════════════════
#                    TURNAROUND SEQUENCES
#              Full orientation changes between poses
# ═══════════════════════════════════════════════════════════════════════════════

@dataclass
class TurnaroundSequence:
    """A sequence for turning from one orientation to another."""
    sequence_id: str
    from_orientation: str  # PoseOrientation value as string
    to_orientation: str    # PoseOrientation value as string
    intermediate_steps: List[Tuple[str, int]]  # (transform_type, duration_ms)
    total_duration_ms: int


# Turnaround sequences - these describe the motion, not the pose changes
# Note: Uses string values that correspond to PoseOrientation enum values
TURNAROUND_SEQUENCES = {
    "front_to_back": TurnaroundSequence(
        sequence_id="front_to_back",
        from_orientation="front",
        to_orientation="back",
        intermediate_steps=[
            ("rotate_start", 100),      # Begin turn
            ("quarter_turn", 150),      # 90 degrees
            ("half_turn", 150),         # 180 degrees
            ("settle", 100),            # Settle into new pose
        ],
        total_duration_ms=80,
    ),
    "back_to_front": TurnaroundSequence(
        sequence_id="back_to_front",
        from_orientation="back",
        to_orientation="front",
        intermediate_steps=[
            ("rotate_start", 100),
            ("quarter_turn", 150),
            ("half_turn", 150),
            ("settle", 100),
        ],
        total_duration_ms=80,
    ),
    "front_to_side": TurnaroundSequence(
        sequence_id="front_to_side",
        from_orientation="front",
        to_orientation="3q_left",
        intermediate_steps=[
            ("rotate_start", 80),
            ("quarter_turn", 120),
            ("settle", 80),
        ],
        total_duration_ms=280,
    ),
    "quick_glance_back": TurnaroundSequence(
        sequence_id="quick_glance_back",
        from_orientation="front",
        to_orientation="3q_right",
        intermediate_steps=[
            ("snap_rotate", 60),
            ("hold", 200),
            ("settle", 80),
        ],
        total_duration_ms=340,
    ),
}


def create_turnaround_animation(sequence: TurnaroundSequence) -> Animation:
    """Create an animation for a turnaround sequence."""
    frames = []
    frame_idx = 0

    for step_type, duration in sequence.intermediate_steps:
        if step_type == "rotate_start":
            # Slight anticipation
            frames.append(AnimationFrame(frame_idx, duration_ms=duration, x_offset=-1, scale_x=0.98))
        elif step_type == "quarter_turn":
            # Compress horizontally (turning away)
            frames.append(AnimationFrame(frame_idx, duration_ms=duration, x_offset=-2, scale_x=0.85))
        elif step_type == "half_turn":
            # Maximum compression (profile)
            frames.append(AnimationFrame(frame_idx, duration_ms=duration, x_offset=0, scale_x=0.7))
        elif step_type == "snap_rotate":
            # Quick snap turn
            frames.append(AnimationFrame(frame_idx, duration_ms=duration, x_offset=2, scale_x=0.9))
        elif step_type == "hold":
            # Hold position
            frames.append(AnimationFrame(frame_idx, duration_ms=duration, x_offset=2, scale_x=0.95))
        elif step_type == "settle":
            # Return to normal
            frames.append(AnimationFrame(frame_idx, duration_ms=duration, x_offset=0, scale_x=1.0))

        frame_idx += 1

    return Animation(
        animation_id=f"turnaround_{sequence.sequence_id}",
        animation_type=AnimationType.TURN,
        frames=frames,
        loop=False,
        interruptible=False,
    )


# Pre-generate turnaround animations
TURNAROUND_ANIMATIONS = {
    seq_id: create_turnaround_animation(seq)
    for seq_id, seq in TURNAROUND_SEQUENCES.items()
}


