        AnimationFrame(3, duration_ms=800, y_offset=-2, scale_y=1.1, scale_x=1.12),  # Peak shock
        # Return (slightly bigger than before = lasting surprise)
        AnimationFrame(4, duration_ms=1000, y_offset=-1, scale_y=1.05, scale_x=1.05),
        AnimationFrame(5, duration_ms=300, y_offset=0, scale_y=1.02, scale_x=1.02),
