class DialogueScenePlayer:
    """Plays pose-animated dialogue scenes."""

    def __init__(self, animation_engine: MicroAnimationEngine, lightmaps: Dict = None):
        self.animation_engine = animation_engine
        self.current_scene: Optional[DialogueScene] = None
        self.current_beat_idx: int = 0
        self.beat_start_time: float = 0.0
        self.current_pose: str = ""
        self.pose_lines: List[str] = []
        self.waiting_for_input: bool = False

        # Use provided lightmaps or empty dict
        self.lightmaps = lightmaps or {}

        # Pose cache
        self.pose_cache: Dict[str, List[str]] = {}

    def set_lightmaps(self, lightmaps: Dict):
        """Set lightmaps reference after initialization."""
        self.lightmaps = lightmaps

    def load_pose(self, pose_name: str) -> List[str]:
        """Load a pose from lightmaps or file cache."""
        # Handle aliases
        actual_pose = POSE_ALIASES.get(pose_name, pose_name)

        if actual_pose in self.pose_cache:
            return self.pose_cache[actual_pose]

        # Try to get from lightmaps first
        if self.lightmaps and actual_pose in self.lightmaps:
            lm = self.lightmaps[actual_pose]
            # Lightmap has figure attribute
            if hasattr(lm, 'figure'):
                self.pose_cache[actual_pose] = lm.figure
                return lm.figure

        # Try alternate naming (lightmap_shades_X.txt)
        try:
            script_dir = os.path.dirname(os.path.abspath(__file__))
            filepath = os.path.join(script_dir, f"lightmap_shades_{actual_pose}.txt")
            with open(filepath, 'r', encoding='utf-8') as f:
                lines = f.read().split('\n')
            lines = preprocess_lightmap_lines(lines, do_smooth=True)
            self.pose_cache[actual_pose] = lines
            return lines
        except:
            pass

        # Try figure file naming (X_figure.txt)
        try:
            script_dir = os.path.dirname(os.path.abspath(__file__))
            filepath = os.path.join(script_dir, f"{actual_pose}_figure.txt")
            with open(filepath, 'r', encoding='utf-8') as f:
                lines = f.read().split('\n')
            lines = preprocess_lightmap_lines(lines, do_smooth=True)
            self.pose_cache[actual_pose] = lines
            return lines
        except:
            pass

        # Return empty if nothing found
        return []

    def start_scene(self, scene: DialogueScene):
        """Start playing a dialogue scene."""
        self.current_scene = scene
        self.current_beat_idx = 0
        self.beat_start_time = time.time()

        # Set initial state
        self.current_pose = scene.initial_pose
        self.pose_lines = self.load_pose(scene.initial_pose)
        self.animation_engine.set_idle_animation(scene.initial_breathing)

    def update(self) -> Optional[DialogueSceneBeat]:
        """Update scene state, return current beat if changed."""
        if not self.current_scene:
            return None

        if self.current_beat_idx >= len(self.current_scene.beats):
            return None  # Scene complete

        beat = self.current_scene.beats[self.current_beat_idx]
        now = time.time()

        # Handle pause beats
        if beat.speaker == "PAUSE":
            if (now - self.beat_start_time) * 1000 >= beat.duration_ms:
                self.advance_beat()
            return beat

        return beat

    def advance_beat(self):
        """Advance to next beat."""
        self.current_beat_idx += 1
        self.beat_start_time = time.time()

        if self.current_beat_idx < len(self.current_scene.beats):
            beat = self.current_scene.beats[self.current_beat_idx]

            # Handle pose change
            if beat.pose and beat.pose != self.current_pose:
                new_lines = self.load_pose(beat.pose)
                if beat.transition:
                    self.animation_engine.start_transition(
                        self.pose_lines, new_lines, beat.transition
                    )
                self.current_pose = beat.pose
                self.pose_lines = new_lines

            # Handle animation trigger
            if beat.animation:
                self.animation_engine.trigger_reaction(beat.animation)

            # Handle breathing change
            if beat.breathing:
                self.animation_engine.set_idle_animation(beat.breathing)

    def render(self) -> Tuple[List[str], Optional[DialogueSceneBeat]]:
        """Render current frame and return (lines, current_beat)."""
        beat = self.update()

        # Get animated pose
        if self.animation_engine.transitioning:
            lines = self.animation_engine.render_transition_frame()
        else:
            lines = self.animation_engine.render_animated_pose(self.pose_lines)

        return lines, beat

    def is_complete(self) -> bool:
        """Check if scene is complete."""
        return self.current_beat_idx >= len(self.current_scene.beats) if self.current_scene else True


