#
#                    🔥 SEMANTIC MODIFIER SYSTEM 🔥
#
#              Interjections aren't decoration - they're MEANING CHANGERS.
#              Prefix + Core + Suffix = Unique emotional state
#              Each combination seeds different dialogue branches.
#
# ═══════════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════════

# Mood types that modifiers can express
class ModifierMood(Enum):
    LOVING = "loving"           # Affectionate tsundere
    SHEEPISH = "sheepish"       # Uncertain, confused
    OVERWHELMED = "overwhelmed" # Can't process, breaking
    DEFIANT = "defiant"         # Bratty resistance
    DESPERATE = "desperate"     # Urgent need
    COMMANDING = "commanding"   # Taking control
    VULNERABLE = "vulnerable"   # Walls down
    SATISFIED = "satisfied"     # Content, achieved
    TRAILING = "trailing"       # Unfinished, hanging
    NEUTRAL = "neutral"         # Clean, no modifier


# Prefix pools - set the INCOMING mood
SEMANTIC_PREFIXES = {
    ModifierMood.LOVING: ["baka...", "nn...", "...hey,", "fiend...", "mm..."],
    ModifierMood.SHEEPISH: ["...", "um...", "uh...", "well...", "I mean..."],
    ModifierMood.OVERWHELMED: ["hahhh—", "ghhh—", "nngh—", "I—", "can't—"],
    ModifierMood.DEFIANT: ["tch.", "hmph.", "whatever,", "fine,", "ugh,"],
    ModifierMood.DESPERATE: ["please—", "I can't—", "wait—", "no—", "don't—"],
    ModifierMood.COMMANDING: ["hey.", "listen.", "look,", "you.", "now."],
    ModifierMood.VULNERABLE: ["...I...", "maybe...", "if you...", "...please,"],
    ModifierMood.TRAILING: ["so...", "and...", "but...", "then..."],
}

# Suffix pools - set the OUTGOING mood
SEMANTIC_SUFFIXES = {
    ModifierMood.LOVING: ["~", "bakaaaa~", "...baka.", "...stupid.", "...dummy."],
    ModifierMood.SHEEPISH: ["ehhhh~", "...I guess.", "...maybe.", "...or something.", "...idk."],
    ModifierMood.TRAILING: ["...", "—", "...anyway.", "...yeah.", "...so."],
    ModifierMood.DEFIANT: ["...hmph.", "...whatever.", "...jerk.", "...meanie.", "...tch."],
    ModifierMood.VULNERABLE: ["...please.", "...okay?", "...right?", "...stay.", "...don't go."],
    ModifierMood.SATISFIED: ["...good.", "...there.", "...finally.", "~♪", "...mm."],
    ModifierMood.OVERWHELMED: ["—!", "...hahhh.", "...ghhh.", "...nngh.", "—!!"],
    ModifierMood.DESPERATE: ["...please!", "—please—", "...I need—", "...more—"],
}


@dataclass
class ModifierResult:
    """Result of applying semantic modifiers to a line."""
    original: str
    modified: str
    prefix_mood: Optional[ModifierMood]
    suffix_mood: Optional[ModifierMood]
    prefix_used: Optional[str]
    suffix_used: Optional[str]

    # The combination determines what comes next
    entry_mood: str   # How we entered this line
    exit_mood: str    # How we leave this line (seeds next)

    # Branching potential
    branch_weight: float  # Higher = more variation potential

    def get_combined_mood(self) -> str:
        """Get the combined mood signature for branching."""
        p = self.prefix_mood.value if self.prefix_mood else "none"
        s = self.suffix_mood.value if self.suffix_mood else "none"
        return f"{p}_{s}"


@dataclass
class PropagatingState:
    """
    State that propagates through the dialogue sequence.
    Each line's modifiers affect the next line's possibilities.
    """
    current_mood: ModifierMood = ModifierMood.NEUTRAL
    momentum: float = 0.0          # -1 (retreating) to +1 (advancing)
    vulnerability_level: float = 0.0  # 0 (guarded) to 1 (open)
    power_dynamic: float = 0.0     # -1 (B dominant) to +1 (F dominant)

    # Modifier history affects future rolls
    recent_prefixes: List[ModifierMood] = field(default_factory=list)
    recent_suffixes: List[ModifierMood] = field(default_factory=list)

    # Branching seeds
    branch_seed: int = 0
    variation_potential: float = 0.5

    def update_from_modifier(self, result: ModifierResult):
        """Update state based on modifier result."""
        # Track history
        if result.prefix_mood:
            self.recent_prefixes.append(result.prefix_mood)
            if len(self.recent_prefixes) > 5:
                self.recent_prefixes.pop(0)

        if result.suffix_mood:
            self.recent_suffixes.append(result.suffix_mood)
            if len(self.recent_suffixes) > 5:
                self.recent_suffixes.pop(0)

        # Update current mood based on exit
        if result.suffix_mood:
            self.current_mood = result.suffix_mood

        # Update dynamics based on moods
        if result.prefix_mood == ModifierMood.DESPERATE or result.suffix_mood == ModifierMood.DESPERATE:
            self.momentum += 0.2
            self.vulnerability_level += 0.1

        if result.prefix_mood == ModifierMood.DEFIANT or result.suffix_mood == ModifierMood.DEFIANT:
            self.momentum -= 0.1
            self.power_dynamic -= 0.15  # B gains power

        if result.prefix_mood == ModifierMood.LOVING or result.suffix_mood == ModifierMood.LOVING:
            self.vulnerability_level += 0.15

        if result.prefix_mood == ModifierMood.COMMANDING:
            self.power_dynamic += 0.2  # F gains power

        # Update variation potential
        self.variation_potential = result.branch_weight

        # Clamp values
        self.momentum = max(-1.0, min(1.0, self.momentum))
        self.vulnerability_level = max(0.0, min(1.0, self.vulnerability_level))
        self.power_dynamic = max(-1.0, min(1.0, self.power_dynamic))

    def get_prefix_probability(self, speaker: str, depth: float = 0.0) -> float:
        """
        Get probability of rolling a prefix based on state.
        V3: DEPTH is the primary driver of modifier probability.
        """
        # V3: Depth-driven base probability
        if depth < 0.2:
            base = 0.20
        elif depth < 0.4:
            base = 0.30
        elif depth < 0.6:
            base = 0.45
        elif depth < 0.8:
            base = 0.55
        else:
            base = 0.70

        base += self.vulnerability_level * 0.1
        if len(self.recent_prefixes) >= 3:
            base -= 0.1
        if abs(self.momentum) > 0.5:
            base += 0.05

        return max(0.1, min(0.85, base))

    def get_suffix_probability(self, speaker: str, depth: float = 0.0) -> float:
        """
        Get probability of rolling a suffix based on state.
        V3: DEPTH is the primary driver of modifier probability.
        """
        if depth < 0.2:
            base = 0.25
        elif depth < 0.4:
            base = 0.35
        elif depth < 0.6:
            base = 0.50
        elif depth < 0.8:
            base = 0.60
        else:
            base = 0.75

        base += self.vulnerability_level * 0.1
        if len(self.recent_suffixes) >= 3:
            base -= 0.08
        if speaker == "BIRDSONG" and self.power_dynamic > 0.3:
            base += 0.05
        elif speaker == "FIEND" and self.power_dynamic < -0.3:
            base += 0.05

        return max(0.15, min(0.90, base))

    def get_mood_weights(self, speaker: str, depth: float = 0.0) -> Dict[ModifierMood, float]:
        """
        Get weighted probabilities for each mood based on state.
        V3: Depth gates which moods can appear.
        """
        weights = {}

        # V3: Depth-gated mood availability
        weights[ModifierMood.SHEEPISH] = 1.0
        weights[ModifierMood.TRAILING] = 1.0

        if depth >= 0.2:
            weights[ModifierMood.DEFIANT] = 1.0
            weights[ModifierMood.LOVING] = 1.0

        if depth >= 0.4:
            weights[ModifierMood.VULNERABLE] = 1.0
            weights[ModifierMood.COMMANDING] = 1.0
            weights[ModifierMood.SATISFIED] = 1.0

        if depth >= 0.6:
            weights[ModifierMood.DESPERATE] = 1.0
            weights[ModifierMood.OVERWHELMED] = 1.0

        # Adjust based on current mood (continuity)
        if self.current_mood in weights:
            weights[self.current_mood] *= 1.5

        # Adjust based on vulnerability
        if self.vulnerability_level > 0.6:
            if ModifierMood.VULNERABLE in weights:
                weights[ModifierMood.VULNERABLE] *= 2.0
            if ModifierMood.LOVING in weights:
                weights[ModifierMood.LOVING] *= 1.5
            if ModifierMood.DESPERATE in weights:
                weights[ModifierMood.DESPERATE] *= 1.5

        # Adjust based on momentum
        if self.momentum > 0.5:
            if ModifierMood.DESPERATE in weights:
                weights[ModifierMood.DESPERATE] *= 1.8
            if ModifierMood.OVERWHELMED in weights:
                weights[ModifierMood.OVERWHELMED] *= 1.5
        elif self.momentum < -0.3:
            if ModifierMood.DEFIANT in weights:
                weights[ModifierMood.DEFIANT] *= 1.5
            weights[ModifierMood.SHEEPISH] *= 1.3

        # Adjust based on power dynamic
        if speaker == "BIRDSONG":
            if self.power_dynamic > 0.3:
                weights[ModifierMood.SHEEPISH] *= 1.3
                if ModifierMood.OVERWHELMED in weights:
                    weights[ModifierMood.OVERWHELMED] *= 1.4
            else:
                if ModifierMood.DEFIANT in weights:
                    weights[ModifierMood.DEFIANT] *= 1.4
                if ModifierMood.COMMANDING in weights:
                    weights[ModifierMood.COMMANDING] *= 1.3
        else:
            if self.power_dynamic > 0.3:
                if ModifierMood.COMMANDING in weights:
                    weights[ModifierMood.COMMANDING] *= 1.4
                if ModifierMood.SATISFIED in weights:
                    weights[ModifierMood.SATISFIED] *= 1.3
            else:
                if ModifierMood.VULNERABLE in weights:
                    weights[ModifierMood.VULNERABLE] *= 1.3
                if ModifierMood.LOVING in weights:
                    weights[ModifierMood.LOVING] *= 1.4

        # Avoid repetition
        for recent in self.recent_prefixes[-2:]:
            if recent in weights:
                weights[recent] *= 0.5
        for recent in self.recent_suffixes[-2:]:
            if recent in weights:
                weights[recent] *= 0.5

        return weights


class SemanticModifierEngine:
    """
    Applies semantic modifiers to dialogue lines.
    Creates meaning through prefix+suffix combinations.
    V3: Depth controls modifier probability and mood availability.
    """

    def __init__(self):
        self.state = PropagatingState()
        self.depth = 0.0  # V3: Track depth

    def reset(self, seed: int = None):
        """Reset state for new sequence."""
        self.state = PropagatingState()
        self.depth = 0.0
        if seed is not None:
            self.state.branch_seed = seed
            random.seed(seed)

    def set_depth(self, depth: float):
        """V3: Set current depth for modifier probability scaling."""
        self.depth = max(0.0, min(1.0, depth))

    def apply_modifiers(self, speaker: str, core_text: str,
                       intensity: float = 0.5,
                       force_prefix: ModifierMood = None,
                       force_suffix: ModifierMood = None,
                       depth: float = None) -> ModifierResult:
        """
        Apply semantic modifiers to a core line.
        V3: Depth drives probability and mood gating.

        ROLL for prefix (independent)
        ROLL for suffix (independent)
        Combination determines meaning and branches.
        """
        # V3: Use provided depth or stored depth
        current_depth = depth if depth is not None else self.depth

        prefix_used = None
        suffix_used = None
        prefix_mood = None
        suffix_mood = None

        # Get mood weights based on state AND depth
        mood_weights = self.state.get_mood_weights(speaker, current_depth)

        # ROLL FOR PREFIX (probability scales with depth)
        prefix_prob = self.state.get_prefix_probability(speaker, current_depth)
        prefix_roll = random.random()

        if force_prefix:
            prefix_mood = force_prefix
            pool = SEMANTIC_PREFIXES.get(prefix_mood, [])
            if pool:
                prefix_used = random.choice(pool)
        elif prefix_roll < prefix_prob:
            # Weighted mood selection
            prefix_mood = self._weighted_mood_select(mood_weights, SEMANTIC_PREFIXES)
            if prefix_mood:
                pool = SEMANTIC_PREFIXES[prefix_mood]
                prefix_used = random.choice(pool)

        # ROLL FOR SUFFIX (INDEPENDENT, also depth-driven)
        suffix_prob = self.state.get_suffix_probability(speaker, current_depth)
        suffix_roll = random.random()

        if force_suffix:
            suffix_mood = force_suffix
            pool = SEMANTIC_SUFFIXES.get(suffix_mood, [])
            if pool:
                suffix_used = random.choice(pool)
        elif suffix_roll < suffix_prob:
            # Weighted mood selection (can be different from prefix!)
            suffix_mood = self._weighted_mood_select(mood_weights, SEMANTIC_SUFFIXES)
            if suffix_mood:
                pool = SEMANTIC_SUFFIXES[suffix_mood]
                suffix_used = random.choice(pool)

        # BUILD MODIFIED LINE
        parts = []
        if prefix_used:
            parts.append(prefix_used)

        # Adjust core based on prefix
        adjusted_core = core_text
        if prefix_used and prefix_used.endswith('—'):
            # Interrupting prefix - might lowercase the start
            if adjusted_core and adjusted_core[0].isupper():
                adjusted_core = adjusted_core[0].lower() + adjusted_core[1:]

        parts.append(adjusted_core.rstrip('.!?') if suffix_used else adjusted_core)

        if suffix_used:
            # Don't double punctuation
            if parts[-1].endswith(('—', '~', '.')):
                parts.append(suffix_used.lstrip('.'))
            else:
                parts.append(suffix_used)

        modified = ' '.join(parts)

        # Clean up spacing
        modified = modified.replace('  ', ' ').replace(' ~', '~').replace(' ...', '...')
        modified = modified.replace('— ', '— ').replace(' —', '—')

        # Calculate branch weight
        branch_weight = 0.3  # Base
        if prefix_mood: branch_weight += 0.25
        if suffix_mood: branch_weight += 0.25
        if prefix_mood and suffix_mood and prefix_mood != suffix_mood:
            branch_weight += 0.2  # Mixed moods = more variation

        # Determine entry/exit moods
        entry_mood = prefix_mood.value if prefix_mood else "neutral"
        exit_mood = suffix_mood.value if suffix_mood else (prefix_mood.value if prefix_mood else "neutral")

        result = ModifierResult(
            original=core_text,
            modified=modified,
            prefix_mood=prefix_mood,
            suffix_mood=suffix_mood,
            prefix_used=prefix_used,
            suffix_used=suffix_used,
            entry_mood=entry_mood,
            exit_mood=exit_mood,
            branch_weight=branch_weight
        )

        # Update propagating state
        self.state.update_from_modifier(result)

        return result

    def _weighted_mood_select(self, weights: Dict[ModifierMood, float],
                              pool_dict: Dict) -> Optional[ModifierMood]:
        """Select a mood based on weights, only from moods that have pools."""
        available = [(m, w) for m, w in weights.items() if m in pool_dict]
        if not available:
            return None

        total = sum(w for _, w in available)
        r = random.random() * total
        cumulative = 0

        for mood, weight in available:
            cumulative += weight
            if r <= cumulative:
                return mood

        return available[0][0]


class PropagatingDialogueEngine:
    """
    Dialogue engine that propagates state through the sequence.
    Each line's modifiers seed the next line's possibilities.
    The sequence is NOT predetermined - it GROWS from the seed.
    """

    def __init__(self):
        self.living_engine = LivingDialogueEngine()
        self.modifier_engine = SemanticModifierEngine()

    def generate_propagating_sequence(self,
                                      scenario_id: str,
                                      seed: int = None,
                                      intensity: float = 0.5,
                                      intimacy: int = 20,
                                      max_lines: int = 20) -> List[Tuple[str, str, ModifierResult]]:
        """
        Generate a dialogue sequence that propagates logically.

        NOT predetermined - seeded and left to grow.
        More modifiers = more variation potential = more branches explored.
        """
        if seed is None:
            seed = random.randint(0, 999999)

        self.modifier_engine.reset(seed)
        self.living_engine.set_state(intensity, intensity * 0.6, intimacy, "building")

        scenario = SCENARIOS.get(scenario_id)
        if not scenario:
            return []

        sequence = []
        speakers = ["FIEND", "BIRDSONG"]

        # Determine starting speaker from scenario
        if scenario.power_start == "F_dominant":
            speakers = ["FIEND", "BIRDSONG"]
        elif scenario.power_start == "B_dominant":
            speakers = ["BIRDSONG", "FIEND"]
        else:
            random.shuffle(speakers)

        last_dna = None
        current_beat_idx = 0
        lines_in_beat = 0

        for i in range(max_lines):
            # Determine speaker (alternating with some variation)
            speaker = speakers[i % 2]

            # Allow power dynamic to shift speaker order
            if abs(self.modifier_engine.state.power_dynamic) > 0.5:
                if self.modifier_engine.state.power_dynamic > 0 and speaker == "BIRDSONG":
                    # F is dominant, might interrupt
                    if random.random() < 0.2:
                        speaker = "FIEND"
                elif self.modifier_engine.state.power_dynamic < 0 and speaker == "FIEND":
                    # B is dominant, might interrupt
                    if random.random() < 0.2:
                        speaker = "BIRDSONG"

            # Generate core line from living engine
            result = self.living_engine.generate_line(speaker, last_dna)
            if not result:
                continue

            core_text, line_id = result
            line = self.living_engine.lexicon[line_id]
            last_dna = line.dna

            # Calculate intensity based on progression and state
            current_intensity = min(1.0, intensity + (i / max_lines) * 0.3 +
                                   self.modifier_engine.state.momentum * 0.2)

            # Apply semantic modifiers
            mod_result = self.modifier_engine.apply_modifiers(
                speaker, core_text, current_intensity
            )

            sequence.append((speaker, mod_result.modified, mod_result))

            # Check if high variation potential opens new branches
            if mod_result.branch_weight > 0.6:
                # More variation = might add extra exchange
                if random.random() < mod_result.branch_weight - 0.5:
                    # Generate a reactive line from the other speaker
                    other_speaker = "BIRDSONG" if speaker == "FIEND" else "FIEND"
                    react_result = self.living_engine.generate_line(other_speaker, last_dna)
                    if react_result:
                        react_text, react_id = react_result
                        react_line = self.living_engine.lexicon[react_id]
                        last_dna = react_line.dna

                        # Apply modifiers to reaction
                        react_mod = self.modifier_engine.apply_modifiers(
                            other_speaker, react_text, current_intensity
                        )
                        sequence.append((other_speaker, react_mod.modified, react_mod))

            # Update living engine state based on modifier state
            self.living_engine.intensity = current_intensity
            self.living_engine.desperation = self.modifier_engine.state.vulnerability_level

            lines_in_beat += 1

            # Move to next beat periodically
            if lines_in_beat >= random.randint(2, 4):
                current_beat_idx += 1
                lines_in_beat = 0

                if current_beat_idx >= len(scenario.beats):
                    current_beat_idx = len(scenario.beats) - 1

        return sequence

    def generate_branching_dialogue(self,
                                   scenario_id: str,
                                   seed: int = None,
                                   intensity: float = 0.5,
                                   intimacy: int = 20) -> Dict:
        """
        Generate dialogue with full branching metadata.
        Returns structure showing how modifiers created the path.
        """
        sequence = self.generate_propagating_sequence(
            scenario_id, seed, intensity, intimacy
        )

        # Build branching tree
        tree = {
            "seed": seed,
            "scenario": scenario_id,
            "lines": [],
            "branch_points": [],
            "mood_trajectory": [],
            "power_trajectory": [],
        }

        for speaker, text, mod_result in sequence:
            line_data = {
                "speaker": speaker,
                "text": text,
                "original": mod_result.original,
                "prefix": mod_result.prefix_used,
                "suffix": mod_result.suffix_used,
                "entry_mood": mod_result.entry_mood,
                "exit_mood": mod_result.exit_mood,
                "branch_weight": mod_result.branch_weight,
            }
            tree["lines"].append(line_data)

            # Track mood trajectory
            tree["mood_trajectory"].append(mod_result.exit_mood)

            # Mark branch points
            if mod_result.branch_weight > 0.6:
                tree["branch_points"].append({
                    "index": len(tree["lines"]) - 1,
                    "weight": mod_result.branch_weight,
                    "combined_mood": mod_result.get_combined_mood(),
                })

        return tree


# Singleton propagating engine
_propagating_engine: Optional[PropagatingDialogueEngine] = None

def get_propagating_engine() -> PropagatingDialogueEngine:
    global _propagating_engine
    if _propagating_engine is None:
        _propagating_engine = PropagatingDialogueEngine()
    return _propagating_engine


def generate_semantic_dialogue(scenario_id: str,
                              seed: int = None,
                              intensity: float = 0.5,
                              intimacy: int = 20,
                              max_lines: int = 15) -> List[Tuple[str, str]]:
    """
    High-level function to generate semantically-modified dialogue.
    Returns list of (speaker, modified_text).
    """
    engine = get_propagating_engine()
    sequence = engine.generate_propagating_sequence(
        scenario_id, seed, intensity, intimacy, max_lines
    )
    return [(speaker, text) for speaker, text, _ in sequence]


# Singleton engine
_living_engine: Optional[LivingDialogueEngine] = None

def get_living_engine() -> LivingDialogueEngine:
    global _living_engine
    if _living_engine is None:
        _living_engine = LivingDialogueEngine()
    return _living_engine


def generate_living_dialogue(scenario_id: str, intensity: float = 0.5,
                            desperation: float = 0.3, intimacy: int = 20,
                            phase: str = "building") -> List[List[Tuple[str, str]]]:
    """High-level function to generate living dialogue."""
    engine = get_living_engine()
    engine.set_state(intensity, desperation, intimacy, phase)
    return engine.generate_living_sequence(scenario_id)


@dataclass
class TrustProfile:
    """Permanent trust stats - persists across all sessions. Never decreases."""
    # Core trust dimensions (0-100)
    trust_vulnerability: int = 0    # bathroom/natural scenes accepted
    trust_control: int = 0          # love_bunny/facesitting accepted
    trust_intensity: int = 0        # rough/edge/denial accepted
    trust_intimacy: int = 0         # pillow talk, emotional moments accepted

    # Personality profile (emerges from choices)
    style_verbal: int = 0           # "Good girl" type choices
    style_physical: int = 0         # Touch/pull type choices
    style_silent: int = 0           # *stare* type choices
    tempo_patient: int = 0          # Slow/gentle choices
    tempo_eager: int = 0            # Faster/harder choices
    tempo_aggressive: int = 0       # Edge/push choices

    # Kink affinities (0-100, tracks interest)
    kink_bathroom: int = 0
    kink_control: int = 0
    kink_edge: int = 0
    kink_praise: int = 0
    kink_denial: int = 0

    kink_affinity: Dict[str, int] = field(default_factory=dict)  # tracks arbitrary kink keys
    # Content unlocks (permanent once earned)
    unlocked_pull_move: bool = False        # trust_intensity >= 40
    unlocked_edge_play: bool = False        # trust_intensity >= 30
    unlocked_love_bunny: bool = False       # trust_control >= 35
    unlocked_starving_bunny: bool = False   # trust_intimacy >= 40
    unlocked_hump_dog: bool = False         # trust_vulnerability >= 50
    unlocked_facesitting: bool = False      # trust_control >= 60
    unlocked_watersports: bool = False      # trust_vulnerability >= 75
    unlocked_edge_mastery: bool = False     # edge_play used 5+ times
    unlocked_sync_mode: bool = False        # both pleasures aligned 3+ times

    # Progression tracking
    total_choices_made: int = 0
    edge_play_count: int = 0
    sync_count: int = 0
    transcendence_count: int = 0

    def add_trust(self, dimension: str, amount: int):
        """Add trust to a dimension (never decreases)."""
        attr = f"trust_{dimension}"
        if hasattr(self, attr):
            current = getattr(self, attr)
            setattr(self, attr, min(100, current + amount))
            self._check_unlocks()

    def add_style(self, style: str, amount: int = 1):
        """Track style choice."""
        attr = f"style_{style}"
        if hasattr(self, attr):
            setattr(self, attr, getattr(self, attr) + amount)

    def add_tempo(self, tempo: str, amount: int = 1):
        """Track tempo preference."""
        attr = f"tempo_{tempo}"
        if hasattr(self, attr):
            setattr(self, attr, getattr(self, attr) + amount)

    def add_kink(self, kink: str, amount: int):
        """Track kink affinity.

        Supports both fixed kink_* fields and arbitrary keys via kink_affinity dict.
        """
        # Generic storage for any kink key
        if not hasattr(self, "kink_affinity") or self.kink_affinity is None:
            self.kink_affinity = {}
        try:
            current_generic = int(self.kink_affinity.get(kink, 0))
        except Exception:
            current_generic = 0
        self.kink_affinity[kink] = min(100, current_generic + int(amount))

        # Back-compat for defined kink_* fields
        attr = f"kink_{kink}"
        if hasattr(self, attr):
            current = getattr(self, attr)
            setattr(self, attr, min(100, current + amount))

    def record_kink(self, kink: str, amount: int):
        """Alias for add_kink (used by some scene triggers)."""
        self.add_kink(kink, amount)

    def _check_unlocks(self) -> List[str]:
        """Check and apply unlocks based on trust levels. Returns newly unlocked."""
        newly_unlocked = []

        if self.trust_intensity >= 30 and not self.unlocked_edge_play:
            self.unlocked_edge_play = True
            newly_unlocked.append("edge_play")

        if self.trust_control >= 35 and not self.unlocked_love_bunny:
            self.unlocked_love_bunny = True
            newly_unlocked.append("love_bunny")

        if self.trust_intensity >= 40 and not self.unlocked_pull_move:
            self.unlocked_pull_move = True
            newly_unlocked.append("pull_move")

        if self.trust_intimacy >= 40 and not self.unlocked_starving_bunny:
            self.unlocked_starving_bunny = True
            newly_unlocked.append("starving_bunny")

        if self.trust_vulnerability >= 50 and not self.unlocked_hump_dog:
            self.unlocked_hump_dog = True
            newly_unlocked.append("hump_dog")

        if self.trust_control >= 60 and not self.unlocked_facesitting:
            self.unlocked_facesitting = True
            newly_unlocked.append("facesitting")

        if self.trust_vulnerability >= 75 and not self.unlocked_watersports:
            self.unlocked_watersports = True
            newly_unlocked.append("watersports")

        if self.edge_play_count >= 5 and not self.unlocked_edge_mastery:
            self.unlocked_edge_mastery = True
            newly_unlocked.append("edge_mastery")

        if self.sync_count >= 3 and not self.unlocked_sync_mode:
            self.unlocked_sync_mode = True
            newly_unlocked.append("sync_mode")

        return newly_unlocked

    def get_dominant_style(self) -> str:
        """Get the dominant interaction style."""
        styles = {"verbal": self.style_verbal, "physical": self.style_physical, "silent": self.style_silent}
        if max(styles.values()) == 0:
            return "balanced"
        return max(styles, key=styles.get)

    def get_dominant_tempo(self) -> str:
        """Get the dominant tempo preference."""
        tempos = {"patient": self.tempo_patient, "eager": self.tempo_eager, "aggressive": self.tempo_aggressive}
        if max(tempos.values()) == 0:
            return "balanced"
        return max(tempos, key=tempos.get)

    def to_dict(self) -> dict:
        """Serialize for saving."""
        return {k: v for k, v in self.__dict__.items()}

    @classmethod
    def from_dict(cls, data: dict) -> 'TrustProfile':
        """Deserialize from saved data."""
        profile = cls()
        for k, v in data.items():
            if hasattr(profile, k):
                setattr(profile, k, v)
        return profile


# ═══════════════════════════════════════════════════════════════════════════════
#                    CHOICE CONSEQUENCE SYSTEM
#              Every choice has IMMEDIATE / SESSION / PERMANENT effects
# ═══════════════════════════════════════════════════════════════════════════════

@dataclass
class ChoiceConsequence:
    """Defines the consequences of a choice."""
    # Immediate effects (this round)
    her_pleasure: float = 0.0
    his_pleasure: float = 0.0
    momentum: float = 0.0
    composure: float = 0.0           # Negative = walls come down
    her_pleasure_set: Optional[float] = None  # Set to specific value (for edge)

    # Session effects
    unlock_move: Optional[str] = None
    activate_mode: Optional[str] = None
    fiend_mood_shift: Optional[str] = None
    enable_dialogue: Optional[str] = None  # Enable a dialogue pool

    # Permanent effects
    trust_vulnerability: int = 0
    trust_control: int = 0
    trust_intensity: int = 0
    trust_intimacy: int = 0
    style: Optional[str] = None      # verbal/physical/silent
    tempo: Optional[str] = None      # patient/eager/aggressive
    kink: Optional[Tuple[str, int]] = None  # (kink_name, amount)


