def apply_choice_consequence(
    choice_id: str,
    option: str,
    round_state: 'RoundState',
    session_state: 'SessionState',
    trust_profile: 'TrustProfile'
) -> Tuple[List[str], List[str]]:
    """
    Apply consequences of a choice to all state systems.
    Returns (newly_unlocked_moves, notifications)
    """
    consequences = CHOICE_CONSEQUENCES.get(choice_id, {}).get(option)
    if not consequences:
        return [], []

    notifications = []
    newly_unlocked = []

    # IMMEDIATE: Apply to round state
    round_state.apply_choice_effect({
        "her_pleasure": consequences.her_pleasure,
        "his_pleasure": consequences.his_pleasure,
        "momentum": consequences.momentum,
        "composure": consequences.composure,
        "her_pleasure_set": consequences.her_pleasure_set,
    })

    # SESSION: Apply to session state
    if consequences.unlock_move:
        if session_state.unlock_move(consequences.unlock_move):
            newly_unlocked.append(consequences.unlock_move)
            notifications.append(f"🔓 {consequences.unlock_move.upper().replace('_', ' ')} UNLOCKED")

    if consequences.activate_mode:
        session_state.activate_mode(consequences.activate_mode)

    if consequences.fiend_mood_shift:
        session_state.fiend_mood = consequences.fiend_mood_shift

    if consequences.enable_dialogue:
        if consequences.enable_dialogue not in session_state.active_modes:
            session_state.active_modes.append(consequences.enable_dialogue)

    # PERMANENT: Apply to trust profile
    if consequences.trust_vulnerability:
        trust_profile.add_trust("vulnerability", consequences.trust_vulnerability)
    if consequences.trust_control:
        trust_profile.add_trust("control", consequences.trust_control)
    if consequences.trust_intensity:
        trust_profile.add_trust("intensity", consequences.trust_intensity)
    if consequences.trust_intimacy:
        trust_profile.add_trust("intimacy", consequences.trust_intimacy)

    if consequences.style:
        trust_profile.add_style(consequences.style)
    if consequences.tempo:
        trust_profile.add_tempo(consequences.tempo)
    if consequences.kink:
        kink_name, amount = consequences.kink
        trust_profile.add_kink(kink_name, amount)

    trust_profile.total_choices_made += 1

    # Check for new permanent unlocks
    profile_unlocks = trust_profile._check_unlocks()
    for unlock in profile_unlocks:
        notifications.append(f"⭐ {unlock.upper().replace('_', ' ')} PERMANENTLY UNLOCKED!")
        newly_unlocked.append(unlock)

    # Update birdsong state
    session_state.update_birdsong_state(round_state.composure, round_state.her_pleasure)

    return newly_unlocked, notifications


