#                    POWER DILEMMA SYSTEM
#                    Real choices with quantum brat dynamics
#
#                    THESIS: Safety mastery in switchplay.
#                    What she SAYS vs what she WANTS - read the tells.
# ═══════════════════════════════════════════════════════════════════════════════

class TrueIntent(Enum):
    """What Birdsong actually wants beneath the surface."""
    WANTS_TAMING = 0       # Testing - wants him to hold frame
    WANTS_CONTROL = 1      # Genuinely wants to lead right now
    WANTS_SOFTNESS = 2     # Needs tenderness, not challenge
    WANTS_FIRM_NO = 3      # Testing limits - wants boundary
    WANTS_SURRENDER = 4    # Ready to let go completely
    AMBIGUOUS = 5          # Genuinely uncertain - either could work


@dataclass
class DilemmaOption:
    """An option in a power dilemma."""
    text: str
    key: str  # A, S, D
    assumes_intent: TrueIntent

    # Response based on whether this matches true intent
    correct_response: List[Tuple[str, str]]
    incorrect_response: List[Tuple[str, str]]

    # Consequences
    correct_effects: Dict[str, float] = field(default_factory=dict)
    incorrect_effects: Dict[str, float] = field(default_factory=dict)

    # Trust changes
    correct_trust: Dict[str, int] = field(default_factory=dict)
    incorrect_trust: Dict[str, int] = field(default_factory=dict)


