def apply_nls_markers(text: str, mood: str, intensity: float = 0.5) -> str:
    """
    Apply NLS marker swaps based on mood and intensity.
    Markers like ~oy~, ~baka~ get swapped to mood-appropriate variants.
    """
    import re
    result = text

    for marker, mood_swaps in NLS_SWAPS.items():
        # Match ~marker~ pattern (case insensitive)
        pattern = f"~{marker}~"
        if pattern.lower() not in text.lower():
            continue

        # Find best mood match
        best_mood = None
        if mood in mood_swaps:
            best_mood = mood
        else:
            for swap_mood in mood_swaps:
                if swap_mood in mood:
                    best_mood = swap_mood
                    break

        if not best_mood:
            best_mood = list(mood_swaps.keys())[0]

        options = mood_swaps[best_mood]

        # Weight selection by intensity
        if intensity > 0.7 and len(options) > 1:
            swap = random.choice(options[-2:])
        elif intensity < 0.3 and len(options) > 1:
            swap = random.choice(options[:2])
        else:
            swap = random.choice(options)

        result = re.sub(pattern, swap, result, flags=re.IGNORECASE)

    return result


