POWER_VERBS = ["flutter", "waver", "shiver", "melt", "bloom", "pulse", "twitch", "squirm"]

def inject_birdsong_nls(template: str, intensity: float = 0.5, state: str = "rambling") -> str:
    """
    Inject NLS into Birdsong dialogue template.

    Template placeholders:
      {fluster}  - Gah, Nngh, Hahhh, etc.
      {cute}     - BAKA, Mwehhh~, etc.
      {whine}    - Oiii~, Fieeeenddd~, etc.
      {react}    - —!, ~!, etc.
      {power}    - flutter, melt, etc.
    """
    import random

    # Select based on intensity and state
    if intensity > 0.7 or state in ("melting", "needy"):
        fluster_pool = ["Hahhh", "Nngh", "Guh"]
        cute_pool = ["Awaaa~", "Heeee~", "Mmm~"]
    elif state == "bratty":
        fluster_pool = ["Tch", "Gah", "Pfft"]
        cute_pool = ["BAKA", "Mwehhh~", "Nyeh~"]
    else:
        fluster_pool = BIRDSONG_FLUSTER_SOUNDS
        cute_pool = BIRDSONG_CUTE_SOUNDS

    result = template
    result = result.replace("{fluster}", random.choice(fluster_pool))
    result = result.replace("{cute}", random.choice(cute_pool))
    result = result.replace("{whine}", random.choice(BIRDSONG_WHINES))
    result = result.replace("{react}", random.choice(BIRDSONG_REACTIONS))
    result = result.replace("{power}", random.choice(POWER_VERBS))

    return result

def inject_fiend_nls(template: str, mood: str = "cheeky", intensity: float = 0.5, caught: bool = False) -> str:
    """
    Inject NLS into Fiend dialogue template.

    Template placeholders:
      {soft}     - ...hahhh., ...mm., etc.
      {breathy}  - ...hahh., ...mmn., etc.
      {cute}     - ...owo., ...uwu., etc. (LESS frequent)
      {opener}   - Sooo..., ...oi., etc.
      {catch}    - ...there it is., ...cute., etc.
      {puppy}    - ...shut up., ...do it again., etc.
      {tease}    - ...can't I?, ...maybe., etc.
      {command}  - Hold still., Look at me., etc.
      {react}    - ...mm., ...good., etc.
      {power}    - flutter, melt, etc.

    Moods: cheeky, soft, intense, puppy, feral
    """
    import random

    # Select pools based on mood and state
    if caught or mood == "puppy":
        soft_pool = FIEND_PUPPY_CAUGHT
        puppy_pool = FIEND_PUPPY_FLUSTERED
        cute_pool = FIEND_CUTE_RARE  # More likely when caught
        opener_pool = FIEND_OPENERS_SOFT
        catch_pool = FIEND_CATCHES_FOND
        tease_pool = FIEND_TEASES_SOFT
        command_pool = FIEND_COMMANDS_SOFT
        react_pool = FIEND_REACTIONS_LOW
    elif mood == "intense" or intensity > 0.8:
        soft_pool = FIEND_BREATHY
        puppy_pool = FIEND_PUPPY
        cute_pool = FIEND_CUTE_SOUNDS if random.random() < 0.2 else FIEND_BREATHY  # Rare
        opener_pool = FIEND_OPENERS_EAGER
        catch_pool = FIEND_CATCHES_SMUG
        tease_pool = FIEND_TEASES_SMUG
        command_pool = FIEND_COMMANDS_INTENSE
        react_pool = FIEND_REACTIONS_HIGH
    elif mood == "soft":
        soft_pool = FIEND_SOFT_SOUNDS
        puppy_pool = FIEND_PUPPY
        cute_pool = FIEND_CUTE_SOUNDS if random.random() < 0.3 else FIEND_PLEASED
        opener_pool = FIEND_OPENERS_SOFT
        catch_pool = FIEND_CATCHES_FOND
        tease_pool = FIEND_TEASES_SOFT
        command_pool = FIEND_COMMANDS_SOFT
        react_pool = FIEND_REACTIONS_MID
    elif mood == "feral":
        soft_pool = FIEND_PEAK
        puppy_pool = FIEND_VULNERABLE
        cute_pool = FIEND_BREATHY  # No cute when feral
        opener_pool = FIEND_COMMANDS_INTENSE
        catch_pool = FIEND_CATCHES_SMUG
        tease_pool = FIEND_TEASES_SMUG
        command_pool = FIEND_COMMANDS_INTENSE
        react_pool = FIEND_REACTIONS_HIGH
    else:  # cheeky (default)
        soft_pool = FIEND_SOFT_SOUNDS
        puppy_pool = FIEND_PUPPY
        cute_pool = FIEND_CUTE_SOUNDS if random.random() < 0.25 else FIEND_PLEASED
        opener_pool = FIEND_OPENERS
        catch_pool = FIEND_CATCHES
        tease_pool = FIEND_TEASES
        command_pool = FIEND_COMMANDS
        react_pool = FIEND_REACTIONS_MID

    result = template
    result = result.replace("{soft}", random.choice(soft_pool))
    result = result.replace("{breathy}", random.choice(FIEND_BREATHY))
    result = result.replace("{cute}", random.choice(cute_pool))
    result = result.replace("{opener}", random.choice(opener_pool))
    result = result.replace("{catch}", random.choice(catch_pool))
    result = result.replace("{puppy}", random.choice(puppy_pool))
    result = result.replace("{tease}", random.choice(tease_pool))
    result = result.replace("{command}", random.choice(command_pool))
    result = result.replace("{react}", random.choice(react_pool))
    result = result.replace("{power}", random.choice(POWER_VERBS))

    return result


# ═══════════════════════════════════════════════════════════════════════════════
#                    RECIPROCITY SYSTEM
#              Certain sounds trigger the other person to echo/respond
#              Emotional contagion - awa triggers awa, baka triggers baka
# ═══════════════════════════════════════════════════════════════════════════════

# Sounds that trigger reciprocity
RECIPROCITY_TRIGGERS = {
    # Sound pattern -> (response options, chance)
    "awa": (["...awa.", "Awa~", "...awaaa."], 0.6),
    "owo": (["...owo.", "OwO", "...owo?"], 0.5),
    "uwu": (["...uwu.", "uwu~", "...uwu."], 0.5),
    "mwehhh": (["...mwehhh.", "Mwehhh~", "mweh—"], 0.4),
    "nyeh": (["...nyeh.", "Nyeh~", "nyeh—"], 0.4),
    "hahhh": (["...hahhh.", "Hahhh—", "...hahh."], 0.3),
    # BAKA handled separately - it's special
}

# Who responds to whom
RECIPROCITY_RESPONSES = {
    # (trigger_speaker, sound) -> response_speaker
    # Birdsong's sounds trigger Fiend responses
    "BIRDSONG": {
        "awa": [("FIEND", "...awa."), ("FIEND", "...did you just awa?"), ("FIEND", "...awaaa.")],
        "owo": [("FIEND", "...owo."), ("FIEND", "OwO."), ("FIEND", "...owo?")],
        "uwu": [("FIEND", "...uwu."), ("FIEND", "..."), ("BIRDSONG", "— you uwu'd BACK—!")],
        "mwehhh": [("FIEND", "...mwehhh."), ("FIEND", "..."), ("BIRDSONG", "— did you just MWEHHH—")],
        "nyeh": [("FIEND", "...nyeh."), ("FIEND", "Nyeh."), ("BIRDSONG", "STOP COPYING ME—")],
    },
    # Fiend's sounds trigger Birdsong responses
    "FIEND": {
        "awa": [("BIRDSONG", "— Awa?!"), ("BIRDSONG", "Did you just— AWAAA—"), ("BIRDSONG", "...awa.")],
        "owo": [("BIRDSONG", "— YOU CAN'T JUST OWO—"), ("BIRDSONG", "OwO?!"), ("BIRDSONG", "...owo.")],
        "uwu": [("BIRDSONG", "— you UWU'd at me—!"), ("BIRDSONG", "The big scary— uwu?!"), ("BIRDSONG", "...uwu.")],
        "mwehhh": [("BIRDSONG", "— Mwehhh?! YOU mwehhh?!"), ("BIRDSONG", "...mwehhh."), ("BIRDSONG", "STOP—")],
        "nyeh": [("BIRDSONG", "Nyeh yourself—!"), ("BIRDSONG", "...nyeh."), ("BIRDSONG", "— that's MY sound—")],
    },
}

# ═══════════════════════════════════════════════════════════════════════════════
#                    🐐 BAKA CASCADE SYSTEM 🐐
#              BAKA is special - it's HIGHLY contagious and escalates
#              NOT dialogue replacement - an "I love you" tag when bratty
#              Two goats with anime brainrot, no shame
# ═══════════════════════════════════════════════════════════════════════════════

# BAKA variations - escalating intensity (interjections, not sentences)
BAKA_VARIATIONS = {
    # Tier 0: Standard baka
    0: ["baka", "Baka", "BAKA", "...baka.", "Baka.", "BAKA!"],

    # Tier 1: Extended baka
    1: ["bakaaa", "BAKAAA", "bakaaaa~", "baka baka"],

    # Tier 2: Emotional baka
    2: ["bakuhhh", "BAKUHHH", "bakaaah", "BAKAAAH~"],

    # Tier 3: Unhinged baka
    3: ["bakabakabaka", "BAKABAKABAKA", "bakabaka—"],

    # Tier 4: Transcendent baka (rare)
    4: ["BAKABAKABAKABAKA—", "baka— bakuhhh—", "BAAAAAKAAAAAA—"],
}

# Simple reciprocity - baka triggers baka back (as interjection, not full dialogue)
BAKA_RECIPROCITY = {
    "BIRDSONG": [  # Birdsong's baka triggers Fiend's soft baka
        "...baka.",
        "Baka.",
        "...baka?",
        "...bakabaka.",
    ],
    "FIEND": [  # Fiend's baka triggers Birdsong's loud reaction
        "— baka yourself—",
        "Don't baka ME—",
        "BAKA—!",
        "...baka.",  # Sometimes she just... accepts it
    ],
}

# Track BAKA cascade state
_baka_state = {
    "cascade_tier": 0,          # Current escalation level
    "cascade_count": 0,         # Consecutive bakas
    "last_baka_speaker": None,  # Who said baka last
    "cooldown": 0.0,            # Cooldown between triggers
}

def detect_baka(text: str) -> int:
    """Detect baka in text and return tier level."""
    text_lower = text.lower()

    # Check from highest tier down
    for tier in range(4, -1, -1):
        for variant in BAKA_VARIATIONS[tier]:
            if variant.lower() in text_lower:
                return tier

    return -1  # No baka found

def get_baka_response(trigger_speaker: str, trigger_tier: int) -> Optional[List[Tuple[str, str]]]:
    """Get BAKA reciprocity response - just an interjection, not full dialogue."""
    import random

    # Cooldown check
    if _baka_state["cooldown"] > 0:
        return None

    # 70% chance to reciprocate
    if random.random() > 0.7:
        return None

    # Update cascade state
    if _baka_state["last_baka_speaker"] != trigger_speaker:
        # Different person - might escalate
        if random.random() < 0.3:  # 30% chance to escalate on response
            _baka_state["cascade_tier"] = min(4, _baka_state["cascade_tier"] + 1)

    _baka_state["cascade_count"] += 1
    _baka_state["last_baka_speaker"] = "FIEND" if trigger_speaker == "BIRDSONG" else "BIRDSONG"
    _baka_state["cooldown"] = 5.0  # 5 second cooldown

    # Get response
    responder = "FIEND" if trigger_speaker == "BIRDSONG" else "BIRDSONG"
    responses = BAKA_RECIPROCITY.get(trigger_speaker, BAKA_RECIPROCITY["BIRDSONG"])

    response_text = random.choice(responses)

    # Maybe use escalated variant
    if _baka_state["cascade_tier"] > 0 and "baka" in response_text.lower():
        # Replace with escalated version
        escalated = random.choice(BAKA_VARIATIONS[min(_baka_state["cascade_tier"], 4)])
        if responder == "FIEND":
            escalated = "..." + escalated.lower() + "."
        response_text = escalated

    return [(responder, response_text)]

def get_random_baka(speaker: str, tier: int = None) -> str:
    """Get a random baka variation for a speaker."""
    import random

    if tier is None:
        tier = _baka_state["cascade_tier"]

    tier = min(4, max(0, tier))
    variant = random.choice(BAKA_VARIATIONS[tier])

    # Fiend's bakas are lowercase/breathy, Birdsong's are LOUD
    if speaker == "FIEND":
        if not variant.startswith("..."):
            variant = "..." + variant.lower() + "."
    else:
        if not variant.isupper() and random.random() < 0.5:
            variant = variant.upper()

    return variant

def reset_baka_cascade():
    """Reset BAKA cascade state (call after long pause in dialogue)."""
    _baka_state["cascade_tier"] = 0
    _baka_state["cascade_count"] = 0
    _baka_state["last_baka_speaker"] = None


# Track recent sounds for reciprocity (non-baka)
_reciprocity_state = {
    "last_sound": None,
    "last_speaker": None,
    "cooldown": 0.0,
}

def check_for_reciprocity_trigger(speaker: str, text: str) -> Optional[Tuple[str, str]]:
    """
    Check if text contains a sound that should trigger reciprocity.
    Returns (sound_key, matched_text) or None.
    """
    text_lower = text.lower()

    # BAKA is handled separately - check it first
    baka_tier = detect_baka(text)
    if baka_tier >= 0:
        return ("baka", str(baka_tier))

    for sound in RECIPROCITY_TRIGGERS.keys():
        if sound in text_lower:
            return (sound, sound)

    return None

def get_reciprocity_response(trigger_speaker: str, sound: str, extra: str = None) -> Optional[List[Tuple[str, str]]]:
    """
    Get a reciprocity response for a triggered sound.
    Returns dialogue lines or None if no response triggered.
    """
    import random

    # BAKA cascade handling
    if sound == "baka":
        baka_tier = int(extra) if extra else 0
        return get_baka_response(trigger_speaker, baka_tier)

    # Check cooldown for non-baka sounds
    if _reciprocity_state["cooldown"] > 0:
        return None

    # Check if same sound was just used (avoid loops)
    if _reciprocity_state["last_sound"] == sound:
        return None

    # Get chance for this sound
    _, chance = RECIPROCITY_TRIGGERS.get(sound, ([], 0))

    if random.random() > chance:
        return None

    # Get response options
    responses = RECIPROCITY_RESPONSES.get(trigger_speaker, {}).get(sound, [])
    if not responses:
        return None

    response = random.choice(responses)

    # Update state
    _reciprocity_state["last_sound"] = sound
    _reciprocity_state["last_speaker"] = trigger_speaker
    _reciprocity_state["cooldown"] = 8.0  # Don't trigger again for 8 seconds

    # Response can be single tuple or list
    if isinstance(response, tuple):
        return [response]
    return response

def update_reciprocity_cooldown(dt: float):
    """Update reciprocity cooldown timer."""
    if _reciprocity_state["cooldown"] > 0:
        _reciprocity_state["cooldown"] = max(0, _reciprocity_state["cooldown"] - dt)

    # Decay baka cooldown
    if _baka_state["cooldown"] > 0:
        _baka_state["cooldown"] = max(0, _baka_state["cooldown"] - dt)

    # Decay baka cascade tier over time (slow)
    if _baka_state["cascade_tier"] > 0 and _baka_state["cooldown"] <= 0:
        if random.random() < dt * 0.05:  # Slow decay
            _baka_state["cascade_tier"] = max(0, _baka_state["cascade_tier"] - 1)

def process_dialogue_for_reciprocity(speaker: str, text: str) -> Optional[List[Tuple[str, str]]]:
    """
    Process a dialogue line and potentially generate reciprocity response.
    Call this after displaying a line to maybe queue a follow-up.
    """
    trigger = check_for_reciprocity_trigger(speaker, text)
    if trigger:
        sound, extra = trigger
        return get_reciprocity_response(speaker, sound, extra)
    return None


# ═══════════════════════════════════════════════════════════════════════════════
#                    RHYTHM-LINKED DIALOGUE SYSTEM
# ═══════════════════════════════════════════════════════════════════════════════
#
# Dialogue that reacts to player's rhythm accuracy

RHYTHM_DIALOGUE = {
    # Player doing great (accuracy > 85%, combo > 20)
    "on_fire": [
        [("BIRDSONG", "{fluster}—! You're— hahhh— relentless—")],
        [("BIRDSONG", "Oiii~ slow DOWN— {fluster}—!")],
        [("FIEND", "{soft}"), ("BIRDSONG", "Don't just— {cute}— say SOMETHING—!")],
        [("BIRDSONG", "You're doing that— that THING— {fluster}—")],
        [("FIEND", "{opener}"), ("FIEND", "...you're good at this."), ("BIRDSONG", "{cute}!")],
    ],

    # Player doing well (accuracy > 70%, combo > 10)
    "cruising": [
        [("BIRDSONG", "Mmm~ okay FINE you're not terrible—")],
        [("FIEND", "Mm."), ("BIRDSONG", "Don't 'Mm' at me like you KNOW things—")],
        [("BIRDSONG", "You're getting— {fluster}— cocky—")],
        [("FIEND", "{catch}"), ("BIRDSONG", "I don't— {cute}— shut UP—")],
    ],

    # Player struggling (accuracy < 50% or recent misses)
    "struggling": [
        [("BIRDSONG", "Oiii~ having trouble there, Fiend~?")],
        [("FIEND", "...hahhh."), ("BIRDSONG", "Aww~ you FUMBLED— Heeee~")],
        [("BIRDSONG", "Pfft— was THAT your best~?")],
        [("FIEND", "{puppy}"), ("BIRDSONG", "— wait are you actually SAD about it—")],
        [("BIRDSONG", "It's okay Fiend~ not everyone can keep up~")],
    ],

    # Player recovering (after miss streak ends)
    "recovering": [
        [("BIRDSONG", "Oh? Getting back in the groove~?")],
        [("FIEND", "...I'm back."), ("BIRDSONG", "Tch— don't act COOL about it—")],
        [("BIRDSONG", "There we go~ that's more like it~")],
    ],

    # Big combo milestone (25, 50, 75, 100)
    "milestone": [
        [("BIRDSONG", "{fluster}—! How are you— that's— {cute}—!")],
        [("FIEND", "{opener}"), ("FIEND", "...that was {combo}."), ("BIRDSONG", "DON'T COUNT—!")],
        [("BIRDSONG", "You're not supposed to be THIS good— {fluster}—")],
        [("FIEND", "Sooo..."), ("BIRDSONG", "DON'T 'Sooo' ME RIGHT NOW—")],
    ],

    # Combo broken
    "combo_lost": [
        [("BIRDSONG", "HA—! You SLIPPED—!")],
        [("FIEND", "..."), ("BIRDSONG", "Awww~ poor Fiend~")],
        [("BIRDSONG", "Pfft— there goes your streak~")],
        [("FIEND", "{soft}"), ("BIRDSONG", "— okay that was actually cute—")],
    ],
}

def get_rhythm_dialogue(accuracy: float, combo: int, recent_misses: int,
                        combo_broken: bool = False, milestone_hit: bool = False) -> List[Tuple]:
    """
    Get dialogue appropriate for current rhythm performance.
    Returns a dialogue sequence with NLS injected.
    """
    import random

    # Determine state
    if milestone_hit and combo >= 25:
        state = "milestone"
    elif combo_broken:
        state = "combo_lost"
    elif accuracy > 0.85 and combo > 20:
        state = "on_fire"
    elif accuracy > 0.70 and combo > 10:
        state = "cruising"
    elif accuracy < 0.50 or recent_misses > 3:
        state = "struggling"
    elif recent_misses == 0 and combo > 5:
        state = "recovering"
    else:
        return []  # No special dialogue

    # Get template
    templates = RHYTHM_DIALOGUE.get(state, [])
    if not templates:
        return []

    template = random.choice(templates)

    # Inject NLS into each line
    result = []
    for speaker, text in template:
        if speaker == "BIRDSONG":
            text = inject_birdsong_nls(text, intensity=accuracy)
        elif speaker == "FIEND":
            caught = state in ("struggling", "combo_lost")
            text = inject_fiend_nls(text, caught=caught)

        # Replace combo placeholder
        text = text.replace("{combo}", str(combo))
        result.append((speaker, text))

    return result

# ═══════════════════════════════════════════════════════════════════════════════
#                    DEEP STATE DETECTION SYSTEM
# ═══════════════════════════════════════════════════════════════════════════════
#
# Routes dialogue to appropriate NLS_EXCHANGE category based on detected state

def get_state_appropriate_exchange(vibe: 'Vibe', intensity: float,
                                    recent_performance: str = "neutral") -> List[Tuple]:
    """
    Select exchange category based on detected Birdsong state + performance.
    Returns a full exchange with NLS injection.
    """
    import random

    # Detect Birdsong state from game signals
    state = detect_birdsong_state(vibe, intensity,
                                   recent_misses=getattr(vibe, 'recent_misses', 0))

    # Performance can override state
    if recent_performance == "on_fire" and state not in ("melting", "needy"):
        state = random.choice(["melting", "bratty"])  # She's affected
    elif recent_performance == "struggling":
        state = random.choice(["bratty", "rambling"])  # She teases

    # Get exchanges for this state
    exchanges = NLS_EXCHANGES.get(state, NLS_EXCHANGES.get("rambling", [[]]))
    if not exchanges:
        return []

    exchange = random.choice(exchanges)

    # Inject NLS based on state
    result = []
    for item in exchange:
        if isinstance(item, tuple) and len(item) == 2:
            speaker, text = item
            if speaker == "BIRDSONG":
                text = inject_birdsong_nls(text, intensity=intensity, state=state)
            elif speaker == "FIEND":
                # Fiend gets caught more when she's bratty
                caught = state == "bratty" and random.random() < 0.3
                text = inject_fiend_nls(text, caught=caught)
            result.append((speaker, text))
        else:
            result.append(item)  # SILENCE, SOUND, etc.

    return result

# ═══════════════════════════════════════════════════════════════════════════════
#                    INFINITE EXCHANGE GENERATOR
# ═══════════════════════════════════════════════════════════════════════════════
#
# Uses the interjection engine for truly infinite coherent dialogue

def generate_infinite_exchange(exchange_type: str = "banter",
                               birdsong_state: str = "rambling") -> List[Tuple[str, str]]:
    """
    Generate a completely new exchange using the interjection engine.
    Falls back to template-based injection if engine unavailable.

    Exchange types: banter, tease, caught, tender
    """
    if INTERJECTION_ENGINE_AVAILABLE:
        # Use the full interjection semantics engine
        lines = generate_exchange(exchange_type, length=4)
        return exchange_to_tuples(lines)
    else:
        # Fallback: use template injection
        return get_state_appropriate_exchange(
            Vibe(),  # Dummy vibe
            intensity=50.0,
            recent_performance="neutral"
        )

def generate_infinite_birdsong_line(emotion: str = "bratty") -> str:
    """Generate a single Birdsong line"""
    if INTERJECTION_ENGINE_AVAILABLE:
        emotion_map = {
            "bratty": IEmotion.BRATTY,
            "playful": IEmotion.PLAYFUL,
            "flustered": IEmotion.FLUSTERED,
            "melting": IEmotion.MELTING,
            "vulnerable": IEmotion.VULNERABLE,
            "defiant": IEmotion.DEFIANT,
        }
        target = emotion_map.get(emotion, IEmotion.BRATTY)
        line = assemble_birdsong_line(target_emotion=target)
        return line.text
    else:
        return inject_birdsong_nls("{fluster}— stop that—!", state=emotion)

def generate_infinite_fiend_line(core_type: str = "observation") -> str:
    """Generate a single Fiend line"""
    if INTERJECTION_ENGINE_AVAILABLE:
        line = assemble_fiend_line(target_core=core_type)
        return line.text
    else:
        return inject_fiend_nls("{opener} {catch}")

