def get_mastery_feedback(mastery: 'FiendMastery', profile: 'PlayerProfile') -> Optional[List[Tuple]]:
    """
    Check if player has hit a mastery milestone and return appropriate feedback.
    Returns None if no milestone hit this session.
    """
    import random

    # Check tool mastery (>70% accuracy with a tool)
    tools = ['observe', 'command', 'escalate', 'ground', 'tease']
    for tool in tools:
        accuracy = mastery.get_tool_mastery(tool)
        total = getattr(mastery, f"{tool}_total", 0)
        if accuracy > 0.7 and total > 3:  # Need some usage first
            key = f"{tool}_mastery"
            if key in MASTERY_FEEDBACK and key not in getattr(profile, 'shown_mastery', []):
                if not hasattr(profile, 'shown_mastery'):
                    profile.shown_mastery = []
                profile.shown_mastery.append(key)

                template = random.choice(MASTERY_FEEDBACK[key])
                # Inject NLS
                result = []
                for speaker, text in template:
                    if speaker == "BIRDSONG":
                        text = inject_birdsong_nls(text)
                    result.append((speaker, text))
                return result

    # Check state-reading mastery
    states = ['rambling', 'bratty', 'melting', 'needy', 'quiet']
    for state in states:
        accuracy = mastery.get_state_mastery(state)
        reads = getattr(mastery, f"{state}_reads", 0)
        if accuracy > 0.7 and reads > 3:  # Need some reads first
            key = f"read_{state}"
            if key in MASTERY_FEEDBACK and key not in getattr(profile, 'shown_mastery', []):
                if not hasattr(profile, 'shown_mastery'):
                    profile.shown_mastery = []
                profile.shown_mastery.append(key)
                return random.choice(MASTERY_FEEDBACK[key])

    # Check overall mastery level
    total_sessions = profile.total_sessions
    avg_accuracy = mastery.get_overall_mastery()

    if total_sessions >= 10 and avg_accuracy > 0.8 and "master" not in getattr(profile, 'shown_mastery', []):
        if not hasattr(profile, 'shown_mastery'):
            profile.shown_mastery = []
        profile.shown_mastery.append("master")
        template = random.choice(MASTERY_FEEDBACK["master"])
        result = []
        for speaker, text in template:
            if speaker == "BIRDSONG":
                text = inject_birdsong_nls(text)
            result.append((speaker, text))
        return result

    elif total_sessions >= 5 and avg_accuracy > 0.6 and "journeyman" not in getattr(profile, 'shown_mastery', []):
        if not hasattr(profile, 'shown_mastery'):
            profile.shown_mastery = []
        profile.shown_mastery.append("journeyman")
        template = random.choice(MASTERY_FEEDBACK["journeyman"])
        result = []
        for speaker, text in template:
            if speaker == "BIRDSONG":
                text = inject_birdsong_nls(text)
            result.append((speaker, text))
        return result

    elif total_sessions >= 2 and "apprentice" not in getattr(profile, 'shown_mastery', []):
        if not hasattr(profile, 'shown_mastery'):
            profile.shown_mastery = []
        profile.shown_mastery.append("apprentice")
        template = random.choice(MASTERY_FEEDBACK["apprentice"])
        result = []
        for speaker, text in template:
            if speaker == "BIRDSONG":
                text = inject_birdsong_nls(text)
            result.append((speaker, text))
        return result

    return None

