# Helper function to get exchanges by phase or state
def get_nls_exchange(phase_or_state: str) -> List[Tuple]:
    """Get a random NLS exchange for the given phase or state"""
    exchanges = NLS_EXCHANGES.get(phase_or_state, [])
    if not exchanges:
        # Default to approach if not found
        exchanges = NLS_EXCHANGES.get("approach", [[]])
    return random.choice(exchanges)

def get_nls_for_birdsong_state(state: str) -> List[Tuple]:
    """Get NLS exchange matching Birdsong's current state"""
    return get_nls_exchange(state)

