#                    ACHIEVEMENT DISPLAY HELPERS
# ═══════════════════════════════════════════════════════════════════════════════

def render_achievement_popup(scr, achievement: Achievement, y_start: int = 5):
    """Render an achievement unlock popup."""
    h, w = scr.getmaxyx()

    tier_colors = {
        'common': curses.A_NORMAL,
        'uncommon': curses.color_pair(4),      # Green
        'rare': curses.color_pair(6),          # Blue
        'legendary': curses.color_pair(5),     # Magenta
        'mythic': curses.color_pair(3) | curses.A_BOLD,  # Yellow bold
    }

    tier_symbols = {
        'common': '●',
        'uncommon': '◆',
        'rare': '★',
        'legendary': '✦',
        'mythic': '✧',
    }

    color = tier_colors.get(achievement.tier, curses.A_NORMAL)
    symbol = tier_symbols.get(achievement.tier, '●')

    # Box dimensions
    box_w = min(60, w - 4)
    box_x = (w - box_w) // 2

    try:
        # Header
        header = f" ACHIEVEMENT UNLOCKED "
        scr.addstr(y_start, box_x + (box_w - len(header)) // 2, header,
                   curses.A_REVERSE | color)

        # Achievement name
        name_line = f"{symbol} {achievement.name} {symbol}"
        scr.addstr(y_start + 2, box_x + (box_w - len(name_line)) // 2, name_line,
                   color | curses.A_BOLD)

        # Tier
        tier_line = f"[{achievement.tier.upper()}]"
        scr.addstr(y_start + 3, box_x + (box_w - len(tier_line)) // 2, tier_line,
                   color)

        # Description (wrapped)
        desc = achievement.description
        y = y_start + 5
        while desc and y < y_start + 12:
            line = desc[:box_w - 4]
            if len(desc) > box_w - 4:
                # Find last space
                last_space = line.rfind(' ')
                if last_space > 0:
                    line = desc[:last_space]
                    desc = desc[last_space + 1:]
                else:
                    desc = desc[box_w - 4:]
            else:
                desc = ""
            scr.addstr(y, box_x + 2, f'"{line}"', curses.A_DIM)
            y += 1

        # Reward
        if achievement.reward_description:
            y += 1
            reward_line = f"Reward: {achievement.reward_description}"
            if len(reward_line) > box_w - 4:
                reward_line = reward_line[:box_w - 7] + "..."
            scr.addstr(y, box_x + 2, reward_line, curses.color_pair(4))

    except curses.error:
        pass


def get_achievement_summary(progress: AchievementProgress) -> List[str]:
    """Get a summary of achievement progress for display."""
    total = len([a for a in ACHIEVEMENTS.values() if not a.secret])
    unlocked = len([a for a in ACHIEVEMENTS.values()
                    if a.id in progress.unlocked and not a.secret])

    lines = [
        f"Achievements: {unlocked}/{total}",
        "",
    ]

    # By tier
    for tier in ['common', 'uncommon', 'rare', 'legendary', 'mythic']:
        tier_achs = [a for a in ACHIEVEMENTS.values() if a.tier == tier and not a.secret]
        tier_unlocked = [a for a in tier_achs if a.id in progress.unlocked]
        symbol = {'common': '●', 'uncommon': '◆', 'rare': '★',
                  'legendary': '✦', 'mythic': '✧'}[tier]
        lines.append(f"  {symbol} {tier.capitalize()}: {len(tier_unlocked)}/{len(tier_achs)}")

    # Recent unlocks
    if progress.unlocked:
        lines.append("")
        lines.append("Recent:")
        recent = progress.unlocked[-3:]
        for ach_id in reversed(recent):
            ach = ACHIEVEMENTS.get(ach_id)
            if ach:
                lines.append(f"  • {ach.name}")

    return lines

