@dataclass
class PlayerProfile:
    """Persistent player profile - tracks MASTERY of being Fiend"""

    # === SESSION META ===
    total_sessions: int = 0
    total_playtime_minutes: float = 0.0
    first_session_date: str = ""
    last_session_date: str = ""

    # === DATE ROUTE (Polaroid Selection) ===
    # The last-selected girl on the polaroid board (session entry screen).
    # Only 'birdsong' is playable right now, but we persist the choice so the
    # next boot highlights what you last clicked.
    last_date_target: str = "birdsong"

    # === PROGRESSION (GEN 36) ===
    # A simple XP/level track that primarily unlocks *longer play*.
    player_level: int = 1
    player_xp: float = 0.0
    player_xp_total: float = 0.0

    # === FIEND MASTERY ===
    mastery: FiendMastery = field(default_factory=FiendMastery)

    # === TRUST PROFILE (NEW - meaningful progression) ===
    trust: TrustProfile = field(default_factory=TrustProfile)

    # === ACHIEVEMENT PROGRESS ===
    achievement_progress: AchievementProgress = field(default_factory=AchievementProgress)

    # === DIALOGUE SEEN (anti-repeat) ===
    seen_story_snippets: List[int] = field(default_factory=list)
    seen_exchanges: List[str] = field(default_factory=list)

    # === MILESTONE TRACKING ===
    achievements: List[str] = field(default_factory=list)  # Legacy - use achievement_progress
    total_climaxes: int = 0
    total_slips: int = 0
    total_wrong_holes: int = 0
    longest_combo: int = 0
    longest_session_minutes: float = 0.0
    avg_combo_peak: float = 0.0
    avg_session_length: float = 0.0
    completed_modes: Dict[str, int] = field(default_factory=dict)

    # === ESCALATION TRACKING ===
    highest_tier_ever: int = 0
    transcendence_completions: int = 0
    total_tier_attempts: Dict[int, int] = field(default_factory=dict)

    def save(self):
        """Persist to disk"""
        try:
            data = {
                "total_sessions": self.total_sessions,
                "total_playtime_minutes": self.total_playtime_minutes,
                "first_session_date": self.first_session_date,
                "last_session_date": self.last_session_date,
                "last_date_target": str(getattr(self, "last_date_target", "birdsong")),
                "player_level": int(getattr(self, "player_level", 1)),
                "player_xp": float(getattr(self, "player_xp", 0.0)),
                "player_xp_total": float(getattr(self, "player_xp_total", 0.0)),
                "mastery": self.mastery.to_dict(),
                "trust": self.trust.to_dict(),
                "achievement_progress": self.achievement_progress.to_dict(),
                "seen_story_snippets": self.seen_story_snippets[-100:],
                "seen_exchanges": self.seen_exchanges[-500:],
                "achievements": self.achievements,
                "total_climaxes": self.total_climaxes,
                "total_slips": self.total_slips,
                "total_wrong_holes": self.total_wrong_holes,
                "longest_combo": self.longest_combo,
                "longest_session_minutes": self.longest_session_minutes,
                "avg_combo_peak": self.avg_combo_peak,
                "avg_session_length": self.avg_session_length,
                "completed_modes": self.completed_modes,
                "highest_tier_ever": self.highest_tier_ever,
                "transcendence_completions": self.transcendence_completions,
                "total_tier_attempts": self.total_tier_attempts,
            }
            with open(PROFILE_PATH, 'w') as f:
                json.dump(data, f, indent=2)
        except:
            pass

    def xp_needed_for_next_level(self) -> float:
        """XP curve: gentle early, gradually steeper."""
        lvl = max(1, int(getattr(self, "player_level", 1)))
        # 100, 125, 150, 175, ...
        return float(100 + (lvl - 1) * 25)

    def get_cycle_cap(self) -> int:
        """GEN 36: unlock longer play as level rises.

        Base: 2 cycles.
        +1 cycle every 3 levels. Hard cap at 6.
        """
        lvl = max(1, int(getattr(self, "player_level", 1)))
        cap = 2 + (lvl - 1) // 3
        return int(max(2, min(6, cap)))

    def add_xp(self, amount: float) -> Tuple[int, bool]:
        """Add XP, handle level-ups. Returns (new_level, leveled_up)."""
        try:
            amt = float(amount)
        except Exception:
            amt = 0.0
        if amt <= 0:
            return int(getattr(self, "player_level", 1)), False

        self.player_xp_total = float(getattr(self, "player_xp_total", 0.0)) + amt
        self.player_xp = float(getattr(self, "player_xp", 0.0)) + amt

        leveled = False
        while self.player_xp >= self.xp_needed_for_next_level():
            self.player_xp -= self.xp_needed_for_next_level()
            self.player_level = int(getattr(self, "player_level", 1)) + 1
            leveled = True
            # Safety: don't loop forever if file corruption makes xp_needed 0
            if self.xp_needed_for_next_level() <= 0:
                break
        return int(getattr(self, "player_level", 1)), leveled

    @classmethod
    def load(cls) -> 'PlayerProfile':
        """Load from disk or create new"""
        try:
            if os.path.exists(PROFILE_PATH):
                with open(PROFILE_PATH, 'r') as f:
                    data = json.load(f)
                profile = cls()
                for key, value in data.items():
                    if key == "mastery" and isinstance(value, dict):
                        profile.mastery = FiendMastery.from_dict(value)
                    elif key == "trust" and isinstance(value, dict):
                        profile.trust = TrustProfile.from_dict(value)
                    elif key == "achievement_progress" and isinstance(value, dict):
                        profile.achievement_progress = AchievementProgress.from_dict(value)
                    elif hasattr(profile, key):
                        setattr(profile, key, value)
                return profile
        except:
            pass
        return cls()

    def record_gambit_choice(self, tool: str, birdsong_state: str, score: float):
        """Record a gambit choice - was it the Fiend move?"""
        optimal_score = FIEND_PLAYBOOK.get(birdsong_state, {}).get(tool, 0.5)
        was_optimal = score >= 0.7  # 70%+ is "correct"
        self.mastery.record_choice(tool, birdsong_state, was_optimal)

    def record_choice(self, choice_id: str, was_picked: bool, enjoyment: float = 0.5):
        """Record a choice for preference learning (simplified for now)"""
        # For now, just track that we made choices - could expand later
        pass

    def get_choice_preference(self, choice_id: str) -> float:
        """Get preference score for a choice (0-1). Returns 0.5 for unknown."""
        # For now, return neutral - could expand with learning later
        return 0.5

    def update_preference_vector(self, dimension: str, target: float, weight: float = 0.1):
        """Update a preference dimension (simplified for now)"""
        # Could track tender_vs_rough, fast_vs_slow, etc.
        pass

    def mark_seen(self, content_type: str, content_id: any):
        """Mark content as seen for anti-repeat"""
        if content_type == "story_snippet":
            if content_id not in self.seen_story_snippets:
                self.seen_story_snippets.append(content_id)
        elif content_type == "exchange":
            exchange_hash = str(hash(str(content_id)))[:12]
            if exchange_hash not in self.seen_exchanges:
                self.seen_exchanges.append(exchange_hash)
                if len(self.seen_exchanges) > 500:
                    self.seen_exchanges = self.seen_exchanges[-500:]

    def should_show(self, content_type: str, content_id: any) -> bool:
        """Check if content should be shown (anti-repeat)"""
        if content_type == "story_snippet":
            return content_id not in self.seen_story_snippets
        elif content_type == "exchange":
            exchange_hash = str(hash(str(content_id)))[:12]
            return exchange_hash not in self.seen_exchanges
        return True

    def get_mastery_report(self) -> str:
        """Get a text report of mastery progress"""
        overall = self.mastery.get_overall_mastery()
        weakest, weak_score = self.mastery.get_weakest_area()

        lines = [
            f"Overall Fiend Mastery: {overall*100:.0f}%",
            f"",
            f"Tool Mastery:",
        ]
        for tool in FIEND_TOOLS:
            score = self.mastery.get_tool_mastery(tool)
            total = getattr(self.mastery, f"{tool}_total", 0)
            lines.append(f"  {tool.upper()}: {score*100:.0f}% ({total} uses)")

        lines.append(f"")
        lines.append(f"State Reading:")
        for state in BIRDSONG_STATES:
            score = self.mastery.get_state_mastery(state)
            reads = getattr(self.mastery, f"{state}_reads", 0)
            lines.append(f"  {state.upper()}: {score*100:.0f}% ({reads} reads)")

        lines.append(f"")
        lines.append(f"Focus Area: {weakest.upper()} ({weak_score*100:.0f}%)")

        return "\n".join(lines)

