def get_transition(from_pose: str, to_pose: str) -> TransitionType:
    """Get transition type between poses"""
    key = (from_pose, to_pose)
    if key in POSE_TRANSITIONS:
        return POSE_TRANSITIONS[key]
    # Check wildcards
    if ("*", to_pose) in POSE_TRANSITIONS:
        return POSE_TRANSITIONS[("*", to_pose)]
    if (from_pose, "*") in POSE_TRANSITIONS:
        return POSE_TRANSITIONS[(from_pose, "*")]
    return TransitionType.FADE  # Default

def get_mode_pose(mode: str, intensity: float) -> str:
    """Get pose for current mode and intensity (legacy fallback)"""
    poses = MODE_POSES.get(mode, MODE_POSES["gentle"])
    for (lo, hi), pose in poses.items():
        if lo <= intensity < hi:
            return pose
    return "squat"

def get_tree_pose(current_pose: str, combo: int, misses_in_row: int, intensity: float, is_climax: bool = False) -> str:
    """Get next pose using tree diagram based on momentum"""
    if current_pose not in POSE_TREE:
        return current_pose

    tree = POSE_TREE[current_pose]

    # Climax path
    if is_climax and "next_climax" in tree:
        return tree["next_climax"]

    # Surge path: high combo = escalate
    if combo >= MOMENTUM_SURGE_THRESHOLD:
        return tree.get("next_surge", tree["next_natural"])

    # Retreat path: too many misses = pull back
    if misses_in_row >= MOMENTUM_RETREAT_THRESHOLD:
        return tree.get("next_retreat", tree["next_natural"])

    # Natural progression
    return tree["next_natural"]

def get_undulation_profile(intensity: float, combo: int) -> dict:
    """Get figure undulation intensity based on state"""
    if combo >= 20:
        return UNDULATION_PROFILES["peak"]
    elif intensity >= 80:
        return UNDULATION_PROFILES["intense"]
    elif intensity >= 50:
        return UNDULATION_PROFILES["building"]
    elif intensity >= 25:
        return UNDULATION_PROFILES["warming"]
    else:
        return UNDULATION_PROFILES["calm"]

