#                              DIALOGUE SYSTEM (COMPLETE)
#                              With pose-aware interlude selection
# ═══════════════════════════════════════════════════════════════════════════════

# === INTERLUDE POSE REQUIREMENTS ===
# Some interludes require specific poses or forbid others

INTERLUDE_POSE_DATA = {
    # Face-required interludes (eye contact, intimacy)
    "face_required": {
        "requires_face": True,
        "preferred_poses": ["face", "coy_cheek", "front_presence", "downward"],
    },
    # Back-ok interludes (physical, less verbal)
    "back_ok": {
        "requires_face": False,
        "preferred_poses": ["squat", "stand_backfacing", "downward"],
    },
    # Afterglow interludes (post-intensity)
    "afterglow": {
        "requires_face": True,
        "preferred_poses": ["laying_smile", "angled_collapse"],
    },
    # Active/challenging interludes
    "active": {
        "requires_face": True,
        "preferred_poses": ["front_presence", "strut", "coy_cheek"],
    },
}


def select_interlude_for_pose(pool: List, current_pose: str, mode: str) -> List:
    """
    Select an interlude that works with the current pose.
    If current pose forbids the interlude content, triggers pose change.
    """
    pose_ctx = POSE_CONTEXT.get(current_pose, {})
    can_see_face = pose_ctx.get("can_see_face", True)

    # For face-hidden poses, prefer interludes without eye contact dialogue
    face_dialogue_phrases = ["look at me", "eyes", "see you", "see your face", "watching you"]

    # Filter interludes
    suitable = []
    for interlude in pool:
        # Check if any line requires face visibility
        needs_face = False
        for speaker, line in interlude:
            line_lower = str(line).lower()
            if any(phrase in line_lower for phrase in face_dialogue_phrases):
                needs_face = True
                break

        if needs_face and not can_see_face:
            continue  # Skip this interlude

        suitable.append(interlude)

    # If no suitable interludes, return from full pool (pose will adapt)
    if not suitable:
        return random.choice(pool)

    return random.choice(suitable)


