class BathroomSemanticEngine:
    """
    Specialized modifier engine for bathroom scenes.

    PHILOSOPHY:
    - Bodies are bodies. This is intimacy through acceptance.
    - Feral means HONEST, not comedic or fetishistic.
    - He witnesses. She's vulnerable. Both are animals.
    - The sounds ground them in physical reality.
    """

    def __init__(self):
        self.base_engine = SemanticModifierEngine()
        self.sound_conversion_chance = 0.55  # 55% chance to convert
        self.natural_sound_chance = 0.25     # 25% chance for pure natural sound
        self.vulnerability_chance = 0.35    # 35% chance for vulnerability expression

    def reset(self, seed: int = None):
        self.base_engine.reset(seed)

    def _convert_to_bathroom_sound(self, original: str, speaker: str) -> str:
        """Convert interjection to bathroom-grounded version."""
        if random.random() > self.sound_conversion_chance:
            return original

        if speaker == "BIRDSONG":
            conversions = BATHROOM_SOUND_CONVERSIONS
            animal_pool = BATHROOM_ANIMAL_SOUNDS_B
        else:
            conversions = FIEND_BATHROOM_SOUNDS
            animal_pool = BATHROOM_ANIMAL_SOUNDS_F

        # Try direct conversion
        for key, options in conversions.items():
            if key in original.lower() or original.lower().strip() in key:
                return random.choice(options)

        # Maybe pure animal sound
        if random.random() < 0.25:
            return random.choice(animal_pool)

        return original

    def _maybe_add_natural_sound(self, speaker: str) -> Optional[str]:
        """Maybe return a natural body sound to insert."""
        if random.random() > self.natural_sound_chance:
            return None

        # Natural sounds are speaker-agnostic but context matters
        if speaker == "BIRDSONG":
            # Her body sounds
            if random.random() < 0.6:
                return random.choice(BATHROOM_NATURAL_SOUNDS)
            else:
                return random.choice(BATHROOM_VULNERABILITY_B)
        else:
            # His witness sounds
            return random.choice(FIEND_WITNESS_SOUNDS)

        return original

    def apply_bathroom_modifiers(self, speaker: str, core_text: str,
                                 intensity: float = 0.5) -> ModifierResult:
        """
        Apply modifiers with bathroom-specific enhancements.

        Higher interjection chance + sound conversions.
        """
        # Boost probabilities for bathroom context
        original_prefix_prob = self.base_engine.state.get_prefix_probability(speaker)
        original_suffix_prob = self.base_engine.state.get_suffix_probability(speaker)

        # Temporarily boost probabilities
        self.base_engine.state.vulnerability_level = min(1.0,
            self.base_engine.state.vulnerability_level + 0.25)

        # Get base result
        result = self.base_engine.apply_modifiers(speaker, core_text, intensity)

        # Convert interjections to bathroom sounds
        modified_text = result.modified

        if result.prefix_used:
            converted_prefix = self._convert_to_bathroom_sound(result.prefix_used, speaker)
            if converted_prefix != result.prefix_used:
                modified_text = modified_text.replace(result.prefix_used, converted_prefix, 1)

        if result.suffix_used:
            converted_suffix = self._convert_to_bathroom_sound(result.suffix_used, speaker)
            if converted_suffix != result.suffix_used:
                # Find and replace suffix (it's at the end)
                if result.suffix_used in modified_text:
                    idx = modified_text.rfind(result.suffix_used)
                    if idx >= 0:
                        modified_text = modified_text[:idx] + converted_suffix + modified_text[idx+len(result.suffix_used):]

        # Maybe add natural body sound (grounding in physical reality)
        natural_sound = self._maybe_add_natural_sound(speaker)
        if natural_sound and not result.prefix_used and not result.suffix_used:
            # No modifiers rolled - add a grounding sound
            if random.random() < 0.5:
                modified_text = f"{natural_sound} {modified_text}"
            else:
                modified_text = f"{modified_text} {natural_sound}"
        elif natural_sound and random.random() < 0.3:
            # Already has modifiers but maybe add natural sound too (feral layering)
            modified_text = f"{modified_text} {natural_sound}"

        # Create updated result
        return ModifierResult(
            original=result.original,
            modified=modified_text,
            prefix_mood=result.prefix_mood,
            suffix_mood=result.suffix_mood,
            prefix_used=result.prefix_used,
            suffix_used=result.suffix_used,
            entry_mood=result.entry_mood,
            exit_mood=result.exit_mood,
            branch_weight=result.branch_weight + 0.1,  # Bathroom = more variation
        )


class BathroomDialogueEngine:
    """
    Generate bathroom scene dialogue using the same core system,
    but with bathroom-specific sound modifications.

    PHILOSOPHY: Bodies are bodies. Intimacy through acceptance.
    """

    def __init__(self):
        self.living_engine = LivingDialogueEngine()
        self.bathroom_modifier = BathroomSemanticEngine()

    def generate_bathroom_sequence(self,
                                   scenario_id: str = "vulnerable_confession",
                                   seed: int = None,
                                   intensity: float = 0.6,
                                   intimacy: int = 40,
                                   max_lines: int = 12) -> List[Tuple[str, str, ModifierResult]]:
        """
        Generate bathroom dialogue sequence.

        Uses same scenarios but with bathroom sound modifications.
        Recommended scenarios for bathroom: vulnerable_confession, slow_tenderness
        """
        if seed is None:
            seed = random.randint(0, 999999)

        self.bathroom_modifier.reset(seed)
        self.living_engine.set_state(intensity, intensity * 0.7, intimacy, "peak")

        scenario = SCENARIOS.get(scenario_id, SCENARIOS["vulnerable_confession"])
        sequence = []

        speakers = ["BIRDSONG", "FIEND"]  # Bathroom usually B-focused
        last_dna = None

        for i in range(max_lines):
            speaker = speakers[i % 2]

            # Generate core line
            result = self.living_engine.generate_line(speaker, last_dna)
            if not result:
                continue

            core_text, line_id = result
            line = self.living_engine.lexicon[line_id]
            last_dna = line.dna

            # Apply bathroom modifiers
            mod_result = self.bathroom_modifier.apply_bathroom_modifiers(
                speaker, core_text, intensity + (i / max_lines) * 0.2
            )

            sequence.append((speaker, mod_result.modified, mod_result))

            # Bathroom scenes might trigger extra reactions
            if mod_result.branch_weight > 0.5 and random.random() < 0.3:
                # Insert a pure sound/reaction
                if speaker == "BIRDSONG":
                    reaction = random.choice(BATHROOM_ANIMAL_SOUNDS_B)
                    sequence.append(("BIRDSONG", reaction, mod_result))
                else:
                    reaction = random.choice(BATHROOM_ANIMAL_SOUNDS_F)
                    sequence.append(("FIEND", reaction, mod_result))

        return sequence


def generate_bathroom_dialogue(scenario_id: str = "vulnerable_confession",
                              seed: int = None,
                              intensity: float = 0.6,
                              intimacy: int = 40,
                              max_lines: int = 10) -> List[Tuple[str, str]]:
    """
    High-level function to generate bathroom scene dialogue.

    Uses the same dialogue generation as normal scenes, but:
    - Higher interjection frequency
    - Interjections convert to bathroom/animal sounds
    - Creates emergent animalism
    """
    engine = BathroomDialogueEngine()
    sequence = engine.generate_bathroom_sequence(
        scenario_id, seed, intensity, intimacy, max_lines
    )
    return [(speaker, text) for speaker, text, _ in sequence]


# Convenience function to enhance existing bathroom dialogue
def enhance_bathroom_line(speaker: str, text: str, intensity: float = 0.6) -> str:
    """
    Enhance an existing bathroom dialogue line with animal sounds.
    Can be used to process the existing BATHROOM_* dialogue pools.
    """
    engine = BathroomSemanticEngine()
    result = engine.apply_bathroom_modifiers(speaker, text, intensity)
    return result.modified

