def _ogre_log(msg: str) -> None:
    """Simple file logger for session debugging."""
    try:
        import time
        _p = user_data_path("logs", "ogre_session.log", create_parent=True)
        with open(_p, "a", encoding="utf-8") as _f:
            _f.write(f"[{time.strftime('%H:%M:%S')}] {msg}\n")
    except Exception:
        pass


# ── RELEASE ENDURANCE PATCH: universal three-minute Ogre Shader ────────────
OGRE_ENDURANCE_PATCH_VERSION = 2
OGRE_ENDURANCE_DEFAULT_SECONDS = 180.0

def _ogre_endurance_env_enabled() -> bool:
    # Intended release behavior is ON. A deliberate explicit 0/off is the only opt-out.
    raw = str(os.environ.get("LOCKKEY_ENDURANCE_MODE", "1") or "1").strip().lower()
    return raw not in ("0", "false", "no", "off", "disabled")

def _ogre_endurance_seconds() -> float:
    try:
        return max(15.0, float(os.environ.get("LOCKKEY_ENDURANCE_SECONDS", OGRE_ENDURANCE_DEFAULT_SECONDS) or OGRE_ENDURANCE_DEFAULT_SECONDS))
    except Exception:
        return OGRE_ENDURANCE_DEFAULT_SECONDS


def _mawgut_no_purple_palette():
    """Preserve glyphs/particles; prevent legacy magenta palette leakage."""
    try:
        bg = -1
        for pair_id in (3, 5, 22, 27, 31):
            try:
                curses.init_pair(pair_id, curses.COLOR_CYAN, bg)
            except Exception:
                pass
    except Exception:
        pass


def _unbroken_rhythm() -> bool:
    """BRATBOX_UNBROKEN=1 (or BRATBOX_RHYTHM_ONLY=1): the night-scene flow. No intro sequence, no
    opening/calibration choices, no interludes, no post-rhythm scenes, no
    milestones, no bathroom breaks, no branching vignettes, no modal
    consequence scenes — just unbroken rhythm with the live dialogue
    writer on top. The writer already reacts to surges/fails/tiers via
    beats, so nothing the modals carried is lost.
    Also enabled by a 'rhythm_only.txt' marker file in the game directory
    (for Windows where env vars may not propagate)."""
    _ub = os.environ.get("BRATBOX_UNBROKEN", "").strip().lower()
    _ro = os.environ.get("BRATBOX_RHYTHM_ONLY", "").strip().lower()
    if _ub in ("1", "true", "yes", "on") or _ro in ("1", "true", "yes", "on"):
        return True
    # Marker file fallback (Windows env var issues)
    try:
        _game_dir = os.path.dirname(os.path.abspath(__file__))
        if os.path.isfile(os.path.join(_game_dir, "rhythm_only.txt")):
            return True
    except Exception:
        pass
    return False


# GAMEPLAY SFX → BROWSER (v10.8). Note hits/misses and squishes used to play
# through server-side pygame synth — inaudible in the browser, which is where
# he actually plays. This appends tiny events to <session>/sfx.jsonl;
# server.py exposes them at /api/sfx and the browser plays them (~120ms
# poll): WebAudio-synthesized ticks for hits/misses, the gooey clip pool
# for squishes. Fire-and-forget; never blocks the frame loop.
_SFX_SEQ = [0]
_SFX_FILE = [None]


def _gameplay_sfx_enabled() -> bool:
    return (os.environ.get("LOCKKEY_NOTE_CLICKS", "1") or "1").strip().lower() not in (
        "0", "false", "no", "off")


def _emit_gameplay_sfx(kind: str, quality: str = "", clip: str = "") -> None:
    try:
        if not _gameplay_sfx_enabled():
            return
        if _SFX_FILE[0] is None:
            fifo_dir = os.environ.get("JASMINE_FIFO_DIR") or ""
            sess = os.path.dirname(os.path.abspath(fifo_dir)) if fifo_dir else ""
            if not sess or not os.path.isdir(sess):
                return
            _SFX_FILE[0] = os.path.join(sess, "sfx.jsonl")
        _SFX_SEQ[0] += 1
        evt = {"idx": _SFX_SEQ[0], "kind": kind, "q": quality or "",
               "t": round(time.time(), 3)}
        if clip:
            evt["clip"] = clip
        with open(_SFX_FILE[0], "a") as f:
            f.write(json.dumps(evt) + "\n")
    except Exception:
        pass


class PlayableEngineV5:
    def __init__(self, scr, tutorial_mode: bool = False, session_profile_override=None, flow_mode: bool = False):
        try:
            if certify_startup:
                certify_startup("ogre_shader", console_font=os.environ.get("LOCKKEY_CONSOLE_FONT"))
            # IMPORTANT:
            # Do not wrap the Ogre Shader curses screen in GlyphCertifiedScreen by default.
            # The certification wrapper can downgrade Unicode shade blocks (░▒▓█) into
            # dot/colon fallback glyphs, which makes lightmaps look like stippled
            # punctuation instead of the intended cell-shader art.
            #
            # Keep the wrapper available only as an explicit debug/fallback mode.
            if GlyphCertifiedScreen and _lk_env_on("LOCKKEY_GLYPH_CERTIFIED_SCREEN_DEBUG"):
                scr = GlyphCertifiedScreen(scr)
        except Exception:
            pass
        self.scr = scr
        self.config = load_config()
        self.vibe = Vibe()
        # FLOW MODE / QUICK MODE / ENDLESS MODE — env-overridable
        # LOCKKEY_QUICK_MODE=1  → no voice, super-fast typewriter, rhythm-only backbone
        # LOCKKEY_ENDLESS=1     → loop sessions indefinitely (outer loop in __main__)
        _env_quick   = str(os.environ.get("LOCKKEY_QUICK_MODE", "0")).strip().lower() in ("1","true","yes","on")
        _env_endless = str(os.environ.get("LOCKKEY_ENDLESS",   "0")).strip().lower() in ("1","true","yes","on")

        # BLACK WIND / hostile-context launch contract.
        # These env vars are meant for WotW story handoff scenes where Ogre Shader
        # should read as strained, procedural, unhappy, and non-romantic rather
        # than the normal warm "Make Love" loop.
        self.black_wind_context = _lk_env_on("LOCKKEY_BLACK_WIND") or _lk_env_text("LOCKKEY_CONTEXT_TONE").lower() in ("black_wind", "struggle", "hostile", "dread", "captive")
        self.forheroes_context = _lk_env_on("LOCKKEY_FORHEROES") or _lk_env_text("LOCKKEY_CONTEXT_TONE").lower() in ("forheroes", "for_heroes", "hana_arcade", "bratbox_arcade", "arcade_lab")
        self.context_tone = (_lk_env_text("LOCKKEY_CONTEXT_TONE") or ("black_wind" if self.black_wind_context else ("forheroes" if self.forheroes_context else "normal"))).lower()
        self.dialogue_mode = (_lk_env_text("LOCKKEY_DIALOGUE_MODE") or ("none" if self.black_wind_context else ("arcade" if self.forheroes_context else "normal"))).lower()
        self.female_participant_name, self.male_participant_name = _participant_names_from_env()
        self.intro_context_override = _lk_env_text("LOCKKEY_INTRO_CONTEXT")
        self.force_no_love_label = _lk_env_on("LOCKKEY_FORCE_NO_LOVE_LABEL") or self.black_wind_context or self.forheroes_context
        self.no_profile_save = _lk_env_on("LOCKKEY_NO_PROFILE_SAVE") or self.forheroes_context
        # surface-only prisoner bargain. This deliberately preserves the historical
        # Black Wind controls while removing release/climax termination and the
        # trailing brace gate from this one experimental integration.
        self.onryo_prison_bargain = _lk_env_on("LOCKKEY_ONRYO_PRISON_BARGAIN")
        try:
            self.onryo_prison_bargain_seconds = max(1.0, float(os.environ.get("LOCKKEY_ONRYO_PRISON_BARGAIN_SECONDS", "180.0")))
        except Exception:
            self.onryo_prison_bargain_seconds = 180.0
        self._onryo_bargain_started_at = None
        self._onryo_bargain_deadline = None
        self._onryo_bargain_time_complete = False
        self._onryo_bargain_failed = False
        self._onryo_bargain_failure_reason = ""
        self.seed_lock = _lk_seed_from_env()
        if self.seed_lock is not None:
            try:
                random.seed(int(self.seed_lock))
            except Exception:
                pass

        self.flow_mode    = bool(flow_mode) or _env_quick or self.dialogue_mode in ("none", "silent", "off", "no_dialogue")
        self.quick_mode   = bool(flow_mode) or _env_quick or self.dialogue_mode in ("none", "silent", "off", "no_dialogue")
        self.endless_mode = _env_endless
        self._black_wind_dialogue_suppressed = self.dialogue_mode in ("none", "silent", "off", "no_dialogue")

        # Voice toast
