                self.round_state.balance["miss_penalty"]=min(0.60,float(self.round_state.balance.get("miss_penalty",1.0) or 1.0)*0.55)
                self.round_state.balance["composure_drop"]=min(0.75,float(self.round_state.balance.get("composure_drop",1.0) or 1.0)*0.70)
