    def _inject_fiend_interjections_lite(self, text: str) -> str:
        """
        LITE version of Fiend interjections - very rare, single interjection only.
        Used by the fatigue-aware system.
        """
        import random

        # Skip if already has interjection markers
        if text.startswith(('...', 'Mm', 'Sooo', 'Hahhh')):
            return text

        # Simple pools
        openers = ["Mm.", "...oi.", "...hey."]
        closers = ["...cute.", "...yeah.", "...there."]

        # 60% chance: just add opener
        # 30% chance: just add closer
        # 10% chance: neither (we were called but decide not to)
        roll = random.random()

        if roll < 0.6:
            opener = random.choice(openers)
            if not text.startswith(opener[0]):
                return f"{opener} {text}"
        elif roll < 0.9:
            closer = random.choice(closers)
            if not text.endswith('.'):
                return f"{text} {closer}"

        return text

    def _inject_fiend_interjections(self, text: str) -> str:
        """
        Inject interjections into Fiend's dialogue - RARE and MEANINGFUL.

        After playtesting feedback: interjections were too frequent and
        became cumbersome. Now they're:
        - Very rare (1 in 8 lines at most)
        - Only in emotionally significant moments
        - Never stack multiple interjections
        - Cooldown between uses
        """
        import random

        # ═══════════════════════════════════════════════════════════════════
        # COOLDOWN: Track recent interjections to prevent spam
        # ═══════════════════════════════════════════════════════════════════
        if not hasattr(self, '_fiend_interjection_cooldown'):
            self._fiend_interjection_cooldown = 0

        # Decrement cooldown
        self._fiend_interjection_cooldown = max(0, self._fiend_interjection_cooldown - 1)

        # If on cooldown, return text unchanged
        if self._fiend_interjection_cooldown > 0:
            return text

        # Check if text already has interjections (don't double up)
        if text.startswith(('...', 'Mm', 'Sooo', 'Hahhh')):
            return text
        if any(tag in text for tag in ['*shiver*', '*squirm*', '...owo.']):
            return text

        # ═══════════════════════════════════════════════════════════════════
        # CHANCE: Very low - make interjections feel special
        # ═══════════════════════════════════════════════════════════════════
        base_chance = 0.12  # 12% base chance

        # Modify by context
        intensity = 0.5
        if hasattr(self, 'round_state') and self.round_state:
            # Higher chance during high intensity moments
            if self.round_state.her_pleasure and self.round_state.her_pleasure > 0.7:
                base_chance = 0.18
            # Higher chance if she's melting
            if self.round_state.composure and self.round_state.composure < 0.4:
                base_chance = 0.20

        # Roll the dice
        if random.random() > base_chance:
            return text

        # ═══════════════════════════════════════════════════════════════════
        # PICK INTERJECTION: Simple and rare
        # ═══════════════════════════════════════════════════════════════════
        # 70% front opener, 30% back catch
        if random.random() < 0.7:
            # Front opener
            openers = ["Mm.", "...oi.", "...hey.", "Sooo..."]
            opener = random.choice(openers)
            result = f"{opener} {text}"
        else:
            # Back catch (rare)
            catches = ["...there it is.", "...cute.", "...good.", "...yeah."]
            catch = random.choice(catches)
            result = f"{text} {catch}"

        # Set cooldown (8 lines before next interjection)
        self._fiend_interjection_cooldown = 8

        return result

    def _play_scene(self, scene: List, trigger_type: str = "scene", trigger_source: str = "") -> str:
        """
        Play a dialogue scene with full cascade tracking.

        STORY-IN-RHYTHM V2 (2026-09-25): Non-modal. Queues all lines through
        dialogue_commit -> DialogueDirector for barline-gated release during
        rhythm. No screen erase, no blocking, notes never stop.

        trigger_type: scene/choice/hit/miss/interjection/automatic
        trigger_source: specific trigger identifier
        """
        # STORY-IN-RHYTHM: no input flush (was modal). Lines queue non-blocking.
        if getattr(self, "_black_wind_dialogue_suppressed", False):
            return "OK"
        if getattr(self, "forheroes_context", False):
            self._fh_scene_notice(scene)
            return "OK"

        for speaker, content in scene:
            # ═══════════════════════════════════════════════════════════
            # CASCADE TRACKING - Record EVERYTHING with full context
            # Even SILENCE/PAUSE - timing is meaningful to empaths
            # ═══════════════════════════════════════════════════════════
            if hasattr(self, 'cascade'):
                # Snapshot current context
                ctx = self.cascade.snapshot_context(
                    self.round_state,
                    self.session_state,
                    self.vibe,
                    self.scene.rhythm if self.scene else None
                )

                # Detect birdsong state
                birdsong_state = "neutral"
                if hasattr(self, '_detect_birdsong_state'):
                    birdsong_state = self._detect_birdsong_state()
                ctx.birdsong_state = birdsong_state

                # Record to cascade - record_line handles type conversion
                self.cascade.record_line(
                    speaker=speaker,
                    text=content,
                    trigger_type=trigger_type,
                    trigger_source=trigger_source,
                    context=ctx
                )

            # ═══════════════════════════════════════════════════════════
            # ACHIEVEMENT TRACKING - Track dialogue for achievements
            # (disabled in tutorial mode)
            # ═══════════════════════════════════════════════════════════
            if not self.tutorial_mode and hasattr(self, 'profile') and hasattr(self.profile, 'achievement_progress'):
                emotional_state = None
                if hasattr(self, 'round_state'):
                    # Try to get current emotional context
                    if hasattr(self.round_state, 'her_mood'):
                        emotional_state = self.round_state.her_mood

                track_dialogue_achievements(
                    self.profile.achievement_progress,
                    speaker, content, emotional_state
                )
                self._check_achievements_live()

            # STORY-IN-RHYTHM: queue non-blocking instead of modal _display_line.
            # FIEND lines are suppressed at the render layer (never put words in his mouth).
            # SILENCE/PAUSE queue as timed gaps.
            try:
                result = self.dialogue_commit(speaker, content)
                # dialogue_commit returns QUEUED/SKIPPED/OK - all non-blocking.
                # Legacy QUIT/SURGE_PUSH signals no longer apply in non-modal flow.
            except Exception:
                # Fallback: try direct queue to dialogue_director
                # (FIEND turns are skipped here too — no gap for his lines.)
                try:
                    dd = getattr(self, "dialogue_director", None)
                    if dd is not None and str(speaker or "").strip().upper() != "FIEND":
                        dd.queue_line(str(speaker), str(content))
                except Exception:
                    pass
        return "OK"

    def _play_surge_push_scene(self):
        """
        SURGE PUSH - Fiend takes control, forces escalation.
        Called when player uses surge during dialogue.
        """
        # Escalation dialogue options based on current state
        push_scenes = []

        if self.round_state.her_pleasure > 0.6:
            # She's already heated - push to climax
            push_scenes = [
                [("FIEND", "No more waiting."), ("BIRDSONG", "—!")],
                [("FIEND", "Now."), ("BIRDSONG", "...yes.")],
                [("FIEND", "I'm not asking."), ("BIRDSONG", "*shiver*")],
            ]
        elif self.round_state.composure < 0.4:
            # Her walls are down - push intimacy
            push_scenes = [
                [("FIEND", "...come here."), ("BIRDSONG", "*melts*")],
                [("FIEND", "Let me."), ("BIRDSONG", "...okay.")],
                [("FIEND", "I've got you."), ("BIRDSONG", "...I know.")],
            ]
        else:
            # Normal state - assert dominance
            push_scenes = [
                [("FIEND", "My turn."), ("BIRDSONG", "Wha—")],
                [("FIEND", "...interesting."), ("BIRDSONG", "What is?"), ("FIEND", "You.")],
                [("FIEND", "Birdsong."), ("BIRDSONG", "...yeah?"), ("FIEND", "Shh.")],
            ]

        # Pick based on cascade seed for consistency
        seed = self.cascade.session_seed if hasattr(self, 'cascade') else random.randint(0, 9999)
        scene = push_scenes[seed % len(push_scenes)]

        # Play without recursive surge possibility (direct display)
        for speaker, content in scene:
            if hasattr(self, 'cascade'):
                ctx = self.cascade.snapshot_context(
                    self.round_state, self.session_state, self.vibe,
                    self.scene.rhythm if self.scene else None
                )
                self.cascade.record_line(
                    speaker=speaker, text=content,
                    trigger_type="surge_push", trigger_source="player_surge",
                    context=ctx
                )

            # Use simplified display without surge check
            self._display_line_no_surge(speaker, content)

        # Shift pose to dominant
        try:
            self.lightmap_renderer.set_pose("angled_collapse", instant=False)
        except:
            pass

    def _display_line_no_surge(self, speaker: str, content) -> str:
        """Display line without surge handling - for surge push scenes.
        
        STORY-IN-RHYTHM V2 (2026-09-25): Non-modal. Queues through dialogue_commit
        instead of blocking with screen erase + sleep. Notes never stop.
        """
        # STORY-IN-RHYTHM: queue non-blocking. JASMINE_DIRECTOR handles BIRDSONG rewrite.
        try:
            return self.dialogue_commit(speaker, content) or "OK"
        except Exception:
            return "OK"

