    def _commit_idle_q_climax(self) -> dict:
        """Resolve Q as the hidden Idle climax, never as an abandoned session."""
        if getattr(self,"_courteous_relationship",None) is not None:
            stats=self._get_stats()
            stats["idle_q_resolved_climax"] = False
            stats["session_completed"] = False
            stats["quit_requested"] = True
            stats["quit_to_menu"] = True
            return stats
        forced = str(os.environ.get("LOCKKEY_IDLE_FORCE_CLIMAX_KIND", "wrong_fill") or "wrong_fill").strip().lower()
        reproductive = forced == "reproductive"
        self._black_wind_prefinale_active = False
        self._endurance_time_complete = True
        self._terminal_climax_kind = "vaginal" if reproductive else "anal"
        self._terminal_climax_reason = "idle Q authored climax"
        self._terminal_climax_success = True
        self._terminal_climax_heir = False
        self._terminal_climax_heir_count = 0
        self._black_wind_finale_outcome = (
            "intended_reproductive_redirect" if reproductive else "wrong_hole_success"
        )
        try:
            if reproductive:
                if hasattr(self, "telemetry") and self.telemetry:
                    self._brat_arm_terminal()
                    self._force_reproductive_squat(True)
                    self.telemetry.emit_event("REPRODUCTIVE_FINALE", {
                        "route_kind": "vaginal",
                        "reason": "idle Q authored climax",
                        "success": True,
                        "heir": False,
                        "heir_count": 0,
                        "force_ovum": True,
                        "purple_cadence_qualified": False,
                        "ovum_stage": "FOLLICLE_CONTAINMENT",
                        "ovum_progress": 0.03,
                        "ovum_in_tube": False,
                        "ovum_in_chamber": False,
                        "conception_phase": "FOLLICLE_STRUGGLE",
                        "t": time.time(),
                    })
            else:
                self._external_wrong_route_lock = True
                if hasattr(self, "telemetry") and self.telemetry:
                    self.telemetry.emit_event("WRONG_ROUTE_CLIMAX", {
                        "route_kind": "anal",
                        "reason": "idle Q authored climax",
                        "success": True,
                        "heir": False,
                        "t": time.time(),
                    })
        except Exception:
            pass
        self._session_climaxed = True
        self._hard_climax_session_complete = True
        self.vibe.climax_reached = True
        self.vibe.session_time = time.time() - self.session_start
        try:
            self.round_state.climaxes_this_cycle += 1
            self.profile.total_climaxes += 1
        except Exception:
            pass
        stats = self._get_stats()
        stats["idle_q_resolved_climax"] = True
        stats["session_completed"] = True
        stats["quit_requested"] = False
        return stats

    def _route_climax_kind(self, reason: str, *, success: bool=False) -> tuple:
        """Return (kind, heir) from the locked Story/Sandbox/Bratbox table.

        Decision happens once, immediately before animation selection. The same
        frozen purple-cadence snapshot later drives campaign heir rewards.
        """
        reason_key = str(reason or "").lower()
        if self._carrion_bespoke_session():
            return "carrion", False

        relationship=getattr(self,"_courteous_relationship",None)
        if relationship is not None and str(getattr(relationship,"climax_kind","") or "") in ("vaginal","anal"):
            # Courteous Ruin's performed relationship is the route authority.
            # Conception is resolved by the embedding world from fertility;
            # this renderer reports only the act that actually occurred.
            return str(relationship.climax_kind), False
        if relationship is not None:
            # An unfinished relationship receipt must never inherit legacy
            # Black Wind's failure=vaginal fallback.
            return "anal", False

        # The failed-tutorial Black Wind is a fixed story birth: its Shader
        # succeeds reproductively, but the campaign reward is the named nursing
        # ogre aboard the barge—not a free player heir.
        if self._first_failed_tutorial_black_wind_session():
            self._terminal_purple_cadence_snapshot = self._purple_cadence_snapshot()
            return "vaginal", False

        # Hana tutorial now follows unified Bratbox skill law. A clean finish is
        # reproductive; a loss is reproductive only if purple cadence qualified
        # before animation selection. Otherwise it receives WRONG HOLE/no heir.
        if self._hana_tutorial_session():
            if success or "03:00" in reason_key or "endurance" in reason_key or "victory" in reason_key or "cycle cap" in reason_key:
                return "vaginal", True
            cadence = self._purple_cadence_snapshot()
            return ("vaginal", True) if cadence.get("qualified", False) else ("anal", False)

        black_wind = self._bw_resistance_active() or bool(getattr(self, "black_wind_context", False))
        if black_wind:
            idle_kind = str(os.environ.get("LOCKKEY_IDLE_FORCE_CLIMAX_KIND", "") or "").strip().lower()
            if idle_kind == "wrong_fill":
                return "anal", False
            if idle_kind == "reproductive":
                return "vaginal", False
            # All non-tutorial Black Wind victories/rescues go WRONG HOLE.
            # Thrust loss and miss loss go reproductive, but do not create a
            # player heir merely because the plate is reproductive.
            if success or "rescue" in reason_key or "03:00" in reason_key or "endurance" in reason_key or "victory" in reason_key:
                return "anal", False
            return "vaginal", False

        # Peasant, Kitsune, Ogre Chief, Wife, and every Bratbox subject:
        # a clean 3:00/win is reproductive. Loss is reproductive only when the
        # already-earned purple cadence qualifies; otherwise WRONG HOLE.
        if success or "03:00" in reason_key or "endurance" in reason_key or "victory" in reason_key or "cycle cap" in reason_key:
            return "vaginal", True
        cadence = self._purple_cadence_snapshot()
        return ("vaginal", True) if cadence.get("qualified", False) else ("anal", False)

