    def _start_wrong_hole_dialogue_cascade(self, now: float, reason: str) -> None:
        variants = self._wrong_hole_dialogue_variants()
        if not variants:
            return
        seed_text = "|".join((str(reason or ""), str(_lk_seed_from_env() or ""),
                              str(getattr(self, "session_number", 0) or 0),
                              str(getattr(self, "current_mode", "") or "")))
        seed = sum((i + 1) * ord(ch) for i, ch in enumerate(seed_text))
        self._terminal_wrong_hole_dialogue = list(variants[seed % len(variants)])
        self._terminal_wrong_hole_dialogue_index = 0
        self._terminal_wrong_hole_dialogue_started = float(now)

    def _update_wrong_hole_dialogue_cascade(self) -> None:
        rows = list(getattr(self, "_terminal_wrong_hole_dialogue", []) or [])
        idx = int(getattr(self, "_terminal_wrong_hole_dialogue_index", 0) or 0)
        if idx >= len(rows):
            return
        elapsed = time.perf_counter() - float(getattr(self, "_terminal_wrong_hole_dialogue_started", 0.0) or 0.0)
        dd = getattr(self, "dialogue_director", None)
        authored = getattr(self, "authored_dialogue", None)
        while idx < len(rows) and elapsed >= float(rows[idx][0]):
            _at, speaker, text = rows[idx]
            delivered = False
            # The live Ogre HUD renders authored_dialogue reliably in sandbox.
            # DialogueDirector can exist without owning the visible subtitle lane,
            # so it is only a secondary sink here.
            try:
                if authored is not None and hasattr(authored, "queue_line"):
                    authored.queue_line(str(speaker), str(text), 2.6)
                    delivered = True
            except Exception:
                pass
            if not delivered:
                try:
                    if dd is not None and hasattr(dd, "queue_line"):
                        dd.queue_line(str(speaker), str(text), ttl=2.6)
                        delivered = True
                except Exception:
                    pass
            if not delivered:
                self.pending_notifications.append(f"{speaker}: {text}")
            idx += 1
        self._terminal_wrong_hole_dialogue_index = idx

    def _non_black_wind_repro_finale_eligible(self) -> bool:
        """True when the ordinary session should own a playable repro finale.

        Black Wind keeps its inverse route. Carrion, For Heroes, and the prison
        bargain retain their bespoke lifecycle. Hana tutorial, Bratbox, and all
        other ordinary reproductive Ogre Shader sessions use this contract.
        """
        if self._carrion_bespoke_session():
            return False
        if self._bw_resistance_active() or bool(getattr(self, "black_wind_context", False)):
            return False
        if self._forheroes_active():
            return False
        if bool(getattr(self, "onryo_prison_bargain", False)):
            return False
        return True

    def _begin_non_black_wind_repro_finale(self) -> None:
        """Latch the last repro-duration window into a playable climax."""
        if bool(getattr(self, "_non_bw_repro_finale_latched", False)):
            return
        if not self._non_black_wind_repro_finale_eligible():
            return
        now = time.perf_counter()
        _kind, _heir = self._route_climax_kind(
            "ordinary non-black-wind reproductive finale", success=True
        )
        # This route is deliberately reproductive. The route table still owns
        # heir qualification, but may not redirect the visual to wrong-hole.
        _kind = "vaginal"
        self._non_bw_repro_finale_latched = True
        self._non_bw_repro_finale_failed = False
        self._non_bw_repro_finale_miss_baseline = int(getattr(self.vibe, "misses", 0) or 0)
        self._non_bw_repro_finale_started_at = now
        self._prepare_terminal_climax_visual(
            _kind,
            reason="ordinary non-black-wind reproductive finale",
            success=True,
            heir=bool(_heir),
        )
        self.pending_notifications.append("REPRODUCTIVE CLIMAX — THREE MISSES WILL DIVERT")

    def _switch_non_black_wind_repro_to_wrong_hole(self, reason: str) -> None:
        """Immediately replace the live repro finale with the full failure route."""
        if not bool(getattr(self, "_non_bw_repro_finale_latched", False)):
            return
        if bool(getattr(self, "_non_bw_repro_finale_failed", False)):
            return
        now = time.perf_counter()
        self._non_bw_repro_finale_failed = True
        self._forced_degradation_terminal = True
        self._forced_degradation_terminal_animation_started = True
        self._forced_degradation_outcome = {
            "terminal": True,
            "kind": "failure",
            "failure_reason": str(reason or "repro_finale_failure"),
        }
        self._terminal_failure_post_action = "failure_end"
        self._terminal_failure_visual_complete = False
        self._forced_degradation_terminal_animation_until = (
            now + float(self._terminal_climax_visual_duration("anal"))
        )
        try:
            overlay = self.lightmap_renderer.tactile_overlay
            overlay.squat_purple_event = None
            overlay.terminal_failure_visual_complete = False
        except Exception:
            pass
        self._prepare_terminal_climax_visual(
            "anal",
            reason=str(reason or "repro finale diverted"),
            success=False,
            heir=False,
        )
        self._session_climaxed = False
        self.vibe.climax_reached = False
        self.pending_notifications.append("THREE MISSES — WRONG HOLE FINALE")

    def _check_non_black_wind_repro_miss_failover(self) -> None:
        if not bool(getattr(self, "_non_bw_repro_finale_latched", False)):
            return
        if bool(getattr(self, "_non_bw_repro_finale_failed", False)):
            return
        baseline = int(getattr(self, "_non_bw_repro_finale_miss_baseline", 0) or 0)
        misses = int(getattr(self.vibe, "misses", 0) or 0) - baseline
        if misses >= 3:
            self._switch_non_black_wind_repro_to_wrong_hole("three misses during reproductive climax")

    def _terminal_climax_visual_duration(self, kind: str) -> float:
        """Return the authored visual lock length for the routed finale.

        WRONG HOLE now chains a short high-entry into the exact canonical
        terminal climax fork, so it should hard-exit when that shorter visual
        actually ends instead of idling until the old 20.4s blanket timer.
        """
        return 8.65 if str(kind or "").lower() == "anal" else 20.40

    def _prepare_terminal_climax_visual(self, kind: str, *, reason: str, success: bool, heir: bool) -> None:
        """Start one readable terminal plate and forbid generic afterglow."""
        now = time.perf_counter()
        if str(kind).lower() == "carrion" or self._carrion_bespoke_session():
            return
        kind = "anal" if str(kind).lower() == "anal" else "vaginal"

        # Cross-window terminal-route contract.
        # Wrong-route completion permanently suppresses later climax/conception
        # presentation downstream. A 03:00/bargain reproductive terminal tells
        # Cathedral to place the ovum at the chamber gate and fire exactly one
        # terminal completion pulse.
        try:
            _route_payload = {
                "route_kind": kind,
                "reason": str(reason or ""),
                "success": bool(success),
                "heir": bool(heir),
                "t": time.time(),
            }
            _reason_key = str(reason or "").strip().lower()
            _purple_thrust_failure = bool(
                ("thrust_failure" in _reason_key or "thrust failure" in _reason_key)
                and self._purple_cadence_warrants_heir()
            )

            if kind == "anal":
                self._external_wrong_route_lock = True
                if hasattr(self, "telemetry") and self.telemetry:
                    self.telemetry.emit_event("WRONG_ROUTE_CLIMAX", _route_payload)
            elif kind == "vaginal":
                _cadence_preview = dict(self._purple_cadence_snapshot() if bool(heir or _purple_thrust_failure) else (getattr(self, "_terminal_purple_cadence_result", {}) or {}))
                _route_payload["force_ovum"] = True
                _route_payload["purple_cadence_thrust_failure"] = bool(_purple_thrust_failure)
                _route_payload["heir_count"] = max(1 if bool(heir) else 0, int(_cadence_preview.get("heir_count", 0) or 0) if bool(heir) else 0)
                _route_payload["purple_cadence_qualified"] = bool(_cadence_preview.get("qualified", False))
                _route_payload["ovum_stage"] = "FOLLICLE_CONTAINMENT"
                _route_payload["ovum_progress"] = 0.03
                _route_payload["ovum_in_tube"] = False
                _route_payload["ovum_in_chamber"] = False
                _route_payload["conception_phase"] = "FOLLICLE_STRUGGLE"
                if hasattr(self, "telemetry") and self.telemetry:
                    self._brat_arm_terminal()
                    self._force_reproductive_squat(True)
                    self.telemetry.emit_event("REPRODUCTIVE_FINALE", _route_payload)
        except Exception:
            pass

        self._terminal_climax_kind = kind
        self._terminal_climax_reason = str(reason or "")
        self._terminal_climax_success = bool(success)
        self._terminal_climax_heir = bool(heir)
        self._conception_lock_event_emitted = False
        self._conception_event_emitted = False
        _cadence = self._purple_cadence_snapshot() if bool(heir) else {"qualified": False, "bonus": 0, "heir_count": 0}
        if bool(heir):
            _heir_count = max(1, int(_cadence.get("heir_count", 0) or 0))
        else:
            _heir_count = 0
        self._terminal_climax_heir_count = int(_heir_count)
        self._terminal_purple_cadence_result = dict(_cadence)
        self._terminal_climax_duration = self._terminal_climax_visual_duration(kind)
        # Every routed terminal climax owns an absolute session deadline. This
        # prevents reproductive failures from getting stranded in sprite AFTERGLOW
        # when a nested renderer completion flag is lost.
        self._terminal_authoritative_exit_at = now + float(self._terminal_climax_duration)
        self._terminal_authoritative_exit_done = False
        overlay = self.lightmap_renderer.tactile_overlay
        self._surge_pose_override = "squat"
        self._surge_pose_t = float(self._terminal_climax_duration)
        overlay.squat_pose_lock_until = max(float(getattr(overlay, "squat_pose_lock_until", 0.0) or 0.0), now + float(self._terminal_climax_duration))
        self._squat_degradation_warning_until = now + float(self._terminal_climax_duration)
        if kind == "anal":
            # Reuse the established alternate-insertion anatomy: musk/toot cue,
            # opening pose, then WRONG/Buck sprite geometry.  It is deliberately
            # not the normal climax with a different caption.
            try:
                overlay.musk_enabled = True
                # Use the complete canonical toot-event schema.  The renderer
                # reads several keys directly (not through .get), so a partial
                # terminal event crashes on its first frame with KeyError:
                # 'emitted'.
                _anchor = overlay._authored_anus_anchor(
                    str(getattr(overlay, "pose", "squat") or "squat"),
                    int(getattr(overlay, "last_width", 0) or 0),
                    int(getattr(overlay, "last_height", 0) or 0),
                )
                overlay.toot_event = {
                    "started": now,
                    "anchor": _anchor or (0, 0),
                    "emitted": False,
                    "origin_pose": str(getattr(overlay, "pose", "squat") or "squat"),
                    "cooldown": (9999.0, 9999.0),
                    "held": False,
                    "glitch_done": False,
                    "glitch_visible": True,
                    "glitch_direction": 1,
                    "terminal_wrong_hole": True,
                    "event_duration": float(self._terminal_climax_duration),
                    "real_lightmap_animation": True,
                    "suppress_compact_wrong_hole": True,
                    # Terminal wrong-hole uses the high routed fold and its toot
                    # zenith pressure, but must never fire the ordinary black void.
                    "suppress_toot_void": True,
                    "toot_zenith_only": True,
                    "wrong_hole_prefrantic_until": 3.85,
                }
                # One authoritative deadline owns the terminal return. Renderer
                # flags are useful telemetry only; they may not keep gameplay alive.
                self._wrong_hole_authoritative_exit_at = now + float(self._terminal_climax_duration)
                self._wrong_hole_authoritative_exit_done = False
            except Exception:
                pass
            try:
                # The real lightmap owns insertion/climax geometry. Re-enable the
                # ORIGINAL animated bucking/wrong-hole ASCII sprite as a clear
                # secondary read, while keeping the later bespoke terminal ASCII
                # choreography suppressed by suppress_compact_wrong_hole=True.
                self.sprites.pen_state = PenState.NORMAL
                self.sprites.terminal_bucking_display = False
                self.sprites.terminal_bucking_strength = 1.0
                self.sprites.terminal_bucking_frequency = 1.0
                self.sprites.wrong_timer = 0.0
                self.sprites.buck_phase = 0.0
                self.sprites.buck_combo = 0
                self.sprites.tempo_mod = 1.3
                self.sprites.jiggle_amp = 1.5
                self.sprites.jiggle_t = float(self._terminal_climax_duration)
                self.sprites.her_butt = "panic"
                self.sprites.her_face = "shock"
                self.sprites.ogre_face = "shock"
                self.sprites.shake_t = 0.0
                self.sprites.shake_amp = 0.0
            except Exception:
                pass
            self._squat_degradation_warning_text = "WRONG HOLE!"
            self.pending_notifications.append("WRONG HOLE! — ALTERNATE INSERTION")
            self._start_wrong_hole_dialogue_cascade(now, reason)
            try:
                on_wrong_hole(self.profile.achievement_progress)
            except Exception:
                pass
        else:
            self._terminal_wrong_hole_dialogue = []
            self._terminal_wrong_hole_dialogue_index = 0
            # Existing authored insertion/pump plate remains the reproductive
            # visual authority.  Hard-exit after it; never strand tutorial Hana
            # in the generic AFTERGLOW state.
            if overlay.urine_mode in ("degradation","elastic_grotesque"):
                overlay.squat_purple_event = {"started": now, "duration": 20.40, "stage": 6,
                                              "visual_stage": 6, "terminal": True,
                                              "universal_failure": not success,
                                              "failure_pump": True,
                                              "failure_loop_chain": "current_then_finale",
                                              "reproductive_insertion": True,
                                              "guaranteed_heir": bool(heir),
                                              "elastic_repro_terminal": bool(overlay.urine_mode=="elastic_grotesque"),
                                              "elastic_suckler_start_depth": float(getattr(overlay,"suckler_depth",0.0) or 0.0),
                                              "elastic_suckler_start_tier": int(getattr(overlay,"suckler_depth_tier",0) or 0),
                                              "elastic_suckler_start_arc_elapsed": float(max(0.0, time.perf_counter()-float(getattr(overlay,"suckler_arc_started",0.0) or 0.0))) if bool(getattr(overlay,"suckler_arc_started",0.0)) else 0.0}
            self._squat_degradation_warning_text = "REPRODUCTIVE CLIMAX — HOLD"
            try:
                # Emit the canonical climax telemetry/faces, but forced terminal
                # routes may never become a persistent AFTERGLOW gameplay state.
                self.sprites.trigger_climax()
                self.sprites.pen_state = PenState.NORMAL
                self.sprites.afterglow_timer = 0.0
                self.sprites.terminal_bucking_display = False
                self.sprites.terminal_bucking_strength = 1.0
                self.sprites.terminal_bucking_frequency = 1.0
            except Exception:
                pass
        self._auto_surge_queue = []

    def _begin_ogre_failure_animation(self, reason: str, *, receipt=None,
                                      bargain_failure: bool=False,
                                      post_action: str="") -> None:
        relationship=getattr(self,"_courteous_relationship",None)
        if relationship is not None and not bool(getattr(relationship,"climax_ready",False)):
            # Relationship semantics own the ongoing phrase. Legacy failure
            # cleanup is deliberately unreachable in this mode.
            return
            self._forced_degradation_terminal=False
            self._forced_degradation_terminal_animation_started=False
            self._forced_degradation_terminal_animation_until=0.0
            self._forced_degradation_outcome={}
            self._terminal_failure_visual_complete=False
            self._terminal_failure_hard_exit=False
            self._terminal_failure_session_complete=False
            self._terminal_failure_post_action=""
            self._terminal_climax_kind=""
            self._terminal_climax_reason=""
            self._terminal_climax_success=False
            self._terminal_climax_heir=False
            self._endurance_failed=False
            self._endurance_failure_reason=""
            self._auto_surge_queue=[]
            self._auto_surge_next_at=0.0
            self._squat_degradation_lock_until=0.0
            self._squat_degradation_warning_until=0.0
            self._squat_degradation_warning_text=""
            try:
                self.round_state.cycle_lives=max(1,int(getattr(self.round_state,"max_cycle_lives",1) or 1))
                self.round_state.misses=0
                self.round_state.tier_misses=0
                self.round_state.release_charge=0.0
                self.round_state.surge_charge=0.0
                self.round_state.surge_tier=0
                self.round_state.surge_combo_streak=0
            except Exception:
                pass
            try:
                overlay=self.lightmap_renderer.tactile_overlay
                overlay.squat_purple_event=None
                overlay.squat_red_event=None
                overlay.urine_event=None
                overlay.terminal_failure_visual_complete=False
            except Exception:
                pass
            try:
                self.sprites.pen_state=PenState.NORMAL
                self.sprites.terminal_bucking_display=False
                self.sprites.terminal_bucking_strength=1.0
                self.sprites.terminal_bucking_frequency=1.0
            except Exception:
                pass
            try:
                import idle_audio
                idle_audio.recover_performance(90)
            except Exception:
                pass
            self.pending_notifications.append("FIEND RECOVERS THE RHYTHM — HANA STILL DECIDES")
            return
        self._cancel_black_wind_prefinale_warning(str(reason or "mistake"))
        # Defense in depth: grip loss may never launch the explicit terminal
        # plate unless degradation mode was deliberately selected.
        if str(reason or "") == "grip_loss_thrust_failure":
            _tactile=getattr(getattr(self,"lightmap_renderer",None),"tactile_overlay",None)
            _degradation_opt_in=bool(
                _tactile is not None
                and str(getattr(_tactile,"urine_mode","") or "").lower()=="degradation"
                and not bool(getattr(_tactile,"urine_pg",False))
            )
            if not _degradation_opt_in:
                return

        """Latch any terminal Ogre loss behind an uninterrupted climax plate.

        Fatal thrust, exhausted lives, Hana Rally grip loss, Black Wind slip,
        and the 3:00 bargain all converge here. No dialogue, verdict, pose
        selection or return is legal until the full 20.4-second chained failure animation completes.
        """
        if self._carrion_bespoke_session():
            return
        if bool(getattr(self,"_forced_degradation_terminal",False)):
            return
        if self._suggestive_mode_active():
            kind, heir = self._route_climax_kind(reason, success=False)
            self._forced_degradation_terminal=True
            self._forced_degradation_outcome=dict(receipt or {"terminal":True,"kind":"failure"})
            self._forced_degradation_outcome["failure_reason"]=str(reason or "ogre_failure")
            self._forced_degradation_outcome["presentation"]="suggestive_cinematic_failure"
            self._terminal_climax_kind=kind
            self._terminal_climax_reason=str(reason or "ogre_failure")
            self._terminal_climax_success=False
            self._terminal_climax_heir=bool(heir)
            if self._bw_resistance_active() or bool(getattr(self,"black_wind_context",False)):
                self._black_wind_finale_outcome=(
                    "intended_reproductive_redirect" if kind=="vaginal" else "wrong_hole_success"
                )
            # Suggestive changes the authored presentation, never the route.
            # Complete its overwhelmed cinematic before exposing the verdict.
            self._play_climax_cutscene("overwhelmed")
            self._terminal_failure_visual_complete=True
            self._terminal_failure_hard_exit=True
            self._terminal_failure_session_complete=True
            self._terminal_failure_post_action=str(post_action or "failure_end")
            self._session_climaxed=False
            self.vibe.climax_reached=False
            if self._bw_resistance_active() or bool(getattr(self,"black_wind_context",False)):
                self._forced_degradation_black_wind_loss=True
            if bool(bargain_failure or self.onryo_prison_bargain):
                self._onryo_bargain_failed=True
                self._onryo_bargain_failure_reason=str(reason or "ogre_failure")
            self.pending_notifications.append("FAILURE — WORLD CONSEQUENCE LOCKED")
            return
        now=time.perf_counter()
        overlay=self.lightmap_renderer.tactile_overlay
        self._forced_degradation_terminal=True
        if bool(getattr(self, "endurance_mode", False)):
            self._endurance_failed = True
            self._endurance_failure_reason = str(reason or "thrust_failure")
        self._forced_degradation_outcome=dict(receipt or {"terminal":True,"kind":"failure"})
        self._forced_degradation_outcome["failure_reason"]=str(reason or "ogre_failure")
        self._forced_degradation_terminal_animation_started=True
        _kind, _heir = self._route_climax_kind(reason, success=False)
        _visual_duration = float(self._terminal_climax_visual_duration(_kind))
        self._forced_degradation_terminal_animation_until=now+_visual_duration
        # The tactile renderer, not a parallel session timer, is authoritative
        # for completion of the concatenated two-loop failure plate.
        self._terminal_failure_visual_complete=False
        try:
            overlay.terminal_failure_visual_complete=False
        except Exception:
            pass
        self._terminal_failure_post_action=str(post_action or "failure_end")
        # If the Black Wind bargain clock has just reached 03:00, transfer
        # authority from the clock to the complete terminal plate.  Otherwise
        # the outer bargain router sees an expired deadline on the very next
        # frame and emits the receipt after only one reproductive frame.
        if bool(bargain_failure or self.onryo_prison_bargain):
            self._onryo_bargain_time_complete=False
            self._onryo_bargain_deadline=max(
                float(getattr(self, "_onryo_bargain_deadline", 0.0) or 0.0),
                now + _visual_duration + 0.35,
            )
        self._prepare_terminal_climax_visual(_kind, reason=reason, success=False, heir=_heir)
        self._last_conception_strength=max(0.82 if _heir else 0.0,
                                            float(getattr(self,"_last_conception_strength",0.0) or 0.0))
        if self._bw_resistance_active() or bool(getattr(self,"black_wind_context",False)):
            self._forced_degradation_black_wind_loss=True
            self._pending_degradation_bargain_failure=bool(bargain_failure or self.onryo_prison_bargain)
        else:
            # Terminal failure is not a successful climax and must never route
            # into AFTERGLOW. It owns a hard session exit after its visual finale.
            self._terminal_failure_hard_exit=True
            self._session_climaxed=False
            self.vibe.climax_reached=False
        self._squat_degradation_warning_until=now+float(getattr(self, "_terminal_climax_duration", _visual_duration))
        self._squat_degradation_warning_text="THRUST FAILURE — HOLD"
        self.pending_notifications.append("OGRE FAILURE — FULL FAILURE LOOP BEFORE VERDICT")

    def _begin_endurance_climax_animation(self, reason: str="03:00 endurance") -> None:
        """Three-minute completion always receives a full routed finale."""
        if self._carrion_bespoke_session():
            return
        if bool(getattr(self, "_forced_degradation_terminal", False)):
            return
        if self._suggestive_mode_active():
            kind,heir=self._route_climax_kind(reason,success=True)
            self._terminal_climax_kind=kind
            self._terminal_climax_reason=str(reason or "03:00 endurance")
            self._terminal_climax_success=True
            self._terminal_climax_heir=bool(heir)
            if self._bw_resistance_active() or bool(getattr(self,"black_wind_context",False)):
                self._black_wind_finale_outcome=("wrong_hole_success" if kind=="anal" else "intended_reproductive_redirect")
            self._play_climax_cutscene("intimate")
            self._session_climaxed=True
            self._hard_climax_session_complete=True
            self.vibe.climax_reached=True
            return
        now = time.perf_counter()
        self._forced_degradation_terminal = True
        self._forced_degradation_terminal_animation_started = True
        kind, heir = self._route_climax_kind(reason, success=True)
        _visual_duration = float(self._terminal_climax_visual_duration(kind))
        self._forced_degradation_terminal_animation_until = now + _visual_duration
        self._terminal_failure_visual_complete = False
        self._terminal_failure_post_action = "success_end"
        self._forced_degradation_outcome = {"terminal": True, "kind": "success", "reason": reason}
        self._prepare_terminal_climax_visual(kind, reason=reason, success=True, heir=heir)
        self._last_conception_strength = max(float(getattr(self, "_last_conception_strength", 0.0) or 0.0),
                                             0.92 if heir else 0.0)
        self.pending_notifications.append("03:00 — FINALE LOCKED")

    def _finish_degradation_terminal_animation(self) -> None:
        # A requested Black Wind replacement that never maintained its
        # reproductive renderer for three seconds is not allowed to masquerade
        # as the authored redirect. Preserve the lineage consequence, but name
        # the exceptional wrong-hole conception honestly for receipts and
        # novelty achievements.
        if (bool(getattr(self, "_black_wind_finale_miss_latched", False))
                and str(getattr(self, "_terminal_climax_kind", "") or "") == "vaginal"
                and not bool(getattr(self, "_black_wind_repro_visual_confirmed", False))):
            self._black_wind_finale_outcome = "wrong_hole_glitch_conception"
            self._black_wind_finale_message = (
                "THE ROUTE FAILED TO CHANGE. He used the wrong hole. "
                "The correction never arrived. The Black Wind found the family line anyway."
            )
        self._emit_conception_event(reason="terminal visual complete")
        self._terminal_authoritative_exit_at = 0.0
        self._terminal_authoritative_exit_done = True
        self._wrong_hole_authoritative_exit_at = 0.0
        self._wrong_hole_authoritative_exit_done = True
        if self._pending_degradation_bargain_failure:
            self._onryo_bargain_failed=True
            self._pending_degradation_bargain_failure=False
        # Failure finale is terminal in every mode. Once the renderer proves it
        # is complete, the session may not continue through afterglow, tutorial
        # buildup, or another rhythm segment.
        self._terminal_failure_visual_complete=True
        self._terminal_failure_hard_exit=True
        self._terminal_failure_session_complete=True
        _success = bool(getattr(self, "_terminal_climax_success", False))
        self._session_climaxed = _success
        self._hard_climax_session_complete = _success
        try:
            self.vibe.climax_reached = _success
        except Exception:
            pass
        try:
            overlay=getattr(self.lightmap_renderer,'tactile_overlay',None)
            if overlay is not None:
                overlay.terminal_failure_visual_complete=True
                overlay.squat_purple_event=None
        except Exception:
            pass

    def _animate_miss_auto_surge(self, kind: str, source: str) -> None:
        """Run one queued tier through the authored Degradation APIs."""
        if self._suggestive_mode_active():
            self._auto_surge_queue=[]
            return
        kind=str(kind or "").lower();now=time.perf_counter()
        overlay=self.lightmap_renderer.tactile_overlay
        self.sprites.trigger_surge(kind)
        flash={"green":4,"red":6,"purple":5}.get(kind,6)
        shake={"green":(0.28,1.65),"red":(0.34,3.4),"purple":(0.16,0.8)}.get(kind,(0.16,0.8))
        self.lightmap_renderer.trigger_flash(flash,0.24 if kind=="green" else 0.18)
        self.lightmap_renderer.trigger_shake(*shake)
        self._recent_surge_kind=kind;self._recent_surge_t=1.45
        try:
            import idle_audio
            idle_audio.note_surge(kind,1.0)
            idle_audio.play(f"surge_{kind}",1.0)
        except Exception:
            pass
        if kind=="green":
            was_downward=(str(getattr(self.lightmap_renderer,"current_pose","") or "")=="downward"
                          or now<float(getattr(self,"_green_downward_lock_until",0.0) or 0.0))
            overlay.cancel_squat_degradation()
            self._surge_pose_override="downward";self._surge_pose_t=0.90
            self._green_downward_lock_until=now+10.0
            self._green_release_lock_active=bool(was_downward)
            if was_downward:
                reaction=overlay.trigger_green_surge(
                    "downward",quality=1.0,toot_active=bool(getattr(overlay,"toot_event",None)),
                    intensity=float(getattr(getattr(self.scene,"rhythm",None),"intensity",0.0) or 0.0),
                    combo=0,source=str(source or "miss"))
                if reaction: self.pending_notifications.append(reaction)
            else:
                self.pending_notifications.append("AUTO PULL — DOWNWARD IS FORCED")
        else:
            # Later auto tiers must visibly take the squat plate from green.
            self._green_downward_lock_until=0.0
            self._green_release_lock_active=False
            if kind=="red":
                # An auto-green stream normally owns downward for five seconds;
                # the ordered miss cascade deliberately hands pose ownership to
                # the following slap instead of hiding it behind that lock.
                overlay.urine_event=None
            self._surge_pose_override="squat";self._surge_pose_t=1.10
            receipt=overlay.trigger_squat_surge(kind,quality=1.0,source=str(source or "miss"))
            self._commit_auto_squat_receipt(receipt)
        label={"green":"AUTO PULL","red":"AUTO SMACK","purple":"AUTO THRUST"}.get(kind,"AUTO SURGE")
        self.pending_notifications.append(label)
        try:
            self.scene.result_text=label;self.scene.result_timer=0.65
        except Exception:
            pass

    def _update_miss_auto_surges(self) -> None:
        if self._suggestive_mode_active():
            self._auto_surge_queue=[]
            return
        if not self._auto_surge_queue or time.perf_counter()<float(self._auto_surge_next_at or 0.0):
            return
        event=self._auto_surge_queue.pop(0)
        kind=str(event.get("kind","") or "")
        self._animate_miss_auto_surge(kind,str(event.get("source","miss") or "miss"))
        # Red owns a complete slap/recoil cycle before purple can replace it.
        self._auto_surge_next_at=time.perf_counter()+({"green":1.05,"red":1.28,"purple":0.95}.get(kind,1.0))

    def _fh_ogre_surge_label(self, surge_kind: str) -> str:
        return {
            "green": "Fiend catches the rhythm.",
            "red": "Pressure snaps back.",
            "purple": "Purple pressure. Hana pivots late.",
        }.get(str(surge_kind or "").lower(), "Grip loss. Rally continues.")

    def _fh_register_rally_hit(self, quality: str) -> None:
        if not self._forheroes_active():
            return
        try:
            self._forheroes_rally_hits = int(getattr(self, "_forheroes_rally_hits", 0) or 0) + 1
            if str(quality or "").lower() == "perfect":
                self._forheroes_perfects = int(getattr(self, "_forheroes_perfects", 0) or 0) + 1
        except Exception:
            pass
        # Good Hana-side play slows completion rather than ending the rally faster.
        delay = {"perfect": 0.20, "great": 0.16, "good": 0.11}.get(str(quality or "").lower(), 0.08)
        try:
            elapsed = float(getattr(self, "_bw_pressure_elapsed", 0.0) or 0.0)
            wall = max(0.0, time.time() - float(getattr(self, "_bw_pressure_wall_start", time.time()) or time.time()))
            floor = max(0.0, wall * 0.30)
            self._bw_pressure_elapsed = max(floor, elapsed - delay)
        except Exception:
            pass
        try:
            self._hana_ogre_initiative = max(0.0, float(getattr(self, "_hana_ogre_initiative", 0.0) or 0.0) - delay * 9.0)
        except Exception:
            pass
        self._fh_notice(self._fh_hit_text(quality))

    def _fh_register_rally_miss(self, surge_sequence=None) -> None:
        if not self._forheroes_active():
            return
        try:
            self._bw_pressure_elapsed = float(getattr(self, "_bw_pressure_elapsed", 0.0) or 0.0) + 0.20
            self._hana_ogre_initiative = min(100.0, float(getattr(self, "_hana_ogre_initiative", 0.0) or 0.0) + 6.0)
        except Exception:
            pass
        try:
            self._forheroes_rally_misses = int(getattr(self, "_forheroes_rally_misses", 0) or 0) + 1
            self.round_state.surge_charge = 0.0
            self.round_state.surge_tier = 0
            self.round_state.surge_combo_streak = 0
            self.round_state.last_surge_type = "rally_" + str((list(surge_sequence or []) or ["pressure"])[0])
            self.round_state.surge_cooldown = max(float(getattr(self.round_state, "surge_cooldown", 0.0) or 0.0), 0.45)
        except Exception:
            pass
        self._queue_miss_auto_surges(surge_sequence,"hana_rally")
        label = self._fh_ogre_surge_label((list(surge_sequence or []) or [""])[0])
        self._fh_notice(label, force=True)
        try:
            self.scene.result_text = label
            self.scene.result_timer = 0.45
        except Exception:
            pass

    def _fh_scene_notice(self, scene: List) -> None:
        if not self._forheroes_active():
            return
        try:
            lines = [
                "Hana keeps the rally alive.",
                "Fiend reads; Hana changes the answer.",
                "The exchange resets instead of ending.",
                "Again.",
            ]
            idx = int(getattr(self, "_fh_scene_notice_idx", 0) or 0)
            self._fh_scene_notice_idx = idx + 1
            self._fh_notice(lines[idx % len(lines)], force=True)
        except Exception:
            pass

    def _bw_hit_text(self, quality: str) -> str:
        if self._idle_coy_active():
            pools = {
                "perfect": ["Hana meets him exactly.", "She goes with him—eagerly.", "Hana finds his rhythm and purrs.", "She gives him the sweetest yes."],
                "great": ["Hana rolls back to meet him.", "She follows, coy and hungry.", "Hana helps without admitting how much.", "She fits herself to his pace."],
                "good": ["Hana goes with him.", "She gives a little more.", "Hana follows his lead.", "Her hips answer for her."],
            }
            pool = pools.get(str(quality or "").lower(), pools["good"])
            try:
                idx = (int(getattr(self.vibe, "hits", 0) or 0) + int(getattr(self.vibe, "combo", 0) or 0)) % len(pool)
                return pool[idx]
            except Exception:
                return pool[0]
        pools = {
            "perfect": ["Kick timed.", "Distance gained.", "Ogre checks back.", "She keeps trying."],
            "great": ["Shove lands.", "Hana braces.", "Contact broken for a breath.", "Not yet."],
            "good": ["Hana braces.", "She twists away.", "Still trying.", "Pressure slows."],
        }
        pool = pools.get(str(quality or "").lower(), pools["good"])
        try:
            idx = (int(getattr(self.vibe, "hits", 0) or 0) + int(getattr(self.vibe, "combo", 0) or 0)) % len(pool)
            return pool[idx]
        except Exception:
            return pool[0]

    def _idle_coy_cascade_line(self, event):
        """Replace inherited resistance chatter in Idle's visible cascade."""
        trigger=str(getattr(event,"trigger_type","") or "").lower()
        source=str(getattr(event,"trigger_source","") or "").lower()
        depth=int(getattr(event,"cascade_depth",0) or 0)
        if "miss" in trigger or "miss" in source:
            pool=(
                ("MANY-SIRED","My turn, Hana. Keep your argument ready."),
                ("MANY-SIRED","Coyness noted. I am still moving."),
                ("HANA","Mm— bossy. I noticed."),
            )
        elif "surge" in trigger or "surge" in source or "choice" in trigger:
            kind=str(getattr(self,"_recent_surge_kind","") or "").lower()
            pools={
                "purple":(("HANA","Then let me meet you properly."),("HANA","I can be helpful when I want.")),
                "red":(("HANA","Harder, please. I shall deny saying that."),("MANY-SIRED","She asks so sweetly.")),
                "green":(("HANA","Come here. No—closer than that."),("HANA","Stay. I like your weight.")),
            }
            pool=pools.get(kind,(("HANA","Let me help. Just this once."),("MANY-SIRED","Once, she says.")))
        elif "automatic" in trigger or "auto" in source:
            pool=(("MANY-SIRED","I have the pace."),("HANA","I know. I am going with you."))
        else:
            pool=(
                ("HANA","It is only a fling. Hold me closer."),
                ("MANY-SIRED","There she is."),
                ("HANA","Do not look so pleased. Keep going."),
                ("HANA","I love you terribly. This is unrelated."),
            )
        return pool[depth%len(pool)]

    def _bw_surge_kind_from_charge(self) -> str:
        try:
            tier = max(
                int(getattr(self.round_state, "surge_tier", 0) or 0),
                int(float(getattr(self.round_state, "surge_charge", 0.0) or 0.0)),
            )
        except Exception:
            tier = 0
        if tier >= 3:
            return "green"
        if tier >= 2:
            return "red"
        if tier >= 1:
            return "purple"
        return ""

