    def _bw_register_resistance_hit(self, quality: str) -> None:
        if not self._bw_resistance_active():
            return
        delay = {
            "perfect": 0.26,
            "great": 0.21,
            "good": 0.15,
        }.get(str(quality or "").lower(), 0.10)
        try:
            delay *= max(0.25, min(2.5, float(os.environ.get("LOCKKEY_BLACK_WIND_RESIST_DELAY_MULT", "1.0"))))
        except Exception:
            pass
        try:
            elapsed = float(getattr(self, "_bw_pressure_elapsed", 0.0) or 0.0)
            wall = max(0.0, time.time() - float(getattr(self, "_bw_pressure_wall_start", time.time()) or time.time()))
            # Hits can stall or slightly roll back pressure, but they cannot erase the scene.
            floor = max(0.0, wall * 0.38)
            self._bw_pressure_elapsed = max(floor, elapsed - delay)
        except Exception:
            pass
        try:
            self._hana_ogre_initiative = max(0.0, float(getattr(self, "_hana_ogre_initiative", 0.0) or 0.0) - delay * 8.0)
        except Exception:
            pass
        self._bw_notice(self._bw_hit_text(quality))

