    def _bw_connection_prompt_active(self) -> bool:
        return bool(self._bw_resistance_active() and self._hana_brace_prompt_active())

    def _bw_connection_wait_tick(self, dt: float) -> None:
        self._hana_connection_wait_tick(dt, float(getattr(self, "_bw_pressure_duration", 0.0) or 0.0))

    def _bw_release_prompt(self, prompt: str) -> str:
        if not self._bw_resistance_active():
            return prompt
        key = str(prompt or "").upper()
        if "FINAL NEEDS CLIMATE" in key or "NEED CLIMATE" in key:
            return "Still not enough."
        if "BUILD PEAK" in key:
            return "She keeps trying."
        if key.startswith("ENTER "):
            return key.replace("ENTER", "BRACE", 1)
        return prompt

    def _fh_release_prompt(self, prompt: str) -> str:
        if not self._forheroes_active():
            return prompt
        key = str(prompt or "").upper()
        if "FINAL NEEDS CLIMATE" in key or "NEED CLIMATE" in key:
            return "KEEP THE RALLY ALIVE"
        if "BUILD PEAK" in key:
            return "BUILD STYLE / HOLD RALLY"
        if key.startswith("ENTER "):
            return key.replace("ENTER", "COUNTER", 1)
        return prompt

    def _bw_time_remaining(self, duration: float, segment_start: float) -> float:
        # The prison bargain is one uninterrupted, real three-minute ordeal.
        # Its verdict is governed by the monotonic session deadline, so its HUD
        # must never show the older pressure clock (which can pause or rewind in
        # other Black Wind modes).
        if self.onryo_prison_bargain:
            deadline = getattr(self, "_onryo_bargain_deadline", None)
            if deadline is None:
                started = time.perf_counter()
                self._onryo_bargain_started_at = started
                deadline = started + float(getattr(self, "onryo_prison_bargain_seconds", 180.0) or 180.0)
                self._onryo_bargain_deadline = deadline
            return max(0.0, float(deadline) - time.perf_counter())
        if self._bw_resistance_active():
            return max(0.0, float(duration) - float(getattr(self, "_bw_pressure_elapsed", 0.0) or 0.0))
        return max(0.0, float(duration) - (time.time() - float(segment_start)))

    def _held_lane_rewind_seconds(self, key: int, now: float) -> float:
        """Return progress that must be uncredited for an OS-repeat-held lane.

        Curses cannot report key-up events.  Its reliable held-key signature is
        therefore a run of same-lane repeats inside the normal debounce window.
        A short grace protects deliberate taps; sustained repeats then repay
        wall time one-for-one so freezing the chart can never finish a session.
        """
        grace = 1.25
        repeat_gap = 0.30
        prior_key = getattr(self, "_held_lane_key", None)
        prior_seen = float(getattr(self, "_held_lane_last_seen", 0.0) or 0.0)
        if key != prior_key or now - prior_seen > repeat_gap:
            self._held_lane_key = key
            self._held_lane_started_at = now
            self._held_lane_rewind_at = now + grace
            self._held_lane_warning_shown = False
        self._held_lane_last_seen = now
        started = float(getattr(self, "_held_lane_started_at", now) or now)
        if now - started < grace:
            self._held_lane_rewind_active = False
            return 0.0
        accounted = float(getattr(self, "_held_lane_rewind_at", started + grace) or (started + grace))
        rewind = max(0.0, min(repeat_gap, now - accounted))
        self._held_lane_rewind_at = now
        self._held_lane_rewind_active = True
        self._held_lane_rewind_visible_until = now + 0.40
        return rewind

    def _release_held_lane_rewind(self, now: float) -> None:
        if now - float(getattr(self, "_held_lane_last_seen", 0.0) or 0.0) <= 0.30:
            return
        self._held_lane_key = None
        self._held_lane_started_at = 0.0
        self._held_lane_rewind_at = 0.0
        self._held_lane_rewind_active = False

    def _rewind_held_lane_progress(self, seconds: float, segment_start: float, hana_side: bool) -> float:
        """Remove frozen held-key time from the authoritative completion clock."""
        rewind = max(0.0, float(seconds or 0.0))
        if rewind <= 0.0:
            return float(segment_start)
        # Every route retains a local wall-cap/finale clock. Move its origin so
        # no fallback expiry can quietly count frozen chart time.
        segment_start = float(segment_start) + rewind
        if bool(getattr(self, "endurance_mode", False)):
            self._endurance_started_at = float(
                getattr(self, "_endurance_started_at", time.perf_counter())
            ) + rewind
        if self.onryo_prison_bargain:
            self._onryo_bargain_deadline = float(
                getattr(self, "_onryo_bargain_deadline", time.perf_counter())
            ) + rewind
        if hana_side:
            self._bw_pressure_elapsed = max(
                0.0,
                float(getattr(self, "_bw_pressure_elapsed", 0.0) or 0.0) - rewind,
            )
        return float(segment_start)

    def _idle_hold_repro_enabled(self) -> bool:
        return bool(
            str(os.environ.get("LOCKKEY_IDLE_OGRE_MODE", "") or "").strip().lower()
            in ("1", "true", "yes", "on")
            and not self._suggestive_mode_active()
        )

    def _start_idle_hold_repro_preview(self, now: float) -> bool:
        """Start Idle's cancellable reproductive finale preview in-place."""
        if not self._idle_hold_repro_enabled():
            return False
        if bool(getattr(self, "_idle_hold_repro_committed", False)):
            return True
        if bool(getattr(self, "_idle_hold_repro_preview_active", False)):
            return True
        overlay = getattr(getattr(self, "lightmap_renderer", None), "tactile_overlay", None)
        if overlay is None:
            return False
        duration = float(self._terminal_climax_visual_duration("vaginal"))
        overlay.terminal_failure_visual_complete = False
        overlay.squat_purple_event = {
            "started": float(now), "duration": duration, "stage": 6,
            "visual_stage": 6, "terminal": True,
            "universal_failure": False, "failure_pump": True,
            "failure_loop_chain": "current_then_finale",
            "reproductive_insertion": True, "guaranteed_heir": False,
            "idle_hold_preview": True,
            "elastic_repro_terminal": bool(getattr(overlay, "urine_mode", "") == "elastic_grotesque"),
            "elastic_suckler_start_depth": float(getattr(overlay, "suckler_depth", 0.0) or 0.0),
            "elastic_suckler_start_tier": int(getattr(overlay, "suckler_depth_tier", 0) or 0),
            "elastic_suckler_start_arc_elapsed": 0.0,
        }
        self._idle_hold_repro_preview_active = True
        self._idle_hold_repro_preview_started_at = float(now)
        self._idle_hold_repro_service_at = float(now)
        self._idle_hold_repro_rewinding = False
        self._surge_pose_override = "squat"
        self._surge_pose_t = duration
        overlay.squat_pose_lock_until = max(
            float(getattr(overlay, "squat_pose_lock_until", 0.0) or 0.0),
            float(now) + duration,
        )
        self.pending_notifications.append("HELD NOTE - REPRODUCTIVE CLIMAX APPROACHES")
        return True

    def _commit_idle_hold_repro_preview(self, now: float) -> None:
        """Latch the already-running preview once insertion/spill has begun."""
        if bool(getattr(self, "_idle_hold_repro_committed", False)):
            return
        overlay = getattr(getattr(self, "lightmap_renderer", None), "tactile_overlay", None)
        event = getattr(overlay, "squat_purple_event", None) if overlay is not None else None
        if not isinstance(event, dict):
            return
        started = float(event.get("started", now) or now)
        duration = float(event.get("duration", self._terminal_climax_visual_duration("vaginal")) or 20.40)
        self._idle_hold_repro_committed = True
        self._idle_hold_repro_rewinding = False
        event["idle_hold_preview"] = False
        event["idle_hold_committed"] = True
        event["terminal"] = True
        self._forced_degradation_terminal = True
        self._forced_degradation_terminal_animation_started = True
        self._forced_degradation_terminal_animation_until = started + duration
        self._forced_degradation_outcome = {
            "terminal": True, "kind": "success", "reason": "idle held-note reproductive commitment"
        }
        self._terminal_failure_post_action = "success_end"
        self._terminal_failure_visual_complete = False
        self._terminal_climax_kind = "vaginal"
        self._terminal_climax_reason = "idle held-note reproductive commitment"
        self._terminal_climax_success = True
        self._terminal_climax_heir = False
        self._terminal_climax_heir_count = 0
        self._terminal_climax_duration = duration
        self._terminal_authoritative_exit_at = started + duration
        self._terminal_authoritative_exit_done = False
        self._black_wind_finale_outcome = "intended_reproductive_redirect"
        self._surge_pose_override = "squat"
        self._surge_pose_t = max(0.0, started + duration - float(now))
        try:
            self.sprites.trigger_climax()
            self.sprites.pen_state = PenState.NORMAL
            self.sprites.afterglow_timer = 0.0
        except Exception:
            pass
        self.pending_notifications.append("INSERTION AND SPILL - CLIMAX COMMITTED")

    def _service_idle_hold_repro_preview(self, wall_now: float, perf_now: float) -> None:
        if not bool(getattr(self, "_idle_hold_repro_preview_active", False)):
            return
        overlay = getattr(getattr(self, "lightmap_renderer", None), "tactile_overlay", None)
        event = getattr(overlay, "squat_purple_event", None) if overlay is not None else None
        if not isinstance(event, dict):
            self._idle_hold_repro_preview_active = False
            return
        last_service = float(getattr(self, "_idle_hold_repro_service_at", perf_now) or perf_now)
        step = max(0.0, min(0.10, float(perf_now) - last_service))
        self._idle_hold_repro_service_at = float(perf_now)
        age = max(0.0, float(perf_now) - float(event.get("started", perf_now) or perf_now))
        # The canonical terminal renderer begins active spill 0.84 seconds
        # into its 13.20-second finale phase.
        commit_age = 14.04
        held = float(wall_now) - float(getattr(self, "_held_lane_last_seen", 0.0) or 0.0) <= 0.30
        if held:
            self._idle_hold_repro_rewinding = False
            if age >= commit_age:
                self._commit_idle_hold_repro_preview(perf_now)
            return
        if bool(getattr(self, "_idle_hold_repro_committed", False)):
            return
        self._idle_hold_repro_rewinding = True
        # Move the event origin forward faster than wall time, visibly playing
        # the same authored plate backward until ordinary thrusting resumes.
        event["started"] = float(event.get("started", perf_now) or perf_now) + step * 5.0
        rewound_age = max(0.0, float(perf_now) - float(event.get("started", perf_now) or perf_now))
        if rewound_age > 0.02:
            return
        overlay.squat_purple_event = None
        overlay.terminal_failure_visual_complete = False
        overlay.squat_pose_lock_until = 0.0
        self._idle_hold_repro_preview_active = False
        self._idle_hold_repro_rewinding = False
        self._surge_pose_override = ""
        self._surge_pose_t = 0.0
        self.pending_notifications.append("HOLD RELEASED - CLIMAX REWINDS")

    def _break_clean_intimacy_streak(self, reason: str = "") -> None:
        """Reset only the quiet-play proof; never cut short an already earned shot."""
        self._clean_intimacy_hits = 0
        self._clean_intimacy_next_face = 16
        self._clean_intimacy_next_pull = 28
        self._clean_intimacy_last_surges = int(getattr(self.round_state, "surges_used", 0) or 0)

    def _award_clean_intimacy_pose(self, pose: str) -> None:
        pose = "angled_collapse" if pose == "angled_collapse" else "face"
        self._clean_intimacy_pose = pose
        self._clean_intimacy_pose_t = 3.25 if pose == "angled_collapse" else 2.20
        hostile = bool(getattr(self, "black_wind_context", False))
        if pose == "face":
            notice = "EYE CONTACT HELD" if hostile else "CLOSE READ - FACE"
            flash, shake = 3, (0.10, 0.30)
        else:
            notice = "LEVERAGE - PULL" if hostile else "PULL EARNED - RESTRAINT HELD"
            flash, shake = 2, (0.18, 0.75)
        self.pending_notifications.append(notice)
        try:
            self.lightmap_renderer.trigger_flash(flash, shake[0])
            self.lightmap_renderer.trigger_shake(shake[0], shake[1])
        except Exception:
            pass
        self._clean_intimacy_rewards.append({
            "pose": pose,
            "clean_hits": int(self._clean_intimacy_hits),
            "context": "black_wind" if hostile else ("forheroes" if self._forheroes_active() else "standard"),
            "t": round(time.perf_counter(), 4),
        })

    def _register_clean_intimacy_hit(self, quality: str) -> None:
        """Reward uninterrupted manual rhythm without spending the surge meter."""
        current_surges = int(getattr(self.round_state, "surges_used", 0) or 0)
        if current_surges != int(getattr(self, "_clean_intimacy_last_surges", current_surges)):
            self._break_clean_intimacy_streak("surge")
        self._clean_intimacy_last_surges = current_surges
        if str(quality) not in ("good", "great", "perfect"):
            return
        self._clean_intimacy_hits += 1
        if self._clean_intimacy_hits == self._clean_intimacy_next_face:
            self._award_clean_intimacy_pose("face")
        elif self._clean_intimacy_hits == self._clean_intimacy_next_pull:
            self._award_clean_intimacy_pose("angled_collapse")
            # A long clean performance can earn another authored phrase without
            # turning the reward into constant pose flicker.
            self._clean_intimacy_next_face += 32
            self._clean_intimacy_next_pull += 32

    def _trigger_rhythm_surge(self) -> bool:
        _pre_surge_charge=float(getattr(self.round_state,"surge_charge",0.0) or 0.0)
        _pre_surge_combo=int(getattr(self.vibe,"combo",0) or 0)
        _pre_surge_pose=str(getattr(self.lightmap_renderer,"current_pose","") or "")
        _green_lock_was_active=time.perf_counter()<float(getattr(self,"_green_downward_lock_until",0.0) or 0.0)
        _green_was_downward=_pre_surge_pose=="downward" or _green_lock_was_active
        surge_kind = self.round_state.consume_rhythm_surge()
        if not surge_kind:
            return False
        try:
            relationship=getattr(self,"_courteous_relationship",None)
            if relationship is not None:
                relationship.observe_surge(surge_kind)
                now=time.perf_counter()
                receipts=getattr(self,"_courteous_surge_receipts",None)
                if not isinstance(receipts,dict):
                    receipts={}
                    self._courteous_surge_receipts=receipts
                receipts[str(surge_kind)]={"used_at":now,"last":True}
                for _name,_row in receipts.items():
                    if _name!=str(surge_kind) and isinstance(_row,dict):
                        _row["last"]=False
        except Exception:
            pass
        if (os.getenv("LOCKKEY_IDLE_OGRE_MODE", "") == "1" and surge_kind == "purple"
                and self._attached_for_release()):
            # Purple owns authored insertion. It opens the continuous scene
            # soundscape but does not itself play a canned impact sample.
            self._idle_intimacy_inserted=True
        self._break_clean_intimacy_streak("surge")

        rhythm = getattr(self.scene, "rhythm", None)
        notes = []
        if rhythm is not None:
            notes = [
                n
                for n in list(getattr(rhythm, "notes", []) or [])
                if not getattr(n, "hit", False) and not getattr(n, "missed", False)
            ]
        live_notes = [n for n in notes if not getattr(n, "decoy", False)]
        live_notes.sort(key=lambda n: float(getattr(n, "y_pos", 0.0)), reverse=True)

        if surge_kind == "blank":
            # Original Ogre Shader contract: spend one rung to clear the board.
            # No pose override, anatomy animation, context gambit, or release
            # effect is allowed in Suggestive.
            cleared=0
            for note in list(live_notes):
                if self._auto_resolve_note(note,"perfect"):
                    cleared+=1
            if rhythm is not None:
                try: rhythm.notes.clear()
                except Exception: rhythm.notes=[]
            self.round_state.release_charge=min(1.0,float(getattr(self.round_state,"release_charge",0.0) or 0.0)+0.08)
            self.round_state.momentum=min(1.0,float(getattr(self.round_state,"momentum",0.0) or 0.0)+0.06)
            self.sprites.grip=max(0.0,min(3.0,float(getattr(self.sprites,"grip",0.0) or 0.0)+0.80))
            try:
                self.lightmap_renderer.trigger_flash(3,0.12)
                self.lightmap_renderer.trigger_shake(0.08,0.30)
            except Exception:
                pass
            label=f"BLANK — {cleared} NOTES CLEARED"
            self._recent_surge_kind="blank";self._recent_surge_t=0.65
            self.pending_notifications.append(label)
            try:
                self.scene.result_text=label;self.scene.result_timer=0.45
            except Exception:
                pass
            return True

        if surge_kind == "purple":
            release_gain = 0.07
            climate_gain = 0.05
            grip_bonus = 0.90
            momentum_gain = 0.03
            flash_color = 5
            shake = (0.16, 0.8)
            _degradation_mode=getattr(getattr(self.lightmap_renderer,"tactile_overlay",None),"urine_mode","")=="degradation"
            self._surge_pose_override = "squat" if _degradation_mode else ""
            self._surge_pose_t = 0.52 if _degradation_mode else 0.0
            auto_quality = "great"
            auto_count = min(len(live_notes), max(1, int(math.ceil(len(live_notes) * 0.18)))) if live_notes else 0
            resolved = live_notes[:auto_count]
            remainder = live_notes[auto_count:]
            for note in resolved:
                self._auto_resolve_note(note, auto_quality)
            for note in remainder:
                self._rephase_rhythm_note(note, float(getattr(note, "y_pos", 0.0)) - random.uniform(0.16, 0.28))
        elif surge_kind == "red":
            release_gain = 0.13
            climate_gain = 0.09
            grip_bonus = 0.30
            momentum_gain = 0.10
            flash_color = 6
            shake = (0.20, 1.05)
            self._surge_pose_override = "squat"
            self._surge_pose_t = 0.34
            auto_quality = "good"
            auto_count = min(len(live_notes), max(1, int(math.ceil(len(live_notes) * 0.08)))) if live_notes else 0
            resolved = live_notes[:auto_count]
            remainder = live_notes[auto_count:]
            for note in resolved:
                self._auto_resolve_note(note, auto_quality)
            for note in remainder[:max(0, min(4, len(remainder)))]:
                self._rephase_rhythm_note(note, float(getattr(note, "y_pos", 0.0)) + random.uniform(0.02, 0.08))
        else:
            release_gain = 0.17
            climate_gain = 0.18
            grip_bonus = -0.45
            momentum_gain = 0.12
            flash_color = 4
            shake = (0.28, 1.65)
            self._surge_pose_override = "downward"
            self._surge_pose_t = 0.46
            # First green creates a generous ten-second setup. A green struck
            # during that setup (or while naturally downward) starts/restarts a
            # fifteen-second chain window. The visible release still completes
            # its authored five-second burst/dribble, while the longer pose lock
            # lets an expert survive note rearrangement, an auto-cast to zero,
            # and rebuild green. Repeated hits refresh rather than stack it.
            _green_lock_seconds=15.0 if _green_was_downward else 10.0
            self._green_downward_lock_until=time.perf_counter()+_green_lock_seconds
            self._green_release_lock_active=bool(_green_was_downward)
            auto_quality = "perfect"
            auto_count = min(len(live_notes), max(1, int(math.ceil(len(live_notes) * 0.35)))) if live_notes else 0
            resolved = live_notes[:auto_count]
            remainder = live_notes[auto_count:]
            for note in resolved:
                self._auto_resolve_note(note, auto_quality)
            for note in remainder:
                self._rephase_rhythm_note(note, float(getattr(note, "y_pos", 0.0)) + random.uniform(0.18, 0.30))
            if int(getattr(self.round_state, "tier", 0) or 0) < 4:
                self._escalate_cycle_tier("pull")

        self.sprites.trigger_surge(surge_kind)
        try:
            self.lightmap_renderer.trigger_flash(flash_color, 0.18 if surge_kind != "green" else 0.24)
            self.lightmap_renderer.trigger_shake(*shake)
        except Exception:
            pass

        self.round_state.release_charge = min(
            1.0, float(getattr(self.round_state, "release_charge", 0.0)) + release_gain
        )
        self.round_state.surge_charge = min(
            3.0, float(getattr(self.round_state, "surge_charge", 0.0)) + climate_gain
        )
        self.round_state.surge_tier = int(self.round_state.surge_charge)
        self.round_state.momentum = max(
            -1.0, min(1.0, float(getattr(self.round_state, "momentum", 0.0)) + momentum_gain)
        )
        self.sprites.grip = max(0.0, min(3.0, float(getattr(self.sprites, "grip", 0.0)) + grip_bonus))
        if surge_kind == "green":
            self.round_state.composure = max(
                0.0, float(getattr(self.round_state, "composure", 1.0)) - 0.03
            )
        self._recent_surge_kind = surge_kind
        self._recent_surge_t = 1.45
        try:
            import idle_audio
            idle_audio.note_surge(surge_kind,quality)
            idle_audio.play(f"surge_{surge_kind}",quality)
        except Exception:
            pass

        if surge_kind == "green":
            try:
                overlay=self.lightmap_renderer.tactile_overlay
                overlay.cancel_squat_degradation()
                toot=bool(getattr(overlay,"toot_event",None))
                accuracy=float(getattr(self.vibe,"hits",0) or 0)/max(1,float((getattr(self.vibe,"hits",0) or 0)+(getattr(self.vibe,"misses",0) or 0)))
                quality=max(0.35,min(1.0,0.42+accuracy*0.34+min(20,_pre_surge_combo)*0.012+max(0.0,_pre_surge_charge-2.8)*0.35))
                reaction=overlay.trigger_green_surge(
                    "downward" if _green_was_downward else _pre_surge_pose,quality=quality,toot_active=toot,
                    intensity=float(getattr(self.scene.rhythm,"intensity",0.0) or 0.0),
                    combo=_pre_surge_combo,
                )
                if reaction:
                    self.pending_notifications.append(reaction)
                    witness_pool=(
                        ["The witness says nothing. That is somehow worse.","Someone laughs into their sleeve.","A clinical voice notes that the floor will remember."]
                        if getattr(overlay,"urine_mode","")!="degradation" else
                        ["The room notices before she can pretend otherwise.","Someone counts the lingering drops aloud.","No one grants her the mercy of looking away."]
                    )
                    _stage=int(getattr(overlay,"degradation_stage",0) or 0)
                    if getattr(overlay,"urine_mode","")!="degradation" or _stage in (3,6,8):
                        self.pending_notifications.append(witness_pool[(getattr(overlay,"urine_surges",1)-1)%len(witness_pool)])
                elif not _green_was_downward:
                    self.pending_notifications.append("DOWNWARD HELD — TEN SECONDS TO PULL GREEN AGAIN")
            except Exception:
                pass
        elif surge_kind in ("red","purple"):
            try:
                overlay=self.lightmap_renderer.tactile_overlay
                accuracy=float(getattr(self.vibe,"hits",0) or 0)/max(1,float((getattr(self.vibe,"hits",0) or 0)+(getattr(self.vibe,"misses",0) or 0)))
                quality=max(0.35,min(1.0,0.46+accuracy*0.38+min(18,_pre_surge_combo)*0.010))
                squat_receipt=overlay.trigger_squat_surge(surge_kind,quality=quality)
                if squat_receipt and getattr(self,"_courteous_relationship",None) is not None:
                    squat_receipt["reaction"]=""
                    squat_receipt["transition"]=""
                    squat_receipt["milestone"]=0
                    squat_receipt.pop("warning",None)
                    squat_receipt.pop("terminal",None)
                if squat_receipt:
                    if surge_kind=="red":
                        self.lightmap_renderer.trigger_shake(0.34,3.4)
                        self.lightmap_renderer.trigger_flash(6,0.10)
                    reaction=str(squat_receipt.get("reaction","") or "")
                    if reaction:
                        self.pending_notifications.append(reaction)
                    transition=str(squat_receipt.get("transition","") or "")
                    transition_line={
                        "green_to_red":"The held pose turns the next impact into a clean launch.",
                        "purple_to_red":"The recovery is interrupted before the stance settles.",
                        "red_to_purple":"The recoil folds directly into a longer cadence.",
                        "green_to_purple":"The downward hold breaks and reforms as a sustained phrase.",
                    }.get(transition,"")
                    if transition_line:self.pending_notifications.append(transition_line)
                    milestone=int(squat_receipt.get("milestone",0) or 0)
                    if milestone==3:self.pending_notifications.append(f"{surge_kind.upper()} PATTERN — THIRD PHRASE AUTHORED")
                    elif milestone>=5:self.pending_notifications.append(f"{surge_kind.upper()} FINISHER — FIFTH PHRASE AUTHORED")
                    self._squat_degradation_lock_until=max(
                        float(getattr(self,"_squat_degradation_lock_until",0.0) or 0.0),
                        time.perf_counter()+9.0,
                    )
                    if bool(squat_receipt.get("warning",False)):
                        self._squat_degradation_warning_until=time.perf_counter()+3.8
                        self._squat_degradation_warning_text="TOO HARD — STOP"
                    if bool(squat_receipt.get("terminal",False)) and not bool(getattr(self,"_forced_degradation_terminal",False)):
                        self._begin_degradation_terminal_animation(squat_receipt)
                    if getattr(self,"_courteous_relationship",None) is not None:
                        self._squat_degradation_lock_until=0.0
                        self._squat_degradation_warning_until=0.0
                        self._squat_degradation_warning_text=""
            except Exception:
                pass

        if self._bw_resistance_active():
            surge_label = self._bw_player_surge_label(surge_kind)
        else:
            surge_label = {
                "purple": "THRUST SURGE",
                "red": "SMACK SURGE",
                "green": "PULL SURGE",
            }.get(surge_kind, f"{surge_kind.upper()} SURGE")
        self.pending_notifications.append(surge_label)
        try:
            self.scene.result_text = surge_label
            self.scene.result_timer = 0.45
        except Exception:
            pass
        return True

    def _play_her_commit_climax(self, stage: int) -> str:
        stage = max(1, min(int(stage), 2))
        self._surge_pose_override = "laying_smile" if stage == 1 else "downward"
        self._surge_pose_t = 0.72 if stage == 1 else 0.86
        try:
            self.lightmap_renderer.set_pose(self._surge_pose_override)
        except Exception:
            pass
        self.sprites.trigger_surge("red" if stage == 1 else "green")
        try:
            self.lightmap_renderer.trigger_flash(4 if stage == 1 else 5, 0.30)
            self.lightmap_renderer.trigger_shake(0.24, 1.15 + 0.18 * stage)
        except Exception:
            pass

        self.round_state.her_pleasure = min(1.0, float(getattr(self.round_state, "her_pleasure", 0.0)) + 0.18)
        self.round_state.momentum = min(1.0, float(getattr(self.round_state, "momentum", 0.0)) + 0.10)
        self.round_state.release_charge = 0.36 if stage == 1 else 0.30
        self.round_state.surge_charge = max(
            1.95 if stage == 1 else 2.15,
            float(getattr(self.round_state, "surge_charge", 0.0)) - (0.22 if stage == 1 else 0.18)
        )
        self.round_state.surge_tier = int(self.round_state.surge_charge)
        self.round_state.surge_combo_streak = 0
        try:
            self.scene.rhythm.intensity = min(100.0, float(getattr(self.scene.rhythm, "intensity", 0.0)) + 5.0)
        except Exception:
            pass

        self._escalate_cycle_tier(f"resistance {stage}" if self._bw_resistance_active() else f"climax {stage}")
        if self._bw_resistance_active():
            self.pending_notifications.append(f"BRACE HELD {stage}/2")
            notice_result = self._play_release_notice_hold(
                f"BRACE HELD {stage}/2",
                "Distance gained.",
                duration=0.82,
                pulse_color=4,
                pose_override="",
            )
            return "QUIT" if notice_result == "QUIT" else "OK"
        self.pending_notifications.append(f"HER CLIMAX {stage}/2")

        scene_pool = {
            1: [
                [("BIRDSONG", "Fiend— wait—"), ("SOUND", "*shake*"), ("BIRDSONG", "oh— ohhh—"), ("FIEND", "...good.")],
                [("BIRDSONG", "I was— I was right there—"), ("SOUND", "*wiggle*"), ("FIEND", "I know."), ("BIRDSONG", "...mean.")],
                [("BIRDSONG", "Don't stop— don't you dare—"), ("SOUND", "*pulse*"), ("FIEND", "...again.")],
            ],
            2: [
                [("BIRDSONG", "Fiend—! again—"), ("SOUND", "*shake*"), ("BIRDSONG", "I'm shaking—"), ("FIEND", "Stay with me.")],
                [("BIRDSONG", "I can't keep doing that—"), ("FIEND", "You can."), ("SOUND", "*wiggle*"), ("BIRDSONG", "...prove it.")],
                [("BIRDSONG", "No fair— no fair—"), ("SOUND", "*pulse*"), ("FIEND", "...one more.")],
            ],
        }
        scene_pool = {
            1: [
                [("SOUND", "*tremor*"), ("BIRDSONG", "Wait-- wait--"), ("FIEND", "Hold it."), ("BIRDSONG", "Ah... there.")],
                [("SOUND", "*wiggle*"), ("BIRDSONG", "You felt that."), ("FIEND", "I did."), ("BIRDSONG", "Then keep me there.")],
                [("SOUND", "*shiver*"), ("BIRDSONG", "No, no-- don't stop now--"), ("FIEND", "Breathe."), ("BIRDSONG", "Trying.")],
            ],
            2: [
                [("SOUND", "*shake*"), ("BIRDSONG", "Again-- Fiend, again--"), ("FIEND", "Stay with me."), ("BIRDSONG", "I am, I am.")],
                [("SOUND", "*pulse*"), ("BIRDSONG", "You are cruel."), ("FIEND", "Not yet."), ("BIRDSONG", "Then finish it properly.")],
                [("SOUND", "*tremor*"), ("BIRDSONG", "I cannot keep catching myself like that--"), ("FIEND", "One more climb."), ("BIRDSONG", "...fine.")],
            ],
        }
        result = self._play_scene(
            random.choice(scene_pool.get(int(stage), scene_pool[1])),
            "release_commit",
            f"her_climax_{stage}",
        )
        if result == "QUIT":
            return "QUIT"
        return "OK"

    def _spawn_final_release_particles(self, strength: int = 1) -> None:
        count = 18 + max(0, int(strength)) * 9
        for _ in range(count):
            self.sprites.particles.append(
                {
                    "x": 14.0 + random.uniform(-2.5, 2.5),
                    "y": 6.0 + random.uniform(-2.0, 1.2),
                    "vx": random.uniform(-7.5, 2.0),
                    "vy": random.uniform(-5.6, 1.4),
                    "gravity": -1.6,
                    "char": random.choice(["*", "+", "~", ".", "'"]),
                    "life": 0.70 + random.uniform(0.12, 0.42),
                }
            )

    def _play_final_release_impact(self, beat_idx: int) -> str:
        h, w = self.scr.getmaxyx()
        self._surge_pose_override = "angled_collapse"
        self._surge_pose_t = 0.95 if beat_idx < self._release_qte_hits_needed else 1.20
        try:
            self.lightmap_renderer.set_pose("angled_collapse")
        except Exception:
            pass
        self._spawn_final_release_particles(beat_idx)
        try:
            self.lightmap_renderer.trigger_flash(4 if beat_idx < 3 else 5, 0.28 + 0.04 * beat_idx)
            self.lightmap_renderer.trigger_shake(0.18 + 0.05 * beat_idx, 1.35 + 0.32 * beat_idx)
        except Exception:
            pass
        end_t = time.time() + (0.18 if beat_idx < self._release_qte_hits_needed else 0.24)
        self.scr.nodelay(True)
        while time.time() < end_t:
            dt = 0.033
            try:
                self.lightmap_renderer.update(dt, float(getattr(self.scene.rhythm, "intensity", 0.0)))
                self.sprites.update(dt)
                self.scene.particles.update(dt)
            except Exception:
                pass
            self.scr.erase()
            self.lightmap_renderer.render(
                self.scr,
                1,
                max(8, h - 16),
                w,
                float(getattr(self.scene.rhythm, "intensity", 0.0)),
            )
            _maybe_render_compact_sprites_debug(self.sprites, self.scr, max(10, h - 14), w)
            impact = f"EFFORT {beat_idx}/3" if self._bw_resistance_active() else f"IMPACT {beat_idx}/3"
            try:
                self.scr.addstr(h // 2 - 2, max(2, w // 2 - len(impact) // 2), impact, curses.color_pair(4) | curses.A_BOLD | curses.A_REVERSE)
            except Exception:
                pass
            self.scr.refresh()
            key = self.scr.getch()
            if key == 27:
                return "QUIT"
            time.sleep(0.033)
        return "OK"

    def _await_final_release_hit(self, beat_idx: int, timeout: float = 3.0) -> str:
        h, w = self.scr.getmaxyx()
        end_t = time.time() + max(0.6, float(timeout))
        self.scr.nodelay(True)
        self._release_qte_active = True
        while time.time() < end_t:
            dt = 0.033
            try:
                self.lightmap_renderer.update(dt, float(getattr(self.scene.rhythm, "intensity", 0.0)))
                self.sprites.update(dt)
                self.scene.particles.update(dt)
            except Exception:
                pass
            self.scr.erase()
            self.lightmap_renderer.render(
                self.scr,
                1,
                max(8, h - 16),
                w,
                float(getattr(self.scene.rhythm, "intensity", 0.0)),
            )
            _maybe_render_compact_sprites_debug(self.sprites, self.scr, max(10, h - 14), w)
            title = f"BRACE {beat_idx}/3" if self._bw_resistance_active() else f"FINAL RELEASE {beat_idx}/3"
            subtitle = "Press ENTER before pressure closes." if self._bw_resistance_active() else "Press ENTER before the impact breaks."
            remaining = max(0.0, end_t - time.time())
            timer_str = f"[ BRACE ]  {remaining:0.1f}s" if self._bw_resistance_active() else f"[ ENTER ]  {remaining:0.1f}s"
            attr = curses.color_pair(4) | curses.A_BOLD
            if int(time.time() * 6) % 2 == 0:
                attr |= curses.A_REVERSE
            try:
                self.scr.addstr(h // 2 - 3, max(2, w // 2 - len(title) // 2), title, attr)
                self.scr.addstr(h // 2 - 1, max(2, w // 2 - len(subtitle) // 2), subtitle, curses.color_pair(3))
                self.scr.addstr(h // 2 + 1, max(2, w // 2 - len(timer_str) // 2), timer_str, curses.color_pair(5) | curses.A_BOLD)
            except Exception:
                pass
            self.scr.refresh()
            key = self.scr.getch()
            if key == 27:
                self._release_qte_active = False
                return "QUIT"
            if key in (curses.KEY_ENTER, 10, 13):
                self._release_qte_hits = beat_idx
                return "HIT"
            time.sleep(0.033)
        return "FAIL"

    def _play_final_release_sequence(self) -> str:
        # Safety net: no blocking FINAL RELEASE sequence exists in endurance mode.
        # The only successful endpoint is the 03:00 timer in the outer session loop.
        if bool(getattr(self, "endurance_mode", False)):
            self._clear_release_commit_latch()
            self.round_state.release_charge = min(0.54, float(getattr(self.round_state, "release_charge", 0.0) or 0.0))
            self.pending_notifications.append("FINAL PRESSURE — KEEP PLAYING")
            return "DEFER"
        if self._bw_resistance_active():
            self._clear_release_commit_latch()
            self._release_qte_active=True
            self._release_qte_hits=self._release_qte_hits_needed
            return self._complete_release_qte()
        self._clear_release_commit_latch()
        self._release_qte_active = True
        self._release_qte_hits = 0
        self._release_qte_step_t = 3.0
        self._release_qte_total_t = 9.0
        self._surge_pose_override = "angled_collapse"
        self._surge_pose_t = 1.80
        try:
            self.lightmap_renderer.set_pose("angled_collapse")
        except Exception:
            pass
        self.sprites.trigger_surge("green")
        if self._bw_resistance_active():
            leadin = random.choice(
                [
                    [("NARRATION", "Hana braces."), ("NARRATION", "The ogre leans in."), ("NARRATION", "There is still a little distance.")],
                    [("NARRATION", "She finds leverage."), ("NARRATION", "Only for a breath."), ("NARRATION", "She uses it anyway.")],
                ]
            )
        else:
            leadin = random.choice(
                [
                    [("SOUND", "*stillness*"), ("BIRDSONG", "Do not lose it now."), ("FIEND", "...hold."), ("SOUND", "*tight shake*")],
                    [("SOUND", "*freeze*"), ("BIRDSONG", "If you mean it, finish."), ("FIEND", "Stay there."), ("SOUND", "*breath catches*")],
                ]
            )
        if self._play_scene(leadin, "final_release", "windup") == "QUIT":
            self._release_qte_active = False
            return "QUIT"
        if self._play_release_notice_hold(
            "STILL NOT ENOUGH" if self._bw_resistance_active() else "FINAL RELEASE",
            "She keeps trying." if self._bw_resistance_active() else "Freeze. Then strike.",
            duration=0.72,
            pulse_color=4,
            pose_override="angled_collapse",
        ) == "QUIT":
            self._release_qte_active = False
            return "QUIT"
        self.pending_notifications.append("She keeps trying." if self._bw_resistance_active() else "FINAL RELEASE")
        for beat_idx in range(1, self._release_qte_hits_needed + 1):
            wait_result = self._await_final_release_hit(beat_idx, timeout=3.0)
            if wait_result == "QUIT":
                return "QUIT"
            if wait_result != "HIT":
                self._fail_release_qte()
                return "FAIL"
            impact_result = self._play_final_release_impact(beat_idx)
            if impact_result == "QUIT":
                self._release_qte_active = False
                return "QUIT"
            self.pending_notifications.append(f"EFFORT {beat_idx}/3" if self._bw_resistance_active() else f"IMPACT {beat_idx}/3")
        return self._complete_release_qte()

    def _fail_release_qte(self) -> None:
        self._release_qte_active = False
        self._clear_release_commit_latch()
        self._release_qte_hits = 0
        self._release_qte_step_t = 0.0
        self._release_qte_total_t = 0.0
        self.round_state.release_charge = max(0.0, float(self.round_state.release_charge) - 0.55)
        self.round_state.momentum = max(-1.0, float(self.round_state.momentum) - 0.20)
        self.round_state.update_depth_from_reversal(False)
        self.reversal.trigger_availability("combo_break", 2.5)
        self.pending_notifications.append("Pressure returns." if self._bw_resistance_active() else "RELEASE LOST")

    def _complete_release_qte(self) -> str:
        relationship=getattr(self,"_courteous_relationship",None)
        if relationship is not None and not bool(getattr(relationship,"climax_ready",False)):
            self._clear_release_commit_latch()
            self._release_qte_active=False
            self._release_qte_hits=0
            self._release_qte_step_t=0.0
            self._release_qte_total_t=0.0
            self._release_commit_available=False
            self._release_commit_stage=0
            try:
                self.round_state.reset_release()
                self.round_state.surge_charge=0.0
                self.round_state.surge_tier=0
                self.round_state.surge_combo_streak=0
            except Exception:
                pass
            self.pending_notifications.append("FIEND HOLDS THE EDGE — THE CONVERSATION CONTINUES")
            return "OK"
        self._clear_release_commit_latch()
        self._last_conception_strength = max(
            0.0,
            min(
                1.0,
                (
                    float(getattr(self.round_state, "depth", 0.0))
                    + float(getattr(self.round_state, "her_pleasure", 0.0))
                    + (float(getattr(self.round_state, "momentum", 0.0)) + 1.0) * 0.5
                ) / 3.0,
            ),
        )
        self._release_qte_active = False
        self._release_qte_hits = 0
        self._release_qte_step_t = 0.0
        self._release_qte_total_t = 0.0
        self._release_commit_available = False
        self._release_commit_stage = 0
        self.round_state.climaxes_this_cycle += 1
        self.round_state.reset_release()
        self.round_state.surge_charge = 0.0
        self.round_state.surge_tier = 0
        self.round_state.surge_combo_streak = 0
        self.round_state.her_pleasure = min(1.0, float(self.round_state.her_pleasure) + 0.20)
        self.round_state.momentum = min(1.0, float(self.round_state.momentum) + 0.25)
        self.vibe.climax_reached = False
        self._session_climaxed = True
        self._reversal_life_on_loan = False
        self.profile.total_climaxes += 1
        self._escalate_cycle_tier("resistance" if self._bw_resistance_active() else "release")
        if self._bw_resistance_active():
            if self._autonomous_suggestive_idle():
                kind,heir=self._route_climax_kind("suggestive idle climax",success=True)
                self._terminal_climax_kind=kind
                self._terminal_climax_success=True
                self._terminal_climax_heir=bool(heir)
                self._black_wind_finale_outcome=("wrong_hole_success" if kind=="anal" else "intended_reproductive_redirect")
                result=self._play_climax_cutscene("intimate")
                self._hard_climax_session_complete=True
                return "QUIT" if result=="QUIT" else "SESSION_COMPLETE"
            self.pending_notifications.append("She kept trying.")
            result = self._play_release_notice_hold(
                "She kept trying.",
                "Pressure returns.",
                duration=0.82,
                pulse_color=4,
                pose_override="",
            )
            return "QUIT" if result == "QUIT" else "OK"
        self.pending_notifications.append("CLIMAX")
        result = self._play_climax_cutscene()
        if result == "QUIT":
            return "QUIT"
        if not self.tutorial_mode:
            try:
                on_climax(self.profile.achievement_progress)
            except Exception:
                pass
        # RELEASE BLOCKER FIX: the climax cutscene is the terminal payoff for
        # embedded wife/Bratbox sessions.  Returning ordinary OK allowed the
        # live intimacy loop to tick once more, spawn reversal/afterglow UI,
        # and sometimes freeze before the outer loop noticed _session_climaxed.
        self._hard_climax_session_complete = True
        try:
            self.reversal.active = False
            self.reversal.in_spike = False
            self.reversal.shield_active = False
        except Exception:
            pass
        try:
            self.sprites.pen_state = PenState.NORMAL
        except Exception:
            pass
        return "SESSION_COMPLETE"

    def _is_content_gated(self, content_type: str) -> bool:
        """Check if content is gated behind reversal tier."""
        gates = {
            "bathroom_scenes": 1,
            "hump_dog": 2,
            "edge_denial": 2,
            "love_bunny": 3,
            "starving_bunny": 3,
            "transcendence_rhythm": 3,
        }
        required_tier = gates.get(content_type, 0)
        return self.reversal.content_tier < required_tier

    # ═══════════════════════════════════════════════════════════════════════════════
    #              FAILURE STATE SYSTEM
    #              Real consequences for bad play - Bird takes over
    # ═══════════════════════════════════════════════════════════════════════════════

    def _check_failure_state(self) -> Optional[str]:
        """
        Check if Fiend has failed badly enough for Bird to take over.

        Failure conditions (any triggers takeover):
        - momentum < -0.5 (she's dominating)
        - power < -0.6 (she's fully in control)
        - 4+ slips this session
        - 3+ wrong holes this session
        - grip at 0 for 10+ seconds

        Returns: "takeover", "failure_end", or None
        """
        if getattr(self,"_courteous_relationship",None) is not None:
            return None
        # BRATBOX_UNBROKEN=1 (v10.10.2): forced exits are disarmed — the night
        # never ends early. Total collapse demotes to a takeover (she takes
        # over, rhythm continues underneath) instead of "failure_end".
        _unbroken = _unbroken_rhythm()
        if int(getattr(self.round_state, "cycle_lives", 0) or 0) <= 0:
            return "takeover" if _unbroken else "failure_end"

        momentum = self.round_state.momentum
        power = self.round_state.power_dynamic
        slips = self.round_state.recent_slips
        wrong_holes = self.round_state.recent_wrong_holes

        # Track failure severity
        failure_score = 0

        if momentum < -0.5:
            failure_score += 2
        elif momentum < -0.3:
            failure_score += 1

        if power < -0.6:
            failure_score += 2
        elif power < -0.4:
            failure_score += 1

        if slips >= 4:
            failure_score += 2
        elif slips >= 2:
            failure_score += 1

        if wrong_holes >= 3:
            failure_score += 2
        elif wrong_holes >= 1:
            failure_score += 1

        # Check grip death
        grip_death = False
        if self.sprites.grip <= 0:
            grip_zero_time = getattr(self, '_grip_zero_timer', 0)
            grip_zero_time += 0.016  # Approximate frame time
            self._grip_zero_timer = grip_zero_time
            if grip_zero_time > 10.0:
                grip_death = True
                failure_score += 3
        else:
            self._grip_zero_timer = 0

        # Thresholds
        if grip_death:
            # v10.10.2: unbroken mode never hard-exits; demote to takeover.
            return "takeover" if _unbroken_rhythm() else "failure_end"
        if failure_score >= 3:
            return "takeover"  # Bird takes over but continues

        return None

    def _trigger_bird_takeover(self) -> str:
        """
        Bird takes control from Fiend.

        Can lead to:
        - Facesitting (if trust_control >= 60)
        - Watersports lead-in (if trust_vulnerability >= 75)
        - Just her on top (default)
        """
        # Play warning first time, takeover on subsequent
        takeover_count = getattr(self, '_takeover_count', 0)

        if takeover_count == 0:
            # First warning
            scene = random.choice(BIRD_TAKEOVER_DIALOGUE["mild"])
            self._takeover_count = 1
        else:
            # Actual takeover
            scene = random.choice(BIRD_TAKEOVER_DIALOGUE["takeover"])
            self._takeover_count += 1

            # Power shift - she's in control now
            self.round_state.shift_power(-0.4, "bird_takeover")
            self.round_state.momentum = max(-1.0, self.round_state.momentum - 0.3)

        if self._play_scene(scene, "bird_takeover") == "QUIT":
            return "QUIT"

        # ═══════════════════════════════════════════════════════════════════
        # TAKEOVER LOOP GUARD
        #
        # Without a guard, the failure check can immediately re-trigger takeover
        # after a dialogue pause/unpause, causing the player to get stuck in a
        # "you suck" loop (e.g. "...lie down." / "Since you can't seem to...perform...").
        # We set a short lockout so gameplay has time to resume and the player
        # can actually recover.
        # ═══════════════════════════════════════════════════════════════════
        self._takeover_lockout = max(getattr(self, '_takeover_lockout', 0.0), 10.0)
        # Also gate escalation followups so they don't stack instantly.
        self._takeover_escalation_lockout = max(getattr(self, '_takeover_escalation_lockout', 0.0), 6.0)

        # Check for escalation based on trust unlocks
        if takeover_count >= 1:  # After first takeover
            # Don't escalate immediately after coming back from dialogue.
            if getattr(self, '_takeover_escalation_lockout', 0.0) > 0.0:
                return "OK"

            # Facesitting lead-in (consent gated)
            if self.trust.unlocked_facesitting and random.random() < 0.35:
                return self._trigger_facesitting_leadin()

            # Watersports lead-in (consent gated, rarer)
            if self.trust.unlocked_watersports and random.random() < 0.2:
                return self._trigger_watersports_leadin()

        return "OK"

    def _trigger_facesitting_leadin(self) -> str:
        """Facesitting lead-in when Bird takes over."""
        scene = random.choice(BIRD_TAKEOVER_DIALOGUE["facesitting_leadin"])

        if self._play_scene(scene, "facesitting_leadin") == "QUIT":
            return "QUIT"

        # Trust/kink updates
        self.trust.add_trust("control", 10)
        self.trust.record_kink("facesitting", 20)

        # Record to cascade
        if hasattr(self, 'cascade'):
            ctx = self.cascade.snapshot_context(
                self.round_state, self.session_state, self.vibe,
                self.scene.rhythm if self.scene else None
            )
            self.cascade.record_choice("facesitting_leadin", ["control", "bird_dom"], ctx)

        # Pose change
        self.lightmap_renderer.set_pose("face", instant=False)

        # Her pleasure spikes (she's getting what she wants)
        self.round_state.her_pleasure = min(1.0, self.round_state.her_pleasure + 0.15)

        self.pending_notifications.append("🦅 BIRD TAKES CONTROL")

        return "OK"

    def _trigger_watersports_leadin(self) -> str:
        """Watersports lead-in when Bird takes over. Rare, consent gated."""
        scene = random.choice(BIRD_TAKEOVER_DIALOGUE["watersports_leadin"])

        if self._play_scene(scene, "watersports_leadin") == "QUIT":
            return "QUIT"

        # Trust/kink updates
        self.trust.add_trust("vulnerability", 15)
        self.trust.record_kink("watersports", 25)

        # Record to cascade
        if hasattr(self, 'cascade'):
            ctx = self.cascade.snapshot_context(
                self.round_state, self.session_state, self.vibe,
                self.scene.rhythm if self.scene else None
            )
            self.cascade.record_choice("watersports_leadin", ["vulnerability", "marking"], ctx)

        self.pending_notifications.append("💦 SHE MARKS HER TERRITORY")

        return "OK"

    def _trigger_failure_ending(self) -> str:
        if self._route_terminal_once(
            "failure ending", success=False, post_action="failure_end"
        ):
            return "OK"
        """
        Round ends due to too many failures.
        Not game over - just this round ends with her comforting him.
        """
        scene = random.choice(FAILURE_ENDING_DIALOGUE)

        if self._play_scene(scene, "failure_ending") == "QUIT":
            return "QUIT"

        # Set undulation to tender
        self.lightmap_renderer.set_undulation_profile("calm")

        # Record to cascade
        if hasattr(self, 'cascade'):
            ctx = self.cascade.snapshot_context(
                self.round_state, self.session_state, self.vibe,
                self.scene.rhythm if self.scene else None
            )
            self.cascade.record_choice("failure_ending", ["failure", "comfort"], ctx)

        # This ends the rhythm section but not the session
        self.vibe.cycles_completed += 1
        self.round_state.tier = 0  # Reset tier

        return "FAILURE_END"


    def _handle_his_early_climax(self) -> str:
        """Handle Fiend peaking before Birdsong."""
        if bool(getattr(self, "endurance_mode", False)) or _unbroken_rhythm():
            # No modal choice. It is now pressure inside the flow:
            # his turn can wait, the rhythm doesn't. (v10.8: unbroken mode
            # takes the same non-modal consequence as endurance — the old
            # slapstick scene + choice menu was a modal interruption.)
            self.round_state.his_pleasure = 0.72
            self.round_state.momentum = max(-1.0, float(getattr(self.round_state, "momentum", 0.0) or 0.0) - 0.08)
            self.pending_notifications.append("PRE-CLIMAX — CONTROL NARROWS")
            self._endurance_threshold_notice_until = time.perf_counter() + 2.0
            return "OK"
        # ═══════════════════════════════════════════════════════════════════
        # DRAMATIC EFFECTS - He's losing control
        # ═══════════════════════════════════════════════════════════════════
        self.lightmap_renderer.trigger_shake(0.5, 3.0)
        self.lightmap_renderer.trigger_flash(5, 0.3)  # Magenta flash
        self.animation_engine.trigger_reaction("startle")

        # Play trigger scene
        if self._play_slapstick_scene(random.choice(HIS_CLIMAX_EARLY_TRIGGER)) == "QUIT":
            return "QUIT"

        # 2026-09-25 (birdsong build): rhythm-only never stops for a modal
        # choice. Auto-pick "keep_going" — the option that doesn't pause.
        if _unbroken_rhythm():
            choice_id = "keep_going"
            self.animation_engine.trigger_reaction("idea")
            if self._play_slapstick_scene(random.choice(HIS_CLIMAX_KEEP_GOING)) == "QUIT":
                return "QUIT"
            return "OK"

        # Present choice with animated lightmap
        h, w = self.scr.getmaxyx()
        cx = w // 2

        options = [
            ("Keep going", "keep_going", "Push through - your turn can wait"),
            ("Let her finish you", "let_her_finish_you", "Surrender control to her"),
            ("Rest together", "rest_together", "Tender pause - there's no rush"),
        ]

        lightmap_bottom = h - 15

        selected = 0
        last_render = 0
        while True:
            now = time.time()

            # Render at ~30fps
            if now - last_render > 0.033:
                last_render = now
                self.scr.erase()

                # Animated lightmap
                try:
                    self.lightmap_renderer.update(0.033, 80)  # High intensity
                    self.lightmap_renderer.render(self.scr, 1, lightmap_bottom, w, 80)
                except:
                    pass

                try:
                    self.scr.addstr(lightmap_bottom + 2, cx - 10, "He's close. Too close.", curses.color_pair(5) | curses.A_BOLD)
                    self.scr.addstr(lightmap_bottom + 3, cx - 8, "What does he do?", curses.A_DIM)
                except: pass

                for i, (text, _, hint) in enumerate(options):
                    y = lightmap_bottom + 5 + i * 2
                    if i == selected:
                        marker = "▶ "
                        color = curses.color_pair(4) | curses.A_BOLD
                    else:
                        marker = "  "
                        color = curses.A_DIM

                    try:
                        self.scr.addstr(y, cx - 15, f"{marker}{text}", color)
                        if i == selected:
                            self.scr.addstr(y + 1, cx - 12, f"  {hint}", curses.A_DIM)
                    except: pass

                self.scr.refresh()

            self.scr.nodelay(True)
            key = self.scr.getch()

            if key in (curses.KEY_UP, ord('w'), ord('W')):
                selected = (selected - 1) % len(options)
            elif key in (curses.KEY_DOWN, ord('s'), ord('S')):
                selected = (selected + 1) % len(options)
            elif key in (curses.KEY_ENTER, 10, 13, ord(' ')):
                break
            elif key == 27:
                return "QUIT"

            time.sleep(0.016)

        choice_id = options[selected][1]

        # Apply consequences
        unlocked, notifications = apply_choice_consequence(
            "his_climax_early",
            choice_id,
            self.round_state,
            self.session_state,
            self.trust
        )

        self.pending_notifications.extend(notifications)

        # Play response scene with reaction
        if choice_id == "keep_going":
            self.animation_engine.trigger_reaction("idea")  # Determination
            if self._play_slapstick_scene(random.choice(HIS_CLIMAX_KEEP_GOING)) == "QUIT":
                return "QUIT"
        elif choice_id == "let_her_finish_you":
            self.animation_engine.trigger_compound("surprised_look_away")
            if self._play_slapstick_scene(random.choice(HIS_CLIMAX_SURRENDER)) == "QUIT":
                return "QUIT"
        else:  # rest_together
            self.animation_engine.trigger_reaction("slump")
            if self._play_slapstick_scene(random.choice(HIS_CLIMAX_REST)) == "QUIT":
                return "QUIT"

        return "OK"

    def _show_notification(self, text: str, duration: float = 1.5):
        """Show a notification overlay."""
        h, w = self.scr.getmaxyx()
        cx = w // 2

        # Draw notification box
        box_w = len(text) + 4
        box_x = cx - box_w // 2

        try:
            self.scr.addstr(h//3, box_x, "┌" + "─" * (box_w - 2) + "┐", curses.color_pair(4))
            self.scr.addstr(h//3 + 1, box_x, "│ " + text + " │", curses.color_pair(4) | curses.A_BOLD)
            self.scr.addstr(h//3 + 2, box_x, "└" + "─" * (box_w - 2) + "┘", curses.color_pair(4))
        except: pass

        self.scr.refresh()
        time.sleep_slow(duration)

    def _get_mode_interlude(self) -> List:
        """Get interlude based on current mode"""
        # Special modes should strongly prefer their own scene pools
        if self.current_mode == "love_bunny":
            return self._pick_unused(LOVE_BUNNY_INTERLUDES, "love_bunny")
        if self.current_mode == "starving":
            return self._pick_unused(STARVING_INTERLUDES, "starving")
        if self.current_mode == "hump_dog":
            return self._pick_unused(HUMP_DOG_INTERLUDES, "hump_dog")
        if self.current_mode == "edge":
            return self._pick_unused(EDGE_INTERLUDES, "edge")

        # 30% chance of story snippet (full comedy scene)
        if random.random() < 0.30:
            return get_random_story_snippet()

        # Pillow talk is a little rarer and only after the first cycle
        if random.random() < 0.25 and self.vibe.cycles_completed > 0:
            return self._pick_unused(PILLOW_TALK, "pillow")

        pools = {
            "gentle": GENTLE_INTERLUDES,
            "steady": STEADY_INTERLUDES,
            "rough": ROUGH_INTERLUDES,
        }
        return self._pick_unused(pools.get(self.current_mode, GENTLE_INTERLUDES), self.current_mode)

