    def _play_climax_shake(self, intensity: int):
        """SLAPSTICK: Screen shake effect - the more intense, the wilder."""
        h, w = self.scr.getmaxyx()
        lightmap_bottom = h - 10

        duration = 0.15 + intensity * 0.05
        shake_amp = intensity * 0.8

        start = time.time()
        while time.time() - start < duration:
            self.scr.erase()

            # Calculate shake offset
            elapsed = time.time() - start
            shake_x = int(math.sin(elapsed * 40) * shake_amp * (1 - elapsed / duration))
            shake_y = int(math.cos(elapsed * 35) * shake_amp * 0.5 * (1 - elapsed / duration))

            try:
                # Apply shake to render position
                self.lightmap_renderer.update(0.02, 90)
                # Offset the entire render
                for row in range(1, lightmap_bottom):
                    try:
                        self.scr.move(row, max(0, shake_x))
                    except:
                        pass
                self.lightmap_renderer.render(self.scr, 1 + shake_y, lightmap_bottom + shake_y, w, 90)
            except:
                pass

            self.scr.refresh()
            time.sleep(0.008)

    def _play_climax_bounce(self, intensity: int):
        """SLAPSTICK: Spring bounce effect - cartoon physics."""
        h, w = self.scr.getmaxyx()
        lightmap_bottom = h - 10

        duration = 0.2 + intensity * 0.1
        bounce_height = intensity * 2

        start = time.time()
        while time.time() - start < duration:
            self.scr.erase()

            # Bouncy spring physics
            elapsed = time.time() - start
            progress = elapsed / duration

            # Damped oscillation
            bounce = abs(math.sin(progress * math.pi * 3)) * bounce_height * (1 - progress)

            try:
                self.lightmap_renderer.update(0.02, 85)
                # Bounce UP (negative Y)
                self.lightmap_renderer.render(self.scr, int(1 - bounce), int(lightmap_bottom - bounce), w, 85)
            except:
                pass

            self.scr.refresh()
            time.sleep(0.008)

    def _play_climax_wiggle(self, duration: float):
        """SLAPSTICK: Post-climax wiggle/twitch animation."""
        h, w = self.scr.getmaxyx()
        lightmap_bottom = h - 10

        start = time.time()
        while time.time() - start < duration * 0.3:  # Quick wiggles
            self.scr.erase()

            elapsed = time.time() - start

            # Rapid horizontal wiggle
            wiggle_x = int(math.sin(elapsed * 30) * 3 * (1 - elapsed / (duration * 0.3)))

            try:
                self.lightmap_renderer.update(0.02, 80)
                # Hacky offset via cursor
                self.lightmap_renderer.render(self.scr, 1, lightmap_bottom, w + wiggle_x, 80)
            except:
                pass

            self.scr.refresh()
            time.sleep(0.008)

    def _play_climax_flash(self, color: str):
        """SLAPSTICK: Screen flash effect."""
        h, w = self.scr.getmaxyx()

        # Determine flash color
        if color == "white":
            flash_pair = curses.color_pair(4) | curses.A_BOLD
        elif color == "pink":
            flash_pair = curses.color_pair(5) | curses.A_BOLD
        else:
            flash_pair = curses.A_REVERSE

        # Quick flash
        self.scr.erase()
        try:
            for row in range(h - 1):
                self.scr.addstr(row, 0, " " * (w - 1), flash_pair)
        except:
            pass
        self.scr.refresh()
        time.sleep(0.08)

        # Flash out
        self.scr.erase()
        self.scr.refresh()
        time.sleep(0.012)

    def _play_climax_narration(self, text: str):
        """SLAPSTICK: Dramatic narration with impact."""
        h, w = self.scr.getmaxyx()
        cx = w // 2
        lightmap_bottom = h - 10

        # Quick shake before narration
        self._play_climax_shake(2)

        # Display narration with weight
        start = time.time()
        while time.time() - start < 1.2:
            self.scr.erase()

            try:
                self.lightmap_renderer.update(0.033, 85)
                self.lightmap_renderer.render(self.scr, 1, lightmap_bottom, w, 85)

                # Centered narration
                self.scr.addstr(h - 6, cx - len(text) // 2, text, curses.A_BOLD | curses.A_DIM)
            except:
                pass

            self.scr.refresh()
            time.sleep(0.033)
        for speaker, content in scene:
            if speaker == "SILENCE":
                duration = content if isinstance(content, (int, float)) else 1.5
                self._play_climax_silence(duration)
            else:
                self._play_climax_line(speaker, content, climax_type)

        # ═══════════════════════════════════════════════════════════════════════
        # CASCADE RECORDING - Major event
        # ═══════════════════════════════════════════════════════════════════════
        if hasattr(self, 'cascade'):
            ctx = self.cascade.snapshot_context(
                self.round_state, self.session_state, self.vibe,
                self.scene.rhythm if self.scene else None
            )
            self.cascade.record_line(
                speaker="CLIMAX",
                text=climax_type,
                trigger_type="climax_cutscene",
                trigger_source=f"climax_{climax_type}",
                context=ctx
            )

        # Restore normal undulation after climax
        # (Let normal gameplay intensity drive the profile again)
        self.lightmap_renderer.set_undulation_profile("release")

        return "OK"

    def _play_climax_line(self, speaker: str, content: str, climax_type: str):
        """
        SLAPSTICK: Fast, punchy dialogue display.
        Quick typewriter, short holds, keep momentum.
        """
        h, w = self.scr.getmaxyx()
        cx = w // 2

        # Determine styling
        if speaker == "FIEND":
            color = curses.color_pair(1) | curses.A_BOLD
            x = cx - len(content) - 5
        elif speaker == "BIRDSONG":
            # During climax, her text is URGENT
            if "!" in content or content.isupper():
                color = curses.color_pair(5) | curses.A_BOLD | curses.A_REVERSE
            else:
                color = curses.color_pair(2) | curses.A_BOLD
            x = cx + 5
        else:
            color = curses.A_DIM
            x = cx - len(content) // 2

        x = max(2, min(x, w - len(content) - 2))

        display = f'"{content}"' if speaker in ("FIEND", "BIRDSONG") else content
        # CLIMAX_VOICE_HOOK_V1: voice climax dialogue lines (BIRDSONG/FIEND) once per line
        try:
            if speaker in ("BIRDSONG", "FIEND"):
                self._voice_any_line(speaker, content)
        except Exception:
            pass   # no audio — display line silently

        lightmap_bottom = h - 10
        dialogue_y = h - 6
        # LOCKKEY_SUBTITLE_SYNC: render older active subtitles above the current line
        try:
            active = getattr(self, "_subtitle_sync_active", None) or []
            if getattr(self, "_subtitle_sync_mode", False) and active:
                # We'll render up to N active lines (oldest->newest), newest uses the typewriter below.
                base_y = dialogue_y - (len(active) - 1)
                base_y = max(2, base_y)
                for j, (_exp, sp, tx) in enumerate(active[:-1]):
                    # style per speaker
                    if sp == "FIEND":
                        col2 = curses.color_pair(1) | curses.A_BOLD
                        disp2 = f'"{tx}"'
                    elif sp == "BIRDSONG":
                        col2 = curses.color_pair(2)
                        disp2 = f'"{tx}"'
                    elif sp == "SOUND":
                        col2 = curses.color_pair(3) | curses.A_DIM
                        disp2 = tx
                    else:
                        col2 = curses.A_DIM
                        disp2 = tx
                    y2 = base_y + j
                    x2 = max(2, min(cx - len(disp2)//2, w - len(disp2) - 2))
                    try:
                        self.scr.addstr(y2, x2, disp2, col2)
                    except Exception:
                        pass
                # move current line down so it doesn't overwrite older ones
                dialogue_y = base_y + (len(active) - 1)
        except Exception:
            pass


        # FAST typewriter - 0.02s per char (was 0.04)
        for i in range(len(display) + 1):
            self.scr.erase()
            try:
                self.lightmap_renderer.update(0.02, 90)
                self.lightmap_renderer.render(self.scr, 1, lightmap_bottom, w, 90)
                self.scr.addstr(dialogue_y, x, display[:i], color)
            except:
                pass
            self.scr.refresh()
            time.sleep(0.008)

        # SHORT hold - 0.3s base (was 0.8s)
        hold_time = 0.3 + len(content) * 0.01
        if "!" in content:
            hold_time *= 0.8  # Exclamations are FAST

        start = time.time()
        while time.time() - start < hold_time:
            self.scr.erase()
            try:
                self.lightmap_renderer.update(0.02, 90)
                self.lightmap_renderer.render(self.scr, 1, lightmap_bottom, w, 90)
                if display:
                    self.scr.addstr(dialogue_y, x, display, color)
            except:
                pass
            self.scr.refresh()
            time.sleep(0.008)

    def _play_climax_silence(self, duration: float):
        """
        SLAPSTICK: Quick breathing pause between impacts.
        Max 0.5 seconds - keeps momentum going.
        """
        h, w = self.scr.getmaxyx()
        lightmap_bottom = h - 10

        # Cap duration for slapstick pacing
        duration = min(duration, 0.5)

        start = time.time()
        while time.time() - start < duration:
            self.scr.erase()
            try:
                self.lightmap_renderer.update(0.02, 90)
                self.lightmap_renderer.render(self.scr, 1, lightmap_bottom, w, 90)
            except:
                pass
            self.scr.refresh()
            time.sleep(0.008)

