    def _play_slapstick_scene(self, scene: List, trigger_type: str = "slapstick") -> str:
        """
        Play a scene with slapstick effects mixed in.

        STORY-IN-RHYTHM V2 (2026-09-25): Non-modal. Dialogue queues through
        dialogue_commit. Slapstick effects become queued SOUND lines + non-blocking
        animation triggers instead of screen-erasing blocking loops. Notes never stop.

        Handles special tags:
        - ("MOUNT", n)    - Awkward mounting attempt
        - ("HOP", n)      - Love hops! Bouncy animal energy
        - ("STRETCH", n)  - Cartoon stretch effect
        - ("YIP", n)      - Quick excited noise burst
        - ("NUZZLE", dir) - Head bump animation
        - ("GROWL", n)    - Low rumble, screen vibrate
        - ("SMACK", n)    - Playful hit with bounce
        - ("OWO", face)   - Face change display
        - ("WIGGLE", n)   - Butt wiggle (her)
        - ("HUFF", n)     - Breath puff visual

        Normal dialogue tags queued via dialogue_commit.
        """
        # STORY-IN-RHYTHM: no input flush (was modal).

        # Map slapstick tags to (sound_text, animation_trigger)
        _slapstick_map = {
            "MOUNT": ("*bump* *wobble*", "wobble"),
            "HOP": ("*boing* *boing*", "hop"),
            "STRETCH": ("*sproing*", "stretch"),
            "YIP": ("*yip!*", "excited"),
            "NUZZLE": ("*nuzzle*", "nuzzle"),
            "GROWL": ("*grrr*", "growl"),
            "SMACK": ("*smack!*", "smack"),
            "OWO": ("*owo*", "surprised"),
            "WIGGLE": ("*wiggle*", "wiggle"),
            "HUFF": ("*huff*", "huff"),
        }

        for item in scene:
            if len(item) == 2 and item[0] in _slapstick_map:
                # Slapstick effect: non-blocking animation + queued sound line
                tag, value = item
                sound_text, anim = _slapstick_map[tag]
                # Trigger animation (non-blocking, best-effort)
                try:
                    if hasattr(self, 'animation_engine') and self.animation_engine:
                        self.animation_engine.trigger_reaction(anim)
                except Exception:
                    pass
                # Queue the sound as a subtitle (non-blocking)
                try:
                    self.dialogue_commit("SOUND", sound_text, ttl=1.0)
                except Exception:
                    pass
            else:
                # Normal dialogue: queue non-blocking
                speaker, content = item[0], item[1]
                try:
                    result = self.dialogue_commit(speaker, content)
                    # Legacy QUIT signal no longer applies in non-modal flow
                except Exception:
                    pass

        return "OK"

    def _slapstick_mount(self, intensity: int):
        """SLAPSTICK: Awkward mounting attempt - wobble, bump, adjust."""
        h, w = self.scr.getmaxyx()
        lightmap_bottom = h - 10

        duration = 0.2 + intensity * 0.1

        start = time.time()
        while time.time() - start < duration:
            self.scr.erase()
            elapsed = time.time() - start

            # Wobble back and forth
            wobble_x = int(math.sin(elapsed * 15) * intensity)
            wobble_y = int(abs(math.sin(elapsed * 10)) * (intensity * 0.5))

            try:
                self.lightmap_renderer.update(0.02, 70)
                # Apply wobble
                self.lightmap_renderer.render(self.scr, 1 + wobble_y, lightmap_bottom + wobble_y, w, 70)

                # Show *bump* text
                if int(elapsed * 10) % 3 == 0:
                    self.scr.addstr(h - 5, w // 2 - 3, "*bump*", curses.A_DIM)
            except:
                pass

            self.scr.refresh()
            time.sleep(0.008)

    def _slapstick_hop(self, intensity: int):
        """SLAPSTICK: Love hops! Bouncy happy animal energy."""
        h, w = self.scr.getmaxyx()
        lightmap_bottom = h - 10

        # Quick hop up and down
        hop_count = min(intensity, 3)

        for i in range(hop_count):
            # Up
            for frame in range(4):
                self.scr.erase()
                hop_y = -frame if frame < 2 else -(3 - frame)
                try:
                    self.lightmap_renderer.update(0.02, 60 + intensity * 5)
                    self.lightmap_renderer.render(self.scr, 1 + hop_y, lightmap_bottom + hop_y, w, 60)
                except:
                    pass
                self.scr.refresh()
                time.sleep(0.012)

    def _slapstick_stretch(self, intensity: int):
        """SLAPSTICK: Cartoon stretch effect - zoom toward something."""
        h, w = self.scr.getmaxyx()
        lightmap_bottom = h - 10

        duration = 0.15 * intensity

        start = time.time()
        while time.time() - start < duration:
            self.scr.erase()
            elapsed = time.time() - start
            progress = elapsed / duration

            # Stretch forward effect (lean)
            stretch = int(progress * intensity * 2)

            try:
                self.lightmap_renderer.update(0.02, 70)
                # Shift render position
                self.lightmap_renderer.render(self.scr, 1, lightmap_bottom, w, 70)

                # Show stretch lines
                if intensity >= 2:
                    for i in range(min(stretch, 3)):
                        self.scr.addstr(h // 2 - i, w // 2 + 5 + i, "->", curses.A_DIM)
            except:
                pass

            self.scr.refresh()
            time.sleep(0.008)

        # Snap back
        self._slapstick_hop(1)

