    def _slapstick_nuzzle(self, direction: str):
        """SLAPSTICK: Head bump animation - affectionate nudge."""
        h, w = self.scr.getmaxyx()
        lightmap_bottom = h - 10

        # Direction determines offset
        if direction == "left":
            offset_x, offset_y = -2, 0
        elif direction == "right":
            offset_x, offset_y = 2, 0
        elif direction == "up":
            offset_x, offset_y = 0, -1
        elif direction == "down":
            offset_x, offset_y = 0, 1
        else:  # forward
            offset_x, offset_y = 1, 0

        # Nudge animation
        for frame in range(6):
            self.scr.erase()
            if frame < 3:
                ox = int(offset_x * (frame / 2))
                oy = int(offset_y * (frame / 2))
            else:
                ox = int(offset_x * ((5 - frame) / 2))
                oy = int(offset_y * ((5 - frame) / 2))

            try:
                self.lightmap_renderer.update(0.02, 50)
                self.lightmap_renderer.render(self.scr, 1 + oy, lightmap_bottom + oy, w, 50)

                # Show *nuzzle* at peak
                if frame == 2:
                    self.scr.addstr(h - 5, w // 2 - 4, "*nuzzle*", curses.color_pair(2) | curses.A_DIM)
            except:
                pass

            self.scr.refresh()
            time.sleep(0.04)

    def _slapstick_growl(self, intensity: int):
        """SLAPSTICK: Low rumble - screen vibrate, menacing but playful."""
        h, w = self.scr.getmaxyx()
        lightmap_bottom = h - 10

        duration = 0.15 + intensity * 0.1

        start = time.time()
        while time.time() - start < duration:
            self.scr.erase()
            elapsed = time.time() - start

            # Rapid micro-shake
            shake_x = random.choice([-1, 0, 1]) if intensity >= 2 else 0
            shake_y = random.choice([-1, 0]) if intensity >= 3 else 0

            try:
                self.lightmap_renderer.update(0.02, 65)
                self.lightmap_renderer.render(self.scr, 1 + shake_y, lightmap_bottom + shake_y, w, 65)

                # Show growl text
                growl_text = "grr" + "r" * min(intensity, 4) + "..."
                self.scr.addstr(h - 5, w // 2 - len(growl_text) // 2, growl_text,
                               curses.color_pair(1) | curses.A_BOLD)
            except:
                pass

            self.scr.refresh()
            time.sleep(0.008)

