    def _rhythm_note_is_actionable(self, note) -> bool:
        """True only for a real note the player can still see and hit."""
        try:
            if bool(getattr(note, "decoy", False)):
                return False
            if bool(getattr(note, "hit", False)) or bool(getattr(note, "missed", False)):
                return False
            y=float(getattr(note, "y_pos", -99.0))
            # Rhythm notes are normalized from the highway top (0) through the
            # hit/miss zone (~1).  Objects outside this range must not satisfy
            # the dry-spell watchdog merely by remaining in the list.
            return -0.08 <= y <= 1.18
        except Exception:
            return False

    def _rhythm_rearm_note(self, note, rhythm, target_y: float = 0.04) -> bool:
        """Turn an existing/native note object into a clean visible note."""
        try:
            lanes=list(Lane)
        except Exception:
            lanes=[]
        try:
            if lanes:
                note.lane=random.choice(lanes)
        except Exception:
            pass
        for field_name, value in (("hit",False),("missed",False),("decoy",False),("expired",False),("removed",False),("active",True)):
            try:
                if hasattr(note,field_name) or field_name in ("hit","missed","decoy"):
                    setattr(note,field_name,value)
            except Exception:
                pass
        try:
            if hasattr(note,"fall_mult") and float(getattr(note,"fall_mult",1.0) or 1.0)<=0.0:
                note.fall_mult=1.0
        except Exception:
            pass
        try:
            self._rephase_rhythm_note(note,float(target_y))
        except Exception:
            try:
                note.y_pos=float(target_y)
                note.spawn_time=float(getattr(rhythm,"time",0.0))
            except Exception:
                return False
        return self._rhythm_note_is_actionable(note)

    def _rhythm_construct_emergency_note(self, rhythm) -> int:
        """Last-resort native-class construction for a truly empty rhythm list."""
        try:
            import importlib, inspect
            mod=importlib.import_module(str(rhythm.__class__.__module__))
        except Exception:
            return 0
        try:
            lanes=list(Lane)
            lane=random.choice(lanes) if lanes else None
        except Exception:
            lane=None
        now=float(getattr(rhythm,"time",0.0) or 0.0)
        candidates=[]
        for name in ("Note","RhythmNote","FallingNote","BeatNote"):
            cls=getattr(mod,name,None)
            if isinstance(cls,type):
                candidates.append(cls)
        for cls in candidates:
            attempts=[
                ((),{}),
                ((lane,),{}) if lane is not None else ((),{}),
                ((lane,now),{}) if lane is not None else ((),{}),
                ((),{"lane":lane}) if lane is not None else ((),{}),
                ((),{"lane":lane,"spawn_time":now}) if lane is not None else ((),{}),
                ((),{"lane":lane,"y_pos":0.04,"spawn_time":now}) if lane is not None else ((),{}),
            ]
            for args,kwargs in attempts:
                try:
                    note=cls(*args,**kwargs)
                    if not self._rhythm_rearm_note(note,rhythm,0.04):
                        continue
                    rhythm.notes.append(note)
                    return 1
                except Exception:
                    continue
        return 0

    def _rhythm_force_note_spawn(self, reason: str = "dry_spell") -> int:
        """Guarantee a visible actionable note, not merely a nonempty notes list."""
        rhythm=getattr(getattr(self,"scene",None),"rhythm",None)
        if rhythm is None:
            return 0
        try:
            rhythm.notes=list(getattr(rhythm,"notes",[]) or [])
        except Exception:
            return 0
        before_ids={id(n) for n in rhythm.notes}
        try: rhythm.spawn_suppressed=False
        except Exception: pass
        for pause_name in ("paused","is_paused","suspended","freeze_spawns","notes_disabled"):
            try:
                if hasattr(rhythm,pause_name): setattr(rhythm,pause_name,False)
            except Exception:
                pass
        try:
            lanes=list(Lane)
        except Exception:
            lanes=[]
        native_names=("force_spawn_note","spawn_note","_spawn_note","force_note","inject_note","add_note")
        for name in native_names:
            fn=getattr(rhythm,name,None)
            if not callable(fn):
                continue
            attempts=[(),(random.choice(lanes),) if lanes else (), ("center",), (0,)]
            for args in attempts:
                try:
                    fn(*args)
                except TypeError:
                    continue
                except Exception:
                    break
                fresh=[n for n in list(getattr(rhythm,"notes",[]) or []) if id(n) not in before_ids]
                for note in fresh:
                    if self._rhythm_rearm_note(note,rhythm,0.04):
                        return 1
        # Expire every known spawn clock and advance the native director.
        for field_name in ("spawn_timer","note_spawn_timer","next_spawn","next_note_time",
                           "time_to_next_note","spawn_cooldown","_spawn_timer","_next_spawn",
                           "last_spawn_time","_last_spawn_time"):
            try:
                if hasattr(rhythm,field_name):
                    setattr(rhythm,field_name,(-999.0 if "last" in field_name else 0.0))
            except Exception:
                pass
        update=getattr(rhythm,"update",None)
        if callable(update):
            for _ in range(12):
                try: update(0.20)
                except Exception: break
                fresh=[n for n in list(getattr(rhythm,"notes",[]) or []) if id(n) not in before_ids]
                for note in fresh:
                    if self._rhythm_rearm_note(note,rhythm,0.04):
                        return 1
        # The common failure is a stale internal object fooling the old watchdog.
        # Recycle one native object before attempting reflective construction.
        notes=list(getattr(rhythm,"notes",[]) or [])
        if notes:
            note=next((n for n in notes if not bool(getattr(n,"decoy",False))),notes[0])
            try:
                rhythm.notes=[note]
            except Exception:
                pass
            if self._rhythm_rearm_note(note,rhythm,0.04):
                return 1
        return self._rhythm_construct_emergency_note(rhythm)

    def _rhythm_reset_full_pattern(self, reason: str = "dry_spell") -> int:
        """Replace a stalled native note director while preserving play progress.

        Clearing ``notes`` alone leaves a corrupt ``time``/``next_spawn`` scheduler
        intact.  That failure mode emits one note, fools the old watchdog, and then
        falls back into repeated one-note RECOVERY sections.  A fresh instance of the
        same native rhythm class is the smallest complete scheduler reset.
        """
        rhythm=getattr(getattr(self,"scene",None),"rhythm",None)
        if rhythm is None:
            return 0
        now=time.perf_counter()

        try:
            rebuilt=type(rhythm)()
        except Exception:
            rebuilt=None
        if rebuilt is None:
            return 0

        # Preserve earned/session state and configured difficulty, never scheduler
        # clocks, note queues, pause flags, or completion state.
        for field_name in (
            "intensity","combo","max_combo","duration",
            "base_bpm","bpm_range","target_bpm",
            "fall_time_base","fall_time_range",
            "window_mult","perfect_window_base","great_window_base",
            "good_window_base","perfect_window","great_window","good_window",
            "live_bpm_mult","live_window_mult","noise_level","decoy_spawn_mult"
        ):
            try:
                if hasattr(rhythm,field_name) and hasattr(rebuilt,field_name):
                    setattr(rebuilt,field_name,getattr(rhythm,field_name))
            except Exception:
                pass
        try:
            rebuilt.spawn_suppressed=False
            rebuilt.complete=False
            self.scene.rhythm=rebuilt
            rhythm=rebuilt
        except Exception:
            return 0

        count_in=1.10
        self._rhythm_recovery_release_at=now+count_in
        self._rhythm_recovery_started_at=now
        self._rhythm_recovery_reason=str(reason or "clog")
        self._rhythm_recovery_waiting_for_note=True
        self._rhythm_recovery_note_deadline=now+count_in+6.0
        self._rhythm_recovery_native_restart_pending=False
        self._rhythm_recovery_seen_note_ids=set()
        self._rhythm_recovery_required_notes=3
        self._rhythm_recovery_rebuild_attempts=int(
            getattr(self,"_rhythm_recovery_rebuild_attempts",0) or 0
        )+1
        return 1

    def _rhythm_seed_recovery_phrase(self, rhythm, count: int = 5) -> int:
        """Seed one complete native phrase after a scheduler rebuild.

        A single emergency note can prove that object construction works while
        leaving the chart permanently unplayable.  Use the engine's own spawner,
        then space five notes across successive beats so recovery visibly resumes
        as a phrase rather than another one-note RECOVERY section.
        """
        if rhythm is None:
            return 0
        try:
            rhythm.notes=[]
            rhythm.spawn_suppressed=False
        except Exception:
            return 0
        spawn=getattr(rhythm,"_spawn_note",None)
        if not callable(spawn):
            return 0
        beat=max(0.24,float(getattr(rhythm,"beat_duration",0.60) or 0.60))
        origin=float(getattr(rhythm,"time",0.0) or 0.0)+0.08
        made=[]
        for idx in range(max(4,int(count or 5))):
            before=len(list(getattr(rhythm,"notes",[]) or []))
            try:spawn()
            except Exception:break
            notes=list(getattr(rhythm,"notes",[]) or [])
            if len(notes)<=before:break
            note=notes[-1]
            try:
                note.spawn_time=origin+idx*beat*0.82
                note.y_pos=min(0.0,-0.18*idx)
                note.hit=False;note.missed=False;note.decoy=False
            except Exception:pass
            made.append(note)
        if len(made)>=4:
            try:
                rhythm.next_spawn=origin+len(made)*beat*0.82
                rhythm.complete=False
            except Exception:pass
            self._rhythm_recovery_force_flow_until=time.perf_counter()+max(4.0,len(made)*beat)
            self._rhythm_recovery_seen_note_ids={id(n) for n in made}
            return len(made)
        try:rhythm.notes=[]
        except Exception:pass
        return 0

    def _rhythm_note_watchdog(self, now: float) -> None:
        """Reset a clogged director, then wait for native top-entry cadence."""
        rhythm=getattr(getattr(self,"scene",None),"rhythm",None)
        if rhythm is None:
            return

        release_at=float(getattr(self,"_rhythm_recovery_release_at",0.0) or 0.0)
        if release_at>float(now):
            # Absolute count-in ownership: nothing may inject or retain notes while
            # recovery is clearing the malformed phrase.
            try: rhythm.notes=[]
            except Exception: pass
            self._last_live_note_seen_at=float(now)
            return
        if release_at>0.0:
            # Count-in ended. Seed a complete native phrase; one probe note is not
            # accepted as proof because that was the original silent-failure mode.
            self._rhythm_recovery_release_at=0.0
            try: rhythm.spawn_suppressed=False
            except Exception: pass
            seeded=self._rhythm_seed_recovery_phrase(rhythm,5)
            if seeded>=4:
                self._rhythm_recovery_waiting_for_note=False
                self._rhythm_recovery_note_deadline=0.0
                self._rhythm_recovery_rebuild_attempts=0
                self._forced_note_cadence_until=float(getattr(self,"_rhythm_recovery_force_flow_until",0.0) or 0.0)
                try:
                    self.scene.result_text=f"RHYTHM FLOW RESTORED — {seeded}-NOTE PHRASE"
                    self.scene.result_timer=1.35
                except Exception:pass
            self._last_live_note_seen_at=float(now)

        notes=list(getattr(rhythm,"notes",[]) or [])
        actionable=[n for n in notes if self._rhythm_note_is_actionable(n)]
        if actionable:
            self._last_live_note_seen_at=float(now)
            if bool(getattr(self,"_rhythm_recovery_waiting_for_note",False)):
                seen=getattr(self,"_rhythm_recovery_seen_note_ids",None)
                if not isinstance(seen,set):
                    seen=set()
                    self._rhythm_recovery_seen_note_ids=seen
                seen.update(id(n) for n in actionable)
                required=max(2,int(getattr(self,"_rhythm_recovery_required_notes",3) or 3))
                if len(seen)>=required:
                    self._rhythm_recovery_waiting_for_note=False
                    self._rhythm_recovery_note_deadline=0.0
                    self._rhythm_recovery_seen_note_ids=set()
                    self._forced_note_cadence_until=0.0
                    self._forced_note_failures=0
                    try:
                        self.scene.result_text="RHYTHM FLOW RESTORED"
                        self.scene.result_timer=0.9
                    except Exception:
                        pass
            return

        # A recovery receipt without a spawned note is a lie. If the freshly
        # rebuilt native director still produces nothing after its count-in and a
        # generous spawn window, rebuild it again rather than waiting through the
        # ordinary five-second dry detector.
        if bool(getattr(self,"_rhythm_recovery_waiting_for_note",False)):
            _deadline=float(getattr(self,"_rhythm_recovery_note_deadline",0.0) or 0.0)
            if _deadline>0.0 and float(now)>=_deadline:
                self._rhythm_recovery_waiting_for_note=False
                self._rhythm_recovery_note_deadline=0.0
                self._rhythm_recovery_seen_note_ids=set()
                attempts=int(getattr(self,"_rhythm_recovery_rebuild_attempts",0) or 0)
                if attempts<2 and self._rhythm_reset_full_pattern("director_rebuild_retry"):
                    self.pending_notifications.append("RHYTHM DIRECTOR REBUILD — COUNT IN")
                else:
                    seeded=self._rhythm_seed_recovery_phrase(rhythm,5)
                    if seeded>=4:
                        self._rhythm_recovery_rebuild_attempts=0
                        self.pending_notifications.append(f"RHYTHM FLOW RESTORED — {seeded}-NOTE PHRASE")
                    else:
                        self.pending_notifications.append("RHYTHM DIRECTOR FAILED — RETRYING SAFELY")
                        self._last_live_note_seen_at=float(now)-4.5
            return
        last=float(getattr(self,"_last_live_note_seen_at",0.0) or 0.0)
        if last<=0.0:
            self._last_live_note_seen_at=float(now)
            return
        # A true dry/clog window, not a momentary gap between authored phrases.
        if float(now)-last<5.0:
            return
        made=self._rhythm_reset_full_pattern("clog_reset")
        if made:
            self._last_live_note_seen_at=float(now)
            self._forced_note_failures=0
            self.pending_notifications.append("RHYTHM RECOVERY — CLEARING CLOG")
            try:
                self.scene.result_text="RHYTHM RESET — COUNT IN"
                self.scene.result_timer=1.1
            except Exception:
                pass
        else:
            self._forced_note_failures=int(getattr(self,"_forced_note_failures",0) or 0)+1
            self._last_live_note_seen_at=float(now)-4.5

    # ═══════════════════════════════════════════════════════════════════════
    # v10.9 — DIRECTOR-DRIVEN FINALE, GAME SIDE
