    def _update_director_finale(self, dt: float):
        """Per-frame sustain for finale / Soft_Glow_Anchor visuals. Non-modal."""
        try:
            now = time.perf_counter()
            if bool(getattr(self, "_finale_active", False)):
                if not bool(getattr(self, "_finale_plate_active", False)):
                    # fallback treatment only — the authored plate animates itself
                    self._finale_flash_t = float(getattr(self, "_finale_flash_t", 0.0) or 0.0) + dt
                    if self._finale_flash_t >= 2.5:
                        self._finale_flash_t = 0.0
                        try:
                            self.lightmap_renderer.trigger_flash(8, 0.35)
                        except Exception:
                            pass
                # mirror the director's 5-minute finale cap, game-side
                if now - float(getattr(self, "_finale_start_t", now) or now) > 300.0:
                    self._director_finale_stop()
            elif bool(getattr(self, "_aftercare_active", False)):
                age = now - float(getattr(self, "_aftercare_start_t", now) or now)
                if age > 90.0:
                    # afterglow fades; the night's normal grammar resumes
                    self._aftercare_active = False
                    try:
                        self.lightmap_renderer.set_undulation_profile("calm")
                    except Exception:
                        pass
                else:
                    # Soft_Glow_Anchor: a gentle warm pulse every ~4s
                    self._aftercare_flash_t = float(getattr(self, "_aftercare_flash_t", 0.0) or 0.0) + dt
                    if self._aftercare_flash_t >= 4.0:
                        self._aftercare_flash_t = 0.0
                        try:
                            self.lightmap_renderer.trigger_flash(5, 0.25)
                        except Exception:
                            pass
        except Exception:
            pass

